const BATCH_04_REVIEWS = {
  "bauhaus": { period: "1919–1933年", year: 1925, summary: "包豪斯是1919至1933年先后设于魏玛、德绍和柏林的德国学校，而非一套固定的红黄蓝几何风格。其不同阶段和教师在建筑、工坊、舞台、摄影、字体与基础课程上立场多样，共同问题是如何重组艺术、工艺、技术、教育与现代生产。", influencedBy: "德国工艺联盟、工艺美术教育、表现主义，以及风格派和构成主义等欧洲先锋交流", influenced: "现代设计教育、国际现代主义建筑、字体、摄影、家具与工业设计", related: ["constructivism", "de-stijl", "new-typography", "international-style-architecture", "swiss"], sources: BATCH_04_SOURCES.bauhaus, zh: ["构图随课程与媒介变化，可采用功能网格、非对称页面或清楚空间模块", "基础几何、材料构造、模块和功能部件，不把圆方三角当作唯一造型", "原色与黑白是部分课程和作品的系统，亦使用材料本色与摄影灰阶", "平面作品使用均匀综合色关系，建筑和物件保留真实环境光与投影", "纸张、印刷油墨、钢管、玻璃、木材、织物、摄影与可见构造", "仅在用户要求文字时使用清楚的几何或功能无衬线字体，避免伪造统一包豪斯字形"], en: ["composition varies by course and medium through functional grids, asymmetric pages, or clearly articulated spatial modules", "elementary geometry, material construction, modules, and functional components without treating circle-square-triangle as the only form", "primary colors and black-white in some teaching and work, alongside inherent material color and photographic gray", "even chromatic organization in graphics, with real ambient light and cast shadow for buildings and objects", "paper, printing ink, tubular steel, glass, timber, textile, photography, and visible construction", "only when text is requested, use clear geometric or functional sans serif lettering without inventing one universal Bauhaus typeface"] },
  "art-deco": { period: "约1920–1940年代", year: 1925, summary: "装饰艺术在1920至1940年代成为跨国建筑、室内、时尚、珠宝、交通工具和平面设计语言，名称后来因1925年巴黎现代装饰与工业艺术博览会而固定。阶梯几何、奢华材料与机器意象常见，但其路线可从手工豪华到流线量产，不能等同于黑金对称。", influencedBy: "立体主义和几何先锋、古代及非欧洲艺术的现代挪用、奢侈工艺、考古热与机器时代设计", influenced: "流线型现代主义、影院和商业建筑、消费品造型及后来的装饰艺术复兴", related: ["cubism", "art-nouveau", "streamline-moderne", "interwar-travel-poster"], sources: BATCH_04_SOURCES.artDeco, zh: ["轴线对称、阶梯轮廓、放射扇形或流线型水平组织随地区和阶段变化", "几何化植物、锯齿、日芒、流线体与精确装饰构件", "黑金和宝石色是豪华路线，亦可用铬银、粉彩、土色和材料本色", "锐利高光、分区照明或均匀商业展示光突出表面与轮廓", "抛光金属、漆、玻璃、木皮、石材、珐琅、印刷油墨与纺织物", "仅在用户要求文字时使用清楚的几何展示字，并按作品年代选择宽窄和装饰程度"], en: ["axial symmetry, stepped silhouettes, radiating fans, or streamlined horizontal organization varying by region and phase", "geometrized plants, zigzags, sunbursts, streamlined bodies, and precise decorative components", "black-gold and jewel tones for luxury branches, with chrome silver, pastels, earth color, and inherent materials elsewhere", "sharp highlights, zoned illumination, or even commercial display light emphasizing surface and contour", "polished metal, lacquer, glass, veneer, stone, enamel, printing ink, and textile", "only when text is requested, use clear geometric display lettering with width and ornament appropriate to the date"] },
  "surrealism": { period: "约1924–1940年代及其延续", year: 1930, summary: "超现实主义以布勒东1924年宣言为重要起点，是跨文学、绘画、摄影、电影、物件和展览的国际运动，探索潜意识、欲望、偶然与自动性。达利式精细梦境只是其中一路，自动绘画、拼贴、摄影实验和超现实物件同样关键。", influencedBy: "达达、精神分析、形而上绘画、象征主义、自动写作与第一次世界大战后的先锋文化", influenced: "抽象表现主义的自动技法、观念与行为实践、实验摄影电影及后来的幻想和广告图像", related: ["dada", "symbolism", "biomorphic", "abstract-expressionism", "surrealist-photography"], sources: BATCH_04_SOURCES.surrealism, zh: ["可用不可能空间、偶然拼合、自动性场域或物件陈列，不限定写实舞台", "精确硬边、流动生物形、摩擦转印、拼贴和现成物可按具体路线选择", "自然综合色、局部异色、自动绘画综合色或黑白摄影均可", "光线可冷静清晰、来源暧昧，也可由暗房、投影或真实展示环境产生", "平滑油彩、自动笔触、拼贴纸、摄影、现成物和实验印痕", "仅在用户要求文字时准确保留宣言、拼贴或作品文字，不使用通用奇幻字体"], en: ["impossible space, chance conjunction, automatic fields, or object display without requiring a realist dream stage", "precise hard edges, fluid biomorphism, frottage, collage, and found objects selected by the specific branch", "natural mixtures, selective chromatic shifts, automatic color, or black-white photography", "light may be cool and clear, ambiguously sourced, or produced by darkroom, projection, and real display conditions", "smooth oil paint, automatic marks, collage paper, photography, found objects, and experimental impressions", "only when text is requested, preserve manifesto, collage, or artwork wording accurately without generic fantasy typography"] },
  "mexican-muralism": { period: "约1920–1950年代", year: 1930, summary: "墨西哥壁画运动在1920年代革命后国家文化计划中兴起，以公共建筑中的壁画讨论革命、劳动、土地、原住民历史与国家身份。里维拉、奥罗斯科和西凯罗斯等人的政治立场、构图与技术并不相同，运动也不能化约为土红色英雄群像。", influencedBy: "墨西哥革命、公共教育政策、前西班牙时期艺术、殖民壁画、欧洲壁画传统与现代先锋", influenced: "美国新政壁画、社会现实主义、拉丁美洲公共艺术和后续政治壁画传统", related: ["social-realism", "realism", "soviet-propaganda-poster", "street-art"], sources: BATCH_04_SOURCES.mexicanMuralism, zh: ["建筑尺度的连续叙事、纪念群组、对角动力或多场景历史结构", "坚实体积、清楚轮廓、概括人物与因艺术家而异的表现性变形", "土红、赭黄、蓝绿和黑白常见，也使用综合色鲜明的现代工业颜料", "大面积明度分区服从远距阅读，并与建筑自然光或室内光协调", "湿壁画、灰泥、硅酸盐综合色、喷绘和实验工业材料", "仅在用户要求文字时使用准确可读的公共题铭或政治标语，不杜撰历史口号"], en: ["architectural-scale continuous narrative, monumental groups, diagonal force, or multiscene historical structure", "solid volume, clear contours, simplified figures, and artist-specific expressive distortion", "earth red, ochre, blue-green, and black-white alongside vivid modern industrial pigments", "large value zones designed for distance and coordinated with architectural daylight or interior light", "true fresco, plaster, silicate color, sprayed paint, and experimental industrial materials", "only when text is requested, use accurate legible public inscriptions or political slogans without inventing historical wording"] },
  "social-realism": { period: "约1920–1950年代", year: 1935, summary: "社会现实主义是20世纪尤其两次世界大战之间在多国出现的广义倾向，以劳动、贫困、不平等和政治冲突为题，并非风格统一的正式组织。它可采用绘画、壁画、版画、摄影与插图，也必须与国家规定、强调理想化社会主义建设的社会主义现实主义区分。", influencedBy: "19世纪现实主义、工人运动、经济危机、新闻与纪实文化、墨西哥壁画及不同国家的左翼艺术网络", influenced: "美国新政艺术、政治版画、纪实传统和后续社会介入艺术", related: ["realism", "mexican-muralism", "socialist-realism", "social-documentary-photography"], sources: BATCH_04_SOURCES.socialRealism, zh: ["群体行动、直接视点与社会环境形成可读叙事，也可采用孤立人物或纪实片段", "未经理想化的身体、具体劳动姿态和从写实到概括的轮廓", "综合色服从地点和媒介，土红、灰蓝、褐与有限强调色只是常见选择", "自然光、硬侧光或公共壁画明度分区保持情境信息可读", "油画、壁画、木刻或石版、摄影颗粒和廉价印刷纸", "仅在用户要求文字时使用准确可读的纪实、报刊或海报字体"], en: ["collective action, direct viewpoints, and social settings forming legible narrative, or isolated figures and documentary fragments", "unidealized bodies, specific working gestures, and contours ranging from naturalistic to simplified", "color follows place and medium, with earth red, gray-blue, brown, and limited accents only as common options", "natural light, hard sidelight, or mural-scale value zoning keeping contextual information readable", "oil painting, mural, woodcut or lithograph, photographic grain, and inexpensive printed paper", "only when text is requested, use accurate legible documentary, newspaper, or poster typography"] },
  "abstract-expressionism": { period: "约1943–1960年代", year: 1950, summary: "抽象表现主义约在1940年代至1960年代初以纽约为重要中心，包含行动绘画、色域倾向及形态各异的抽象实践。大尺幅和对制作过程的强调具有共性，但滴洒、无中心满幅和猛烈身体手势主要描述部分艺术家，不能概括罗斯科、纽曼等不同路线。", influencedBy: "欧洲现代抽象、超现实主义自动技法、美国现代艺术、移民艺术网络与第二次世界大战前后经验", influenced: "色域绘画、后绘画性抽象、极简和后极简的反应，以及后来的新表现主义", related: ["surrealism", "color-field", "post-painterly-abstraction", "minimalism", "neo-expressionism"], sources: BATCH_04_SOURCES.abstractExpressionism, zh: ["大尺幅画面可采用无中心满幅、集中综合色区、垂直区隔或开放边界", "滴流、挥洒、擦抹、宽阔综合色面和简化符号随艺术家路线变化", "综合色范围从高反差多色到有限深色或综合色场，不设统一综合色公式", "画面光由颜料明度、叠层和裸画布关系产生，不模拟固定摄影光源", "滴洒、厚涂、薄染、擦除、裸露画布与可见制作过程", "仅在用户要求文字时使用中性展签字体，不把字体嵌入非文字性画面"], en: ["large canvases may use decentered all-over structure, concentrated color zones, vertical divisions, or open boundaries", "drips, pours, scumbles, broad color areas, and reduced signs varying by artist and branch", "color ranges from high-contrast multicolor to restricted dark systems or fields, with no universal palette", "pictorial light emerges from pigment value, layering, and exposed canvas rather than a fixed photographic source", "dripping, impasto, staining, erasure, raw canvas, and visibly recorded making processes", "only when text is requested, use neutral label typography rather than embedding type in a nonverbal painted field"] },
  "color-field": { period: "约1948–1970年代", year: 1955, summary: "色域绘画约自1940年代末发展，以大尺幅综合色区、综合色关系和观看尺度弱化具象与显著手势。罗斯科的悬浮矩形、纽曼的纵向色带和后续浸染绘画差异很大；柔边、硬边、薄染与较厚涂层都可能出现。", influencedBy: "抽象表现主义、欧洲现代抽象，以及对崇高、综合色和大尺度观看的探索", influenced: "后绘画性抽象、华盛顿色彩画派、硬边绘画、极简主义和后续综合色装置", related: ["abstract-expressionism", "post-painterly-abstraction", "washington-color-school", "hard-edge-painting", "minimalism"], sources: BATCH_04_SOURCES.colorField, zh: ["大尺幅、低事件密度的连续综合色区、悬浮色块、条带或开放场", "描绘形体退居其次，边界可渗化、漂浮、笔直或保持画布形状", "有限综合色之间的明度、饱和度、温度和面积关系构成主体", "综合色自身产生发光、吸收或平面张力，不依赖自然光源模拟", "薄染裸画布、叠层油彩、均匀哑光或精确硬边表面", "仅在用户要求文字时使用画面之外的中性、克制展签字体"], en: ["large-scale low-event fields, floating color zones, bands, or open chromatic expanses", "descriptive form recedes while boundaries may stain, float, remain straight, or follow the canvas shape", "value, saturation, temperature, and area relationships among limited colors form the subject", "color itself produces luminosity, absorption, or planar tension without simulating a natural light source", "stained raw canvas, layered oil, uniform matte paint, or precisely hard-edged surfaces", "only when text is requested, use neutral restrained label typography outside the painted field"] },
  "pop-art": { period: "约1950年代中期–1970年代", year: 1962, summary: "波普艺术于1950年代中期先在英国、继而在1960年代美国等地发展，以广告、漫画、商品、明星和大众传播研究消费文化与图像复制。粗黑轮廓、原色和网点主要对应部分漫画式作品；摄影丝网、雕塑、拼贴和冷静复制同样关键。", influencedBy: "大众传媒、广告和消费文化、达达现成品与拼贴，以及英国独立小组等战后讨论", influenced: "后现代主义、观念与挪用艺术、新波普和多种商业—艺术跨界实践", related: ["dada", "photorealism", "conceptual-art", "postmodernism", "neo-pop"], sources: BATCH_04_SOURCES.popArt, zh: ["广告式裁切、重复模块、商品陈列、漫画格或媒体拼贴随具体路线选择", "机械复制轮廓、放大日常物、摄影转印和工业化雕塑形体", "商业印刷原色、高纯度综合色、摄影综合色或消费品固有综合色", "平面复制光、影棚商品光或展厅环境光，避免统一戏剧照明", "丝网印刷、半调网点、丙烯、拼贴、搪瓷、塑料和工业制作表面", "仅在用户要求文字时准确保留商品、漫画或媒体文字及其引用关系"], en: ["advertising crop, repeated modules, product display, comic panels, or media collage selected by the specific branch", "mechanically reproduced contours, enlarged everyday objects, photographic transfer, and industrially fabricated sculpture", "commercial primaries, saturated color, photographic color, or the inherent colors of consumer goods", "flat reproductive light, studio product light, or gallery ambient light without one dramatic formula", "screenprint, halftone dots, acrylic, collage, enamel, plastic, and industrial fabrication", "only when text is requested, preserve product, comic, or media wording accurately and make its quoted status clear"] },
  "op-art": { period: "约1950年代中期–1970年代", year: 1965, summary: "欧普艺术约在1950年代中期至1970年代通过精确综合色和几何关系激活观看过程，1965年MoMA的《The Responsive Eye》展览推动其名称普及。黑白振动和莫尔纹只是部分方法，综合色相互作用、渐变、曲面与观看移动也同样重要。", influencedBy: "构成主义、包豪斯和几何抽象的综合色研究、视觉心理与知觉科学", influenced: "动力与参与式艺术、综合色和图案设计、时尚及后来的数字视觉实验", related: ["geometric-abstraction", "kinetic-art", "hard-edge-painting", "psychedelic"], sources: BATCH_04_SOURCES.opArt, zh: ["满幅重复、渐变网格、图底反转和随观看位置激活的视觉场", "线距、密度、曲率、尺度与几何模块的连续变化", "黑白极端对比、互补综合色振动或精确综合色渐变", "完全平面图像光，运动与纵深由视觉系统而非真实投影产生", "锐利硬边、平滑颜料、精确印刷、塑料或反射材料", "仅在用户要求文字时使用画面之外的中性字体，避免损坏知觉结构"], en: ["all-over repetition, graded grids, figure-ground reversal, and fields activated by viewer position", "continuous variation of spacing, density, curvature, scale, and geometric modules", "extreme black-white contrast, complementary color vibration, or precise chromatic gradients", "fully flat pictorial illumination with motion and depth produced by perception rather than cast shadow", "razor-sharp edges, smooth paint, precise print, plastic, or reflective material", "only when text is requested, use neutral typography outside the work without disrupting its perceptual structure"] },
  "kinetic-art": { period: "约1920年代末至今，1950–60年代集中发展", year: 1960, summary: "动力艺术把真实运动、机械驱动、空气作用、光变化或观众参与作为作品结构；其先例可追溯到20世纪早期，1950至1960年代集中发展。它不同于未来主义在静态图像中描绘速度，也不限于悬挂式活动雕塑。", influencedBy: "构成主义和达达的机械实验、莫霍利—纳吉、考尔德等先例，以及战后技术和参与式艺术", influenced: "欧普艺术、光与空间、互动装置、机械与电子艺术", related: ["constructivism", "op-art", "zero-group", "light-and-space"], sources: BATCH_04_SOURCES.kineticArt, zh: ["真实运动、观看路径、悬置平衡或光序列共同形成时间结构", "可动杆件、旋转模块、机械装置、空气驱动部件或变化光形", "材料本色、黑白和有限强调色，也可由光产生综合色变化", "环境光、移动投影、反射和装置自发光随时间改变", "金属、塑料、线材、电机、灯具与清楚可见的活动连接", "仅在用户要求文字时使用置于运动结构之外的简洁技术字体"], en: ["real movement, viewing paths, suspended balance, or light sequences forming temporal structure", "movable rods, rotating modules, mechanisms, air-driven components, or changing light forms", "inherent material color, black-white, and limited accents, with color also produced by light", "ambient light, moving cast shadows, reflection, and self-luminous devices changing over time", "metal, plastic, wire, motors, lamps, and clearly articulated moving joints", "only when text is requested, use concise technical typography outside the moving structure"] },
  "minimalism": { period: "约1960年代初–1970年代", year: 1966, summary: "极简主义约在1960年代美国形成，强调物体的字面存在、简单几何、系列重复、工业制造及作品与展场和观者身体的关系。“少即是多”式视觉简洁不足以界定它，单色、留白和无痕表面也不是所有作品的必要条件。", influencedBy: "构成主义、包豪斯与现代抽象，同时反对抽象表现主义的主观手势和构图中心", influenced: "观念艺术、后极简主义、装置艺术及现代雕塑对场地和观者的关注", related: ["constructivism", "abstract-expressionism", "conceptual-art", "post-minimalism", "light-and-space"], sources: BATCH_04_SOURCES.minimalism, zh: ["基本单元的系列排列、重复间隔与作品—展场—观者的实际空间关系", "简单几何、标准构件、清楚尺度和非表现性工业连接", "单色、材料本色或有限综合色，综合色不承担叙事象征的必要任务", "展厅环境光与真实投影揭示物体、间隔、反射和观看移动", "钢、铝、荧光灯、胶合板、砖、玻璃纤维及工业制作表面", "仅在用户要求文字时使用中性展签或制造标记，不把排版当作极简主义本体"], en: ["serial units, repeated intervals, and real spatial relations among work, gallery, and viewer", "simple geometry, standard components, explicit scale, and nonexpressive industrial joints", "monochrome, inherent material color, or limited color without requiring symbolic narrative", "gallery ambient light and real cast shadow revealing object, interval, reflection, and viewer movement", "steel, aluminum, fluorescent light, plywood, brick, fiberglass, and industrial fabrication", "only when text is requested, use neutral labels or fabrication marks without treating typography as Minimalism itself"] },
  "fluxus": { period: "约1962–1978年及其延续", year: 1965, summary: "激浪派约自1962年围绕乔治·马丘纳斯组织的跨国网络发展，以事件谱、表演、出版物、盒装作品、邮寄和日常行动削弱艺术与生活、作者与观众、作品与过程的界线。它没有统一视觉风格，也不能只由说明卡和黑字白纸代表。", influencedBy: "达达、杜尚、实验音乐尤其约翰·凯奇、具体诗、偶发艺术与跨国艺术家网络", influenced: "观念艺术、行为艺术、艺术家书、邮寄艺术和参与式实践", related: ["dada", "conceptual-art", "performance-art", "video-art"], sources: BATCH_04_SOURCES.fluxus, zh: ["事件顺序、说明谱、日常行动、盒装档案或现场关系按作品需要组织", "简单动作、现成物、非纪念尺度、可重复规则与偶然结果", "纸张和物件本色、黑字或偶发综合色，不设统一品牌综合色", "普通现场、舞台或展示光，避免为非戏剧事件添加电影式塑形", "印刷卡、邮寄物、木盒、日常物、胶带、录音录像与使用痕迹", "文字常是作品本体；必须准确、可执行且保留原始指令层级"], en: ["event sequence, score, everyday action, boxed archive, or live relation organized according to the work", "simple actions, found objects, nonmonumental scale, repeatable rules, and chance outcomes", "paper and object color, black type, or incidental color without one branded palette", "ordinary site, stage, or display light without cinematic modeling imposed on nondramatic events", "printed cards, mail, wooden boxes, everyday objects, tape, audio-video records, and use wear", "text is often the work itself and must remain accurate, executable, and faithful to the original instruction hierarchy"] },
  "conceptual-art": { period: "约1960年代中期–1970年代及其延续", year: 1970, summary: "观念艺术约在1960年代中期至1970年代集中发展，把观念、命题、语言、指令或制度语境置于传统艺术物件之前。它并不必然去物质化，也没有统一的黑白档案风格；照片、文本、地图、证书、行动、物件和机构介入都可成为作品。", influencedBy: "杜尚和达达现成品、极简主义、语言哲学、激浪派及对艺术制度和商品物件的质疑", influenced: "制度批判、装置、行为、社会实践、研究型艺术及当代跨媒介创作", related: ["dada", "minimalism", "fluxus", "performance-art", "land-art", "video-art"], sources: BATCH_04_SOURCES.conceptualArt, zh: ["呈现结构由命题决定，可用序列、档案、地图、现场介入或几乎无视觉对象", "语言、指令、照片、现成物、测量和制度关系取代统一造型语言", "综合色通常服从记录和载体，黑白灰不是必要条件", "档案光、现场环境光、投影或屏幕光按作品的证据结构选择", "纸张、照片、复印件、证书、地图、物件、声音、录像与临时材料", "文字可能是作品核心，必须准确、完整、可读并保留引用和指令关系"], en: ["presentation follows the proposition through sequence, archive, map, site intervention, or almost no visual object", "language, instructions, photographs, found objects, measurement, and institutional relations replace one formal vocabulary", "color follows documentation and support, with black-white-gray never required", "archival light, site ambient light, projection, or screen light selected by the work's evidentiary structure", "paper, photographs, photocopies, certificates, maps, objects, sound, video, and temporary materials", "text may be the core work and must remain accurate, complete, legible, and faithful to quotation and instruction relations"] },
  "performance-art": { period: "约1960年代至今", year: 1975, summary: "行为艺术约自1960年代成为重要术语，以身体、动作、时间、现场、观众和记录构成作品，可发生在美术馆、街道或私人空间。它不等同于戏剧表演，也不能以极端身体行为概括舞蹈式、仪式式、日常式、社会参与式等不同实践。", influencedBy: "未来主义和达达演出、包豪斯舞台、实验音乐、偶发艺术、激浪派及视觉艺术对物件边界的突破", influenced: "身体艺术、录像艺术、参与式和社会实践，以及当代现场和网络行为", related: ["fluxus", "conceptual-art", "body-art", "video-art", "happening"].filter(Boolean), sources: BATCH_04_SOURCES.performanceArt, zh: ["身体、时间、观众距离、动作顺序与现场边界共同组织事件", "姿态、重复、耐力、日常行动、仪式或参与规则按具体作品选择", "现场综合色、服装与物件本色或概念性强调色，不设统一配色", "使用现场可用光、舞台功能光或记录设备光，并说明其文献属性", "身体、服装、日常物、场地痕迹、声音及照片录像文献", "仅在作品需要时使用准确的标题、指令、时间或现场说明文字"], en: ["body, duration, audience distance, action sequence, and site boundary jointly organize the event", "gesture, repetition, endurance, everyday action, ritual, or participatory rules selected by the specific work", "site color, clothing and object color, or conceptual accents without one required palette", "available site light, functional stage light, or recording-device light with its documentary status kept clear", "body, clothing, everyday objects, site traces, sound, and photographic or video documentation", "only when the work requires it, use accurate titles, instructions, duration, or site information"] },
  "land-art": { period: "约1960年代末–1970年代及其延续", year: 1970, summary: "大地艺术约在1960年代末至1970年代集中出现，把地形、地质、距离、时间、侵蚀和场地进入作品结构，并常通过照片、地图、文字或影片传播。巨型螺旋和土石工程只是其中一路，小尺度行走、暂时痕迹与生态取向也不应被忽略。", influencedBy: "极简和观念艺术、对画廊与艺术市场的质疑、场域意识，以及景观、地质和环境讨论", influenced: "场域特定艺术、环境艺术、生态艺术及当代公共景观实践", related: ["minimalism", "conceptual-art", "environmental-art", "arte-povera"], sources: BATCH_04_SOURCES.landArt, zh: ["作品沿真实地形、行走路径、切口、堆移或远距视线组织场地关系", "几何土方、重复行走、临时标记与自然过程依具体作品变化", "土、石、水和植被本色随天气与季节改变，不套用统一土色滤镜", "真实日照、天气、时间和地平线决定光线，并保留其变化证据", "土、石、水、植被、侵蚀、施工痕迹，以及地图、照片和影片文献", "仅在需要时使用准确的地点、尺度、时间和行走说明，不让文字替代场地"], en: ["real terrain, walking paths, cuts, displacement, or distant sight lines organize site relations", "geometric earthworks, repeated walking, temporary marks, and natural processes varying by work", "inherent earth, stone, water, and vegetation color changing with weather and season without a uniform earth-tone filter", "real sunlight, weather, duration, and horizon determine illumination, with evidence of change retained", "earth, stone, water, vegetation, erosion, construction traces, maps, photographs, and film documentation", "only when needed, use accurate location, scale, duration, and walking information without replacing the site with text"] },
  "video-art": { period: "约1960年代中期至今", year: 1975, summary: "录像艺术约自1960年代中期便携录像设备普及后发展，以电子时间、实时反馈、单频道、闭路电视、多屏装置和影像处理区别于以院线叙事为中心的电影。CRT雪花和低清模拟色只属于部分历史阶段，数字录像与投影同样属于其延续。", influencedBy: "实验电影、电视广播、激浪派、行为和观念艺术，以及便携录像和电子合成技术", influenced: "媒体装置、数字影像、网络艺术、监控批评及当代移动影像", related: ["fluxus", "conceptual-art", "performance-art", "sound-art", "digital-art"].filter(Boolean), sources: BATCH_04_SOURCES.videoArt, zh: ["单频道、多屏、闭路反馈、循环时序或设备—观众关系组织观看", "电子扫描、实时画面、剪辑、重复动作、反馈与信号处理", "黑白、模拟综合色偏移、广播综合色或数字屏幕综合色按技术阶段选择", "屏幕自发光、投影反射、展厅暗部和电子过曝构成实际光环境", "CRT、磁带、摄像机、监视器、投影、数字文件、压缩和信号噪声", "仅在作品需要时准确呈现时间码、字幕、信号文字或设备信息"], en: ["single-channel, multiscreen, closed-circuit feedback, looped duration, or device-viewer relations organize viewing", "electronic scan, live image, editing, repeated action, feedback, and signal processing", "black-white, analog color shift, broadcast color, or digital screen color selected by technological period", "screen emission, projected reflection, gallery darkness, and electronic overexposure form the actual light environment", "CRT, tape, camera, monitor, projection, digital file, compression, and signal noise", "only when the work requires it, present timecode, captions, signal text, or device information accurately"] },
  "photorealism": { period: "约1960年代末–1980年代及其延续", year: 1972, summary: "照相写实主义约在1960年代末至1970年代的美国形成，以照片为中介，通过投影、网格、喷笔或精密描绘研究相机观看、反射和日常都市表面。它不是单纯追求“像照片”，也应与后来更强调感官过度和尺度放大的超写实主义区分。", influencedBy: "摄影、波普艺术的日常和消费图像，以及对抽象表现主义手势和传统写生的反应", influenced: "超写实主义、商业插画及摄影与绘画边界的后续讨论", related: ["realism", "pop-art", "hyperrealism"], sources: BATCH_04_SOURCES.photorealism, zh: ["摄影式裁切、镜头视点、街景或物件的反射层级和景深线索", "严格透视、比例转译、边缘清晰度与相机造成的局部失焦", "照片来源的自然综合色、综合色偏差、铬金属反射和准确中性色", "日光或商品环境光按照片记录呈现高光、反射和投影", "无痕油彩或丙烯、喷笔过渡、投影或网格转描与光滑画面", "仅在用户要求文字时准确保留照片中的招牌和品牌文字，避免杜撰"], en: ["photographic cropping, lens viewpoint, reflected layers in streets or objects, and depth-of-field cues", "rigorous perspective and proportional transfer, edge sharpness, and camera-derived selective blur", "source-photograph natural color, photographic casts, chrome reflections, and accurate neutrals", "daylight or commercial ambient light preserving recorded highlights, reflections, and cast shadows", "seamless oil or acrylic, airbrush transitions, projection or grid transfer, and a smooth painted surface", "only when text is requested, preserve signs and brand wording from the source photograph accurately without invention"] },
  "postmodernism": { period: "约1970年代–1990年代", year: 1980, summary: "后现代主义自1970年代成为艺术、建筑和设计中的宽泛批判框架，质疑现代主义的普遍性、原创性和媒介纯粹性，运用引用、挪用、戏仿、通俗文化与身份政治。它不是一套折衷综合色和混排字体风格，不同领域也有各自时间线和争论。", influencedBy: "波普与观念艺术、符号学和后结构主义、女权与后殖民批评，以及对现代主义制度和形式正统的反思", influenced: "挪用艺术、图片一代、后现代建筑与设计，以及1990年代以后多元跨媒介实践", related: ["pop-art", "conceptual-art", "pictures-generation", "appropriation-art", "postmodern-architecture", "memphis"], sources: BATCH_04_SOURCES.postmodernism, zh: ["结构由引用和批评目的决定，可分层、并置、序列化或采用传统构图", "历史语汇、现代几何、媒体图像、复制品和身份符号以明确语境重组", "综合色可引用任何来源；不协调强调色只是部分设计路线而非必要条件", "光线服从被引用媒介、摄影、展场或建筑环境，不设统一视觉效果", "复制图像、照片、录像、工业材料、装饰表面、历史构件和数字媒介", "文字可能是引用或批评核心，必须准确标示来源、层级和反讽关系"], en: ["structure follows the work's citational and critical purpose through layering, juxtaposition, sequence, or conventional composition", "historical vocabularies, modern geometry, media images, copies, and identity signs recontextualized with explicit purpose", "color may quote any source; discordant accents define only some design branches and are not required", "light follows the cited medium, photograph, gallery, or architectural environment without one visual effect", "reproduced images, photography, video, industrial materials, ornamental surfaces, historical elements, and digital media", "text may be central to quotation or critique and must identify sources, hierarchy, and ironic relations accurately"] }
};

