const BATCH_05_REVIEWS = {
  "swiss": { period: "约1950–1960年代及其延续", year: 1955, summary: "瑞士国际主义又称国际字体风格，约在1950年代由瑞士和德国的平面设计实践系统化，以非对称网格、无衬线字体、摄影和清晰信息层级追求可复制的视觉沟通。它不是只有左对齐、Helvetica和红黑白；不同设计师的网格、字体与综合色使用并不相同。", influencedBy: "新字体运动、包豪斯、构成主义、现代摄影和瑞士战前设计教育", influenced: "国际企业识别、公共信息系统、编辑设计和数字产品中的网格与信息层级", related: ["bauhaus", "constructivism", "new-typography", "international-corporate-identity", "new-wave-typography"], sources: BATCH_05_SOURCES.swiss, zh: ["模数网格、非对称对齐和清楚阅读顺序，网格可见或隐含", "摄影、几何形、规则线和功能性图像形成精确关系", "黑白红是常见方案之一，也使用全综合色摄影、蓝黄或其他受控综合色", "平面印刷光与摄影原有光线并置，不添加装饰性立体光效", "精确胶印、摄影网点、哑光纸、清楚裁切和有限印刷误差", "仅在用户要求文字时使用准确可读的无衬线字体、左齐或按信息需要对齐"], en: ["modular grids, asymmetric alignment, and a clear reading order with the grid visible or implicit", "photography, geometry, rules, and functional imagery held in precise relation", "black-white-red as one common option alongside full-color photography, blue-yellow, and other controlled palettes", "flat printed illumination combined with the source photograph's light without decorative dimensional effects", "precise offset print, photographic halftone, matte paper, clean trimming, and limited production error", "only when text is requested, use accurate legible sans serif type aligned left or as required by the information"] },
  "mid-century-modern": { period: "约1940年代中期–1960年代末", year: 1955, summary: "“中世纪现代主义”是后来用于概括约1940年代中期至1960年代末建筑、家具、室内和平面设计的宽泛标签，尤其常指美国战后现代生活。它不是当时统一自称的运动，也不必然使用芥末黄、青绿、原子图案或复古插画。", influencedBy: "国际现代主义、包豪斯移民网络、斯堪的纳维亚设计、战时技术与战后工业和住宅生产", influenced: "战后住宅、家具和企业设计，并在20世纪末以来形成持续复兴和收藏文化", related: ["bauhaus", "scandinavian-modern", "atomic-age", "international-style-architecture"], sources: BATCH_05_SOURCES.midCentury, zh: ["开放平面、非对称平衡、清楚功能分区或家具与建筑的整体关系", "简化几何与有机曲线、细脚结构、轻巧悬挑和人体尺度", "综合色随材料与地区变化，木色、中性色和明快强调色均可出现", "自然日光和室内功能光揭示空间、结构和材料，不套用复古综合色滤镜", "木材、胶合板、钢、玻璃、塑料、砖、织物及工业和手工结合表面", "仅在用户要求文字时使用清楚的时代无衬线或展示字体，避免通用复古字"], en: ["open plans, asymmetric balance, clear functional zones, or integrated relations among furniture and architecture", "simplified geometry and organic curves, slender legs, light cantilevers, and human scale", "color varies by material and region, including wood tones, neutrals, and bright accents", "natural daylight and functional interior light revealing space, structure, and material without a retro color filter", "timber, plywood, steel, glass, plastic, brick, textile, and combined industrial-handcrafted surfaces", "only when text is requested, use clear period sans serif or display lettering without generic retro type"] },
  "scandinavian-modern": { period: "约1930–1970年代", year: 1955, summary: "斯堪的纳维亚现代设计约在1930至1970年代获得国际影响，涵盖丹麦、芬兰、瑞典、挪威和冰岛彼此不同的建筑、家具、玻璃、陶瓷和纺织传统。人本功能、材料感和可负担性是重要议题，但“浅木、白墙、柔光”是后来的简化商品形象。", influencedBy: "北欧工艺与民族浪漫传统、功能主义、现代工业、社会民主公共建设和各国材料文化", influenced: "国际家具、家居和公共设计，以及后来的可持续、人本和生活方式设计", related: ["bauhaus", "mid-century-modern", "organic-architecture", "minimalism"], sources: BATCH_05_SOURCES.scandinavian, zh: ["低密度功能布局、人体尺度与物件之间清楚使用关系", "从有机弯木到严格几何的多样形体，连接和结构保持可读", "浅木与中性色常见，但深木、强综合色、图案织物和玻璃综合色同样存在", "自然漫射光和功能照明呈现表面、使用场景与季节性环境", "实木、胶合板、皮革、羊毛、玻璃、陶瓷和金属的真实材料差异", "仅在用户要求文字时使用朴素可读的功能字体，不把排版当作地区本质"], en: ["low-density functional arrangements, human scale, and explicit use relations among objects", "forms ranging from organic bentwood to strict geometry with legible joints and structure", "pale wood and neutrals are common, while dark wood, strong color, patterned textile, and colored glass also occur", "diffuse daylight and functional illumination revealing surfaces, use, and seasonal environment", "solid timber, plywood, leather, wool, glass, ceramic, and metal with distinct material character", "only when text is requested, use plain legible functional lettering without treating typography as a regional essence"] },
  "streamline-moderne": { period: "约1930–1940年代", year: 1935, summary: "流线型现代主义是装饰艺术在1930至1940年代强调空气动力学、速度和量产形象的分支，横跨建筑、车辆、家电和商品设计。水平线带、圆角和光滑表面常见，但真实功能、象征性“流线化”和不同材料之间应加以区分。", influencedBy: "装饰艺术、空气动力学研究、交通工具工程、工业设计和大萧条时期的消费营销", influenced: "战后交通与家电设计、中世纪现代主义及后来的复古未来视觉", related: ["art-deco", "mid-century-modern", "atomic-age", "streamline-moderne-architecture"], sources: BATCH_05_SOURCES.streamline, zh: ["拉长水平轴、连续线带、圆角转折和前后收束的速度轮廓", "水滴形、圆鼻、包覆壳体、齐平开口和流畅连接", "奶油白、海军蓝、铬银及材料本色，配色并非固定三色", "连续高光和环境反射强调曲面，建筑使用真实日照和凹口阴影", "搪瓷钢、铝、铬、玻璃、烤漆、塑料和光滑灰泥", "仅在用户要求文字时使用圆润而可读的几何或工业展示字体"], en: ["elongated horizontal axes, continuous bands, rounded turns, and tapered speed-oriented silhouettes", "teardrop forms, rounded noses, enclosing shells, flush openings, and smooth joints", "cream, navy, chrome silver, and inherent material color without a fixed three-color formula", "continuous highlights and ambient reflections describing curves, with real daylight and recess shadows in architecture", "enameled steel, aluminum, chrome, glass, lacquer, plastic, and smooth stucco", "only when text is requested, use rounded legible geometric or industrial display lettering"] },
  "atomic-age": { period: "约1945–1965年", year: 1957, summary: "原子时代设计约在1945至1965年把核科学、分子图示、卫星和太空想象带入建筑、家具、纺织、广告与娱乐。它同时包含战后乐观、冷战竞争和核焦虑，不能只描述为轻快消费乐观，也不应把1957年后的太空竞赛倒推到全部时期。", influencedBy: "核时代科学传播、中世纪现代主义、冷战、战后消费生产，以及1957年后加速的太空竞赛", influenced: "太空时代设计、Googie建筑、科幻视觉和后来的复古未来主义", related: ["mid-century-modern", "streamline-moderne", "googie-architecture", "retrofuturism"], sources: BATCH_05_SOURCES.atomic, zh: ["非对称爆发、轨道环、分子节点和尺度跳变组织图案或产品轮廓", "星芒、回旋镖、球体、锥体、卫星和拟科学线形", "青绿、珊瑚、芥末黄、黑白和金属色为常见但非固定综合色", "平面广告光、商品高光或建筑霓虹与夜间环境光", "丝网和胶印颗粒、塑料、铝、玻璃纤维、层压板与霓虹", "仅在用户要求文字时使用准确可读的时代展示字体，不伪造科学标注"], en: ["asymmetric bursts, orbital rings, molecular nodes, and scale jumps organizing pattern or product silhouette", "starbursts, boomerangs, spheres, cones, satellites, and pseudo-scientific line forms", "teal, coral, mustard, black-white, and metallic color as common but nonmandatory choices", "flat advertising light, product highlights, or architectural neon within a night environment", "screenprint and offset grain, plastic, aluminum, fiberglass, laminate, and neon", "only when text is requested, use accurate legible period display type without fabricated scientific labels"] },
  "architectural-brutalism": { period: "约1950–1975年及其延续", year: 1965, summary: "建筑粗野主义约在1950至1970年代发展，名称与法语 béton brut 及英国新粗野主义讨论相关，重视材料、结构、服务系统和社会用途的直接表达。清水混凝土很常见，但砖、钢、玻璃和粗糙砌体也可使用；它也并非天然等同于压迫性巨构。", influencedBy: "战前现代主义、勒·柯布西耶的晚期建筑、战后重建、公共机构与英国新粗野主义论述", influenced: "晚期现代建筑、高技派和当代清水混凝土建筑，并为数字“粗野主义”提供名称参照", related: ["bauhaus", "international-style-architecture", "high-tech-architecture", "brutalism"], sources: BATCH_05_SOURCES.architecturalBrutalism, zh: ["体量、交通、结构和功能单元清楚表达，可巨型也可保持紧凑公共尺度", "厚重构件、深凹开口、悬挑、重复模块和外露服务或结构", "综合色主要来自混凝土、砖、钢、玻璃和风化，不强制灰色单色", "真实日照、阴天漫射与深凹投影显示材料和体量关系", "清水混凝土模板纹、砖、粗石、钢、玻璃及可见接缝和风化", "仅在用户要求文字时使用清楚建筑标识，不以超大系统字替代建筑特征"], en: ["massing, circulation, structure, and functional units made explicit at monumental or compact civic scale", "heavy components, deep openings, cantilevers, repeated modules, and exposed services or structure", "color arising from concrete, brick, steel, glass, and weathering rather than mandatory gray monochrome", "real daylight, overcast diffusion, and deep recess shadows revealing material and mass relations", "board-marked concrete, brick, rough stone, steel, glass, visible joints, and weathering", "only when text is requested, use clear architectural signage without substituting oversized system type for architectural character"] },
  "brutalism": { period: "约2010年代至今", year: 2016, summary: "数字或网页粗野主义约在2010年代成为非正式设计标签，借用建筑粗野主义之名，以默认字体、裸露结构、直接链接、强边框或故意不精致的界面反对模板化商业网页。它不是建筑粗野主义的直接延续，也与反设计有交集但不能完全等同。", influencedBy: "早期网页的默认界面、朋克和DIY出版、现代主义系统设计，以及对高度模板化商业UX的反应", influenced: "实验网页、独立文化平台和当代反设计趋势，同时也被商业品牌吸收", related: ["architectural-brutalism", "punk-visual", "swiss", "antidesign", "y2k"].filter(Boolean), sources: BATCH_05_SOURCES.digitalBrutalism, zh: ["裸露页面结构、直接信息区块、强边界或故意破坏常规网格", "浏览器默认控件、硬切矩形、未装饰链接和显式系统构件", "默认网页综合色、黑白、高对比或荧光强调，不设统一配色", "通常无装饰光效，界面层级由边界、尺寸和浏览器状态表达", "HTML默认外观、低加工位图、粗边框、重复背景和可见系统状态", "文字和链接是功能核心，必须可读、可访问且不以混乱损害操作"], en: ["exposed page structure, direct information blocks, hard boundaries, or deliberate disruption of conventional grids", "browser-default controls, hard rectangles, unornamented links, and explicit system components", "default web colors, black-white, high contrast, or fluorescent accents without one required palette", "usually no decorative lighting, with hierarchy expressed by boundaries, scale, and browser state", "default HTML appearance, low-processing bitmaps, heavy borders, repeated backgrounds, and visible system states", "text and links are functional core elements and must remain legible and accessible rather than confusing interaction"] },
  "new-wave-typography": { period: "约1970年代末–1980年代", year: 1980, summary: "新浪潮字体设计约在1970年代末至1980年代由沃尔夫冈·魏因加特在瑞士教学中的实验及美国设计师进一步发展，扭转国际字体风格的中性秩序。斜向、层叠、不同字距和摄影拼合常见，但它是在网格知识上扩展阅读路径，而非任意破坏可读性。", influencedBy: "瑞士国际字体风格、魏因加特的教学实验、摄影制版技术、朋克和后现代设计", influenced: "实验编辑、音乐文化、解构排版和早期数字字体设计", related: ["swiss", "punk-visual", "postmodernism", "grunge-design"], sources: BATCH_05_SOURCES.newWave, zh: ["斜向轴、层叠信息、越界元素和可变阅读路径建立受控张力", "文字块、规则线、摄影和几何形通过缩放、旋转与叠印关联", "黑白、高饱和强调和综合色摄影按信息层级组织", "平面印刷综合色与摄影明暗并置，半透明叠印形成综合色变化", "胶印网点、复印、半透明叠层、套印偏差和纸面颗粒", "文字是主要结构；字号、字距、行距和方向可变但必须维持可辨阅读层级"], en: ["diagonal axes, layered information, edge-crossing elements, and variable reading paths creating controlled tension", "type blocks, rules, photography, and geometry related through scale, rotation, and overprinting", "black-white, saturated accents, and color photography organized by information hierarchy", "flat printed color and photographic tone combined with transparent overprint color shifts", "offset halftone, photocopy, translucent layers, registration shift, and paper grain", "type is the primary structure; scale, spacing, leading, and direction may vary while preserving a discernible reading hierarchy"] },
  "memphis": { period: "1981–1988年（团体活动期）", year: 1983, summary: "孟菲斯集团1981年在米兰成立，1988年解散，以家具、灯具、陶瓷和室内设计中的鲜明综合色、塑料层压板、图案与反功能主义姿态挑战现代主义“良好品味”。它不是一种粉彩平面背景，作品也常包含黑白、强原色和坚硬不舒适的造型。", influencedBy: "意大利激进设计、波普艺术、装饰艺术、后现代建筑和大众消费材料", influenced: "1980年代后现代产品和平面设计，以及后来的新孟菲斯、玩具和数字图形复兴", related: ["italian-radical-design", "postmodernism", "pop-art", "art-deco", "neo-pop"], sources: BATCH_05_SOURCES.memphis, zh: ["不对称物件组合、舞台式陈列和图案与结构的故意冲突", "基础几何、曲线、锯齿、点阵和比例夸张的家具构件", "强原色、粉彩、黑白和彩色材料碰撞，不限定高明度粉彩", "均匀商品或展览光突出轮廓、层压板和光泽材料", "塑料层压板、彩色金属、陶瓷、玻璃、木材和印刷图案", "仅在用户要求文字时使用玩味但可读的几何展示字体，不把字体当成集团核心"], en: ["asymmetric object groupings, stage-like display, and deliberate conflict between pattern and structure", "elementary geometry, curves, zigzags, dots, and furniture components with exaggerated proportion", "strong primaries, pastels, black-white, and colored materials in collision without requiring high-key pastel", "even product or exhibition light revealing silhouettes, laminate, and glossy materials", "plastic laminate, colored metal, ceramic, glass, timber, and printed pattern", "only when text is requested, use playful but legible geometric display type without treating typography as the group's core"] },
  "punk-visual": { period: "约1970年代中期–1980年代及其延续", year: 1977, summary: "朋克视觉约在1970年代中期随英国、美国等地音乐和DIY文化形成，涵盖传单、同人志、唱片、服装、徽章和现场摄影。剪贴字、复印和撕纸高度重要，但不同城市、乐队和政治立场形成多种语言，黑白红并非统一配色。", influencedBy: "达达拼贴、情境主义挪用、地下出版、廉价复印技术、音乐亚文化与青年政治", influenced: "后朋克和硬核视觉、独立出版、抗议设计、时尚和后来的Grunge平面", related: ["dada", "situationist-international", "hardcore-punk-aesthetic", "grunge-design"], sources: BATCH_05_SOURCES.punk, zh: ["反网格剪贴、突兀裁切、越界重叠和快速传播的信息优先级", "手写、模板、剪贴字、粗轮廓、照片截取和直接标记", "黑白高反差、红色或来源材料综合色，不设固定三色", "现场硬光、直接闪光或复印平面明度，保留记录性", "复印颗粒、撕纸、胶痕、报纸、丝网、布料、别针和磨损", "文字是传播核心，保留原文准确性并允许剪贴、打字机和模板混排"], en: ["anti-grid collage, abrupt cropping, edge-crossing overlap, and information priority suited to rapid circulation", "handwriting, stencil, cutout type, coarse contours, cropped photographs, and direct marks", "high-contrast black-white, red, or source-material color without a fixed three-color rule", "hard venue light, direct flash, or flat photocopy value retaining documentary character", "photocopy grain, torn paper, glue, newsprint, screenprint, cloth, safety pins, and wear", "text is central to communication; preserve exact wording while mixing cutout, typewriter, and stencil forms"] },
  "grunge-design": { period: "约1980年代末–1990年代", year: 1993, summary: "Grunge平面设计约在1980年代末至1990年代与另类音乐、独立杂志和桌面出版实验相互发展，常用侵蚀字体、层叠图像和低保真复制挑战现代主义整洁。它不是音乐风格的自动视觉对应，也不能只归于单一设计师或“脏污滤镜”。", influencedBy: "朋克与后朋克出版、新浪潮字体、另类音乐、复印文化和早期桌面排版软件", influenced: "1990年代音乐和青年品牌、实验杂志、网页设计及后来的复古低保真视觉", related: ["punk-visual", "new-wave-typography", "postmodernism", "brutalism"], sources: BATCH_05_SOURCES.grunge, zh: ["不规则层叠、破损网格、密集边缘和仍可辨认的阅读路径", "侵蚀字、手写标记、照片裁切、扫描碎片和不规则边界", "脏灰、暗褐和低饱和强调常见，也可使用高纯度专色和黑白", "复印平面明度、现场摄影硬光和扫描造成的局部综合色损失", "划痕、污渍、油墨渗漏、复印噪点、粗纸和早期数字像素", "文字可破损、重叠和尺度跳变，但关键信息必须保持可读"], en: ["irregular layering, broken grids, dense edges, and a reading path that remains discernible", "eroded type, handwritten marks, photographic crops, scanned fragments, and irregular boundaries", "dirty gray, dark brown, and muted accents are common, alongside spot color, high chroma, or black-white", "flat photocopy values, hard live-photography light, and local color loss from scanning", "scratches, stains, ink bleed, photocopy noise, coarse paper, and early-digital pixels", "type may erode, overlap, and jump in scale, but essential information must remain legible"] },
  "flat-design": { period: "数字界面约2000年代末至今，2010年代初集中普及", year: 2012, summary: "扁平设计在数字界面中于2000年代末至2010年代初集中普及，以简化形体、平涂综合色、图标和排版减少装饰性拟物材质。它并非完全禁止层级、渐变和阴影；过度扁平化会削弱可点击性，后续界面已重新引入受控深度线索。", influencedBy: "国际字体风格、现代图标和信息系统、早期数字界面及对重度拟物装饰的反应", influenced: "响应式产品界面、图标与品牌插画系统，并推动Material Design等重新引入受控层级", related: ["swiss", "skeuomorphism", "material-design", "neumorphism"], sources: BATCH_05_SOURCES.flatDesign, zh: ["响应式网格、清楚层级、稳定导航和以任务为中心的界面区块", "简化几何图标、一致轮廓和可辨控件状态，避免把所有元素压成同一平面", "有限平涂综合色与足够文字对比，可用受控综合色变化区分状态", "通常减少装饰高光，必要时以轻微阴影或层级线索支持可用性", "清楚矢量边缘、一致图标系统和适配不同屏幕的数字表面", "使用高可读界面字体；标签、按钮和链接必须保持明确可发现性"], en: ["responsive grids, clear hierarchy, stable navigation, and task-centered interface regions", "simplified geometric icons, consistent contours, and distinguishable control states without flattening every element equally", "limited flat color with sufficient text contrast and controlled color changes for state", "decorative highlights are reduced, while subtle shadow or depth cues may support usability when needed", "clean vector edges, consistent icon systems, and digital surfaces adapting across screen sizes", "use highly legible interface type; labels, buttons, and links must remain explicit and discoverable"] },
  "skeuomorphism": { period: "设计原则长期存在；数字界面约1980年代至今", year: 2007, summary: "拟物化是让新对象保留旧对象外观或操作线索的广义设计原则，远早于智能手机；数字界面自图形用户界面早期即广泛采用，约2007至2013年在移动系统中达到高峰。皮革、木纹和立体按钮只是特定阶段的视觉表现，功能隐喻才是核心。", influencedBy: "工业产品中的历史拟形、桌面隐喻、早期图形用户界面及降低新技术学习成本的交互需求", influenced: "移动和游戏界面、数字怀旧，并在扁平设计反拨后以更克制方式持续存在", related: ["flat-design", "frutiger-aero", "neumorphism", "y2k"], sources: BATCH_05_SOURCES.skeuomorphism, zh: ["界面结构映射熟悉物件、容器或操作流程，优先保证功能可理解", "斜面、压印、旋钮、纸页和现实控件形态按交互用途选择", "综合色模拟来源材料或功能状态，不限定暖综合色和局部高光", "方向一致的高光、投影和遮挡建立可操作层级，不制造相互矛盾光源", "木、皮革、金属、纸张、玻璃等数字模拟纹理和触感线索", "标签和控件文字必须清晰；装饰拟物不得牺牲可读性和可访问性"], en: ["interface structure maps familiar objects, containers, or operating sequences while prioritizing functional comprehension", "bevels, embossing, knobs, pages, and real-world controls selected according to interaction purpose", "color simulates the source material or functional state without requiring warm neutrals and local highlights", "directionally consistent highlights, shadows, and occlusion establish actionable hierarchy without contradictory light sources", "digitally simulated wood, leather, metal, paper, glass, and other tactile cues", "labels and control text must remain clear; skeuomorphic decoration must not compromise legibility or accessibility"] },
  "acid-graphics": { period: "约2010年代后期至今（非正式行业标签）", year: 2019, summary: "“酸性图形”是2010年代后期设计媒体和青年文化中使用的非正式标签，常把荧光综合色、极端字体、液态或铬质3D、扫描噪声与锐舞/Y2K引用组合。它不是有宣言、成员和固定起止年的艺术运动，与酸性之家、迷幻艺术及acid house图形虽有联系但不能混同。", influencedBy: "锐舞与俱乐部传单、Y2K复兴、实验排版、早期互联网、3D软件和数字后处理", influenced: "当代音乐、时尚、活动视觉和动态图形中的高刺激反规范设计", related: ["rave-aesthetic", "y2k", "new-wave-typography", "glitch-art", "cyberpunk"], sources: BATCH_05_SOURCES.acidGraphics, zh: ["密集越界、边到边信息、中心3D物件或多个层级冲突的海报结构", "液态扭曲、尖锐几何、镀铬体和极端压缩或拉伸字体", "酸绿、电紫、荧光粉、深黑和高综合色数字渐变，配色不是名称定义", "镀铬反射、过曝辉光、屏幕综合色和刻意不自然的3D照明", "数字噪点、扫描纹、压缩伪影、液态金属、塑料和光栅图像", "文字可极端变形但活动名称、时间和功能信息必须准确可读"], en: ["dense edge bleed, edge-to-edge information, a central 3D object, or posters with colliding hierarchies", "liquid distortion, sharp geometry, chrome forms, and extremely condensed or stretched type", "acid green, electric violet, fluorescent pink, deep black, and high-chroma digital gradients without color defining the label", "chrome reflection, clipped glow, screen color, and deliberately unnatural 3D illumination", "digital noise, scan texture, compression artifacts, liquid metal, plastic, and raster imagery", "type may be extremely distorted, but event names, dates, and functional information must remain accurate and legible"] },
  "glitch-art": { period: "电子先例约1960年代；数字实践约1990年代至今", year: 2000, summary: "故障艺术把模拟信号失真、设备误用、数据损坏、软件错误和压缩异常转化为作品方法。电子先例可追溯到1960年代，数字实践在1990年代后扩展；RGB分离、像素撕裂和扫描线只是若干可见结果，不能代替对故障来源和媒介过程的说明。", influencedBy: "实验电子和录像艺术、设备干预、计算机文化、噪音音乐及对技术系统失效的研究", influenced: "网络和数字艺术、动态图形、音乐影像以及批判性媒体设计", related: ["video-art", "digital-art", "generative-art", "acid-graphics", "cyberpunk"].filter(Boolean), sources: BATCH_05_SOURCES.glitch, zh: ["结构由具体错误过程产生，可切片、错位、重复、冻结或破坏时间连续性", "信号弯折、数据重排、块状压缩、像素断裂和设备反馈痕迹", "综合色通道偏移、过曝、位深损失和异常调色取决于技术故障类型", "屏幕自发光、信号剪切和设备显示特性构成光线，不添加无关霓虹", "磁带噪声、模拟雪花、数据弯折、压缩块、坏像素和软件处理痕迹", "仅在需要时保留准确的系统、错误、时间码或界面文字，不伪造技术日志"], en: ["structure emerges from a specific error process through slicing, displacement, repetition, freezing, or broken temporal continuity", "signal bending, data reordering, compression blocks, pixel rupture, and device-feedback traces", "channel shifts, clipping, bit-depth loss, and anomalous color determined by the technical failure", "screen emission, signal clipping, and device display behavior form the light without unrelated neon effects", "tape noise, analog snow, data bending, compression blocks, dead pixels, and software-processing traces", "only when needed, preserve system, error, timecode, or interface text accurately without fabricated technical logs"] },
  "retrofuturism": { period: "约1970年代末至今；所引用未来想象更早", year: 1983, summary: "复古未来主义是后来回看过去未来想象的文化框架，把旧时代对科技、城市、太空和日常生活的预测重新置于当代。它不是单一的1950年代太空风格，也包含乐观、讽刺、失落未来和替代历史等不同态度；视觉必须明确引用的历史时期。", influencedBy: "19至20世纪世界博览会、科幻出版、交通和工业设计、原子与太空时代图像，以及后来的历史怀旧", influenced: "电影、游戏、插画、主题娱乐和品牌中的替代历史及旧未来视觉", related: ["atomic-age", "streamline-moderne", "googie-architecture", "cyberpunk", "synthwave"], sources: BATCH_05_SOURCES.retrofuturism, zh: ["构图应服从明确引用年代，可用世界博览会轴线、太空海报、技术剖面或旧广告布局", "流线机器、火箭、巨构、家电和服装造型必须与所选年代的未来观一致", "综合色引用具体历史印刷、电影或产品资料，不使用通用青绿珊瑚模板", "光线模拟所引年代的摄影、喷绘、舞台或印刷方法，并保留当代回看距离", "旧杂志网点、喷笔、搪瓷金属、塑料、模型摄影和当代数字重构", "仅在用户要求文字时使用与引用年代一致且准确可读的未来主义字体"], en: ["composition follows a specified source era through world's-fair axes, space posters, technical cutaways, or period advertising layouts", "streamlined machines, rockets, megastructures, appliances, and clothing must match the selected era's idea of the future", "color quotes specific historical print, cinema, or product references rather than a generic teal-coral palette", "light simulates the cited era's photography, airbrush, stage, or print method while retaining contemporary retrospective distance", "old-magazine halftone, airbrush, enameled metal, plastic, model photography, and contemporary digital reconstruction", "only when text is requested, use accurate legible futurist lettering consistent with the referenced era"] },
  "synthwave": { period: "约2000年代中期至今", year: 2010, summary: "Synthwave是约2000年代中期形成的电子音乐流派及其伴生视觉文化，重构1980年代电影配乐、街机、VHS和复古未来想象。霓虹地平线、透视网格和跑车是高度流通的封面惯例，却不是所有音乐分支的必要视觉，也不应与真实1980年代设计混同。", influencedBy: "1980年代合成器音乐和电影配乐、街机与家用游戏图形、VHS媒介及复古未来文化", influenced: "独立游戏、音乐封面、网络怀旧和2010年代影视中的80年代复兴", related: ["retrofuturism", "cyberpunk", "vaporwave", "outrun"].filter(Boolean), sources: BATCH_05_SOURCES.synthwave, zh: ["封面可用中心消失点、夜间道路、水平地平线或电影海报式主体结构", "硬边剪影、低多边形地形、跑车、合成器界面和80年代标题几何", "洋红、电青、紫和橙色渐变常见，也可按暗潮等分支使用低饱和综合色", "深色背景、霓虹边光、落日辉光和VHS综合色扩散", "光栅渐变、扫描线、磁带噪声、铬字、喷绘和早期3D表面", "仅在用户要求文字时使用准确可读的80年代电影或街机引用字体"], en: ["covers may use a central vanishing point, night road, horizontal horizon, or film-poster subject structure", "hard silhouettes, low-poly terrain, cars, synthesizer interfaces, and 1980s title geometry", "magenta, electric cyan, violet, and orange gradients are common, while darker branches may use restrained color", "dark grounds, neon rim light, sunset glow, and VHS color bloom", "raster gradients, scanlines, tape noise, chrome type, airbrush, and early-3D surfaces", "only when text is requested, use accurate legible lettering that cites 1980s cinema or arcade graphics"] },
  "vaporwave": { period: "约2010年代初至今", year: 2012, summary: "Vaporwave约在2010年代初由网络音乐和图像文化形成，通过减速采样、企业氛围音乐、早期电脑、商场和全球化消费图像制造怀旧、疏离与讽刺。古典雕像、日文、粉青渐变只是流行语汇；其对资本主义的态度可能批判、暧昧或纯粹沉浸，不能一概而论。", influencedBy: "采样音乐、chillwave、1980至1990年代商业媒体、早期互联网、企业图形和全球消费文化", influenced: "网络美学、音乐微流派、Y2K复兴、封面设计和社交媒体怀旧视觉", related: ["synthwave", "y2k", "seapunk", "webcore"].filter(Boolean), sources: BATCH_05_SOURCES.vaporwave, zh: ["拼贴、重复、空旷商场、旧桌面界面或刻意错位的对称结构", "低多边形、古典复制品、企业标识碎片、早期3D和界面窗口", "粉、青、薰衣草、冷白是常见子类型，也可保留来源广告和录像综合色", "柔和屏幕辉光、低对比渐变、荧光室内光和录像综合色漂移", "VHS扫描线、低清数字图、压缩、塑料与铬反射、旧系统界面", "来源文字和日文必须准确；不得用随机字符替代真实语言或制造伪品牌"], en: ["collage, repetition, empty malls, old desktop interfaces, or deliberately displaced symmetry", "low-poly forms, classical reproductions, fragments of corporate identity, early 3D, and interface windows", "pink, cyan, lavender, and cool white in common substyles, while source advertising and video color may remain", "soft screen glow, low-contrast gradients, fluorescent interior light, and drifting video color", "VHS scanlines, low-resolution digital images, compression, plastic and chrome reflection, and old operating-system interfaces", "source wording and Japanese text must be accurate; never substitute random characters for real language or fabricate brands"] }
};

