const BATCH_07_REVIEWS = {
  "wei-jin-tomb-mural": { period: "约3–6世纪，魏晋南北朝", year: 400, summary: "魏晋南北朝墓葬图像分布广泛，包含壁画、画像砖和漆画等不同材料，并随河西、东北、江南和中原地区而变化。仪仗、宴饮、出行、孝子和神异题材常见，但横向推进、砖红灰绿或简化线描不能成为所有墓室的统一模板。", influencedBy: "汉代墓葬图像、地方丧葬制度、壁画和画像砖工艺，以及民族与区域文化交流", influenced: "隋唐墓室壁画、人物叙事和中国墓葬美术研究", related: ["han-dynasty-pictorial-stone", "han-dynasty-silk-painting", "tang-figure-painting", "dunhuang"], sources: BATCH_07_SOURCES.sixDynasties, zh: ["按墓室结构采用分壁、长卷式推进、独立砖格或中心图像，不假定统一横向叙事", "线描、平涂、画像砖模印和局部晕染依地区与载体变化", "砖土、石灰底、墨、朱、赭及青绿残色依据考古记录，不用统一褪色滤镜", "文物记录使用均匀光，侧光只用于显示真实墙面、砖缝和起伏", "砖石或灰泥、矿物与有机综合色、模印刻线、烟尘、脱落和经记录的修复", "仅在墓葬原有且可辨识时呈现榜题或铭文；不添加伪古文字"], en: ["wall-by-wall, processional, brick-cell, or centered organization selected from the tomb structure rather than one horizontal narrative formula", "line drawing, flat color, molded pictorial brick, and local shading varying by region and support", "earth or brick, lime ground, ink, vermilion, ochre, and surviving blue-green based on archaeological evidence without one faded filter", "even conservation light, with sidelight used only to show real wall texture, joints, and relief", "brick, stone, or plaster, mineral and organic color, molded or incised line, soot, losses, and documented conservation", "show labels or inscriptions only when original and legible; never add fabricated ancient writing"] },
  "running-script-aesthetic": { period: "约2世纪形成并延续至今", year: 350, summary: "行书约在汉末魏晋形成，是介于楷书端整和草书简省之间的广泛书写类型，既可接近楷书，也可趋近草书。它的连带、欹正和速度关系必须来自真实字法；若无法准确保存原文，就不能用流动线条冒充行书。", influencedBy: "汉代隶草书写、楷书形成和日常快速书写", influenced: "历代手札、碑帖、东亚书法和现代中文书写设计", related: ["regular-script-aesthetic", "cursive-script-aesthetic", "clerical-script-aesthetic", "ink-wash"], sources: BATCH_07_SOURCES.runningScript, zh: ["行列可松动，字间呼应、重心和疏密构成连续阅读节奏，但不强制字字相连", "楷书可辨结构与草书式连带按真实行法结合，提按、断连和牵丝须有字形依据", "墨的浓淡干湿与纸绢本色为主，印色只在真实落印时出现", "均匀观看光保留墨色和运笔层次，不添加与书写无关的立体阴影", "毛笔墨、纸绢纤维、渗化、飞白、接锋和速度造成的自然变化", "仅当每个原文字形都能准确可读时使用行书；否则选择楷书或现代可读字体"], en: ["loosely aligned rows with intercharacter response, shifting centers, and density forming continuous reading rhythm without joining every character", "legible regular-script structure combined with evidence-based cursive linkage, pressure, breaks, and connecting threads", "wet-dry and dark-light ink with the paper or silk ground, adding seal red only for a real seal impression", "even viewing light preserving ink and stroke sequence without unrelated dimensional shadows", "brush ink, paper or silk fiber, diffusion, flying-white breaks, rejoined strokes, and natural speed variation", "use running script only when every supplied character remains exact and legible; otherwise choose regular script or modern readable type"] },
  "jiehua": { period: "唐代已有传统，宋元高度发展并延续至后世", year: 1100, summary: "界画是借界尺等工具绘制建筑、舟车和器物界线的中国绘画门类，宋元时期高度发展，但并不等同现代工程制图或统一轴测图。精密直线与构件关系是核心，人物、山水和设色仍可共同参与叙事。", influencedBy: "早期建筑图像、工匠制图、界尺工具与宫廷绘画", influenced: "宋元明清建筑画、城市和园林图像，以及后世建筑表现", related: ["song-court-painting", "gongbi", "blue-green-landscape", "chinese-lianhuanhua"], sources: BATCH_07_SOURCES.jiehua, zh: ["楼阁、舟车或器物按卷轴和画幅组织精密空间，可与山水人物结合而非只作结构图", "界尺辅助的梁柱、斗栱、檐口和栏杆保持平直关系，同时允许手绘轮廓", "墨线、纸绢底、淡赭、青绿和朱色按时代与作品选用", "结构由线性层级、综合色差和遮挡说明，不强加现代轴测光和硬投影", "纸绢、界尺墨线、细笔节点、矿物或透明淡彩和手工微差", "只有原作需要题记或用户提供准确文字时加入可读题款，不使用现代工程乱码"], en: ["precise space for buildings, boats, or objects organized within scroll or framed formats and integrated where appropriate with figures and landscape", "ruled beams, columns, bracket sets, eaves, and railings retaining straight relations alongside freehand contours", "ink line, paper or silk, pale ochre, blue-green, and vermilion selected by date and work", "structure explained through linear hierarchy, color value, and overlap rather than modern axonometric lighting and hard shadows", "paper or silk, ruled ink, fine-brush joints, mineral or transparent light color, and small handmade variation", "add a legible inscription only when present in the source or when exact user text is requested; use no pseudo-engineering notation"] },
  "yuan-literati-painting": { period: "1271–1368年及元末延续", year: 1330, summary: "元代文人画并非单一水墨山水风格，而是士人画家在蒙古统治、隐逸与仕宦等不同处境中，以书法性笔墨、古法重释、诗书画关系和个人交游重新定义绘画价值。赵孟頫、元四家等人的构图、设色和笔法彼此有显著差异。", influencedBy: "宋代文人画、董源巨然等古代山水传统、书法和元代士人文化", influenced: "明清文人画、吴门与松江传统、董其昌的南北宗论及东亚南画", related: ["ink-wash", "wu-school", "songjiang-school", "four-wangs-school"], sources: BATCH_07_SOURCES.yuan, zh: ["平远、层叠、疏林或密集山体依画家而变，以卷轴节奏和题跋空间共同组织", "书法性轮廓、皴法和点苔强调笔墨结构，不能用一种干笔程式覆盖元四家", "墨阶、纸白、淡赭和青绿均可出现，综合色选择服从具体作品", "空间由笔墨层次、虚实和综合色积染建立，不依赖写实投影", "纸绢水墨、干湿皴擦、透明设色、题跋与经证实的印章层", "只有原文准确且不冒充名家时才加入题款；不得伪造赵孟頫或元四家书法印记"], en: ["level distance, layered terrain, sparse groves, or dense mountains varying by painter and organized jointly by scroll rhythm and colophon space", "calligraphic contours, texture strokes, and dots emphasizing brush structure without reducing the Four Masters to one dry-brush formula", "graded ink, paper white, pale ochre, and blue-green all possible according to the specific work", "space built through brush layers, solid-void relations, and accumulated color rather than realistic cast shadow", "ink on paper or silk, dry-wet texture strokes, transparent color, colophons, and documented seal layers", "add inscriptions only with exact wording and without impersonating a master; never fabricate calligraphy or seals of Zhao Mengfu or the Four Masters"] },
  "wu-school": { period: "约15世纪中期–16世纪，后续影响延长", year: 1520, summary: "吴门画派以明代苏州为中心，通常联系沈周、文徵明、唐寅、仇英等不同身份和实践；“文人画派”并不能完整容纳职业性很强的成员。古画重释、诗书画交游与苏州文化重要，但粗笔、细笔、青绿和人物等路线不可统一成淡墨山水。", influencedBy: "元代文人画、苏州收藏与诗书画社交、院体和职业绘画传统", influenced: "晚明文人和职业绘画、松江画派及清代对明画的接受", related: ["yuan-literati-painting", "zhe-school", "songjiang-school", "gongbi"], sources: BATCH_07_SOURCES.wu, zh: ["卷轴游观、册页小景、园林雅集或密集叙事按画家与题材选用", "从沈周粗笔到文徵明细笔、仇英精工设色均可，不以单一皴法定派", "水墨、淡赭、青绿和矿物重彩均存在，纸绢底色参与画面", "墨色和综合色层建立空间，工笔人物与写意山水的明暗机制分别处理", "纸绢、书写性水墨、精细勾染、矿物设色、题跋和可靠印章", "只有在准确保留用户文字时使用与具体作品相称的题款，不仿造吴门名家签名"], en: ["roaming scrolls, album vignettes, garden gatherings, or dense narratives selected by painter and subject", "a range from Shen Zhou's broad brush to Wen Zhengming's fine line and Qiu Ying's meticulous color rather than one school-wide texture stroke", "ink, pale ochre, blue-green, and opaque mineral color all present with the paper or silk ground", "space built through ink and color layers, treating meticulous figures and freely brushed landscape by their distinct value systems", "paper or silk, calligraphic ink, meticulous contour and wash, mineral color, colophons, and verified seals", "use an inscription suited to the specific work only when supplied text remains exact; never imitate a Wu master's signature"] },
  "zhe-school": { period: "约15–16世纪，明代前中期影响显著", year: 1480, summary: "浙派是后世对明代职业画家网络的宽泛称呼，常以戴进为核心并承续南宋院体，但成员、地域和边界并不固定。强烈斧劈皴、对角构图和水墨对比是部分重要路线，不应把所有浙派作品都写成粗放戏剧山水。", influencedBy: "南宋画院和马夏传统、元代职业绘画及明代宫廷和地方画家网络", influenced: "明代宫廷与职业山水、日本室町水墨和后来的浙派接受史", related: ["ma-xia-school", "song-court-painting", "wu-school", "japanese-zen-ink-painting"], sources: BATCH_07_SOURCES.zhe, zh: ["对角近景、紧凑山水、人物叙事或较平稳布局按作品选择，不设统一压迫构图", "斧劈皴、浓淡突变和有力轮廓是重要手段，同时保留精细和较克制笔法", "深墨、灰褐、淡赭、青绿或纸绢本色随题材和时期变化", "浓墨与雾化远景可形成对比，但不把戏剧高反差设为全部浙派特征", "纸绢、水墨、湿笔、干皴、淡彩及职业画家受控制作痕迹", "仅在原作题记可考或用户提供准确文字时呈现，不制造职业画家伪款"], en: ["diagonal foregrounds, compact landscapes, figure narratives, or calmer arrangements selected by work rather than one compressed formula", "axe-cut texture, abrupt ink value, and forceful contour as important devices alongside fine and restrained handling", "deep ink, gray-brown, pale ochre, blue-green, or exposed paper and silk varying by subject and date", "dense ink may contrast with misted distance without making theatrical contrast universal", "paper or silk, ink, wet loading, dry texture strokes, light color, and controlled professional workmanship", "show text only when an original inscription is documented or exact wording is supplied; never fabricate a professional painter's signature"] },
  "songjiang-school": { period: "约16世纪后期–17世纪初，晚明", year: 1600, summary: "松江画派是围绕晚明松江地区董其昌等人的若干文人山水群体与理论影响的总称，内部包括不同支系而非一个样式统一的组织。其关键在古代山水谱系重构、笔墨层积和南北宗理论，不能与吴门画派共享同一套视觉句子。", influencedBy: "元代文人山水、吴门传统、晚明收藏鉴赏和董其昌的绘画理论", influenced: "清初正统山水、四王体系和后世文人画史叙述", related: ["yuan-literati-painting", "wu-school", "four-wangs-school", "four-monks-painting"], sources: BATCH_07_SOURCES.songjiang, zh: ["以古画结构重组层峦、平远和卷轴段落，节奏可疏可密而不等同吴门园林小景", "书法性轮廓与皴法模块通过重复、积叠和空隙说明结构", "墨阶、淡赭、灰绿和纸本暖色为常见体系，也按仿古对象改变", "均匀观看光保留积墨和透明设色层次，不以自然主义投影建空间", "纸本水墨、干湿积层、仿古皴法、题跋与收藏印的历史叠加", "仅在文字准确且不冒充董其昌等名家时设置题款；印章不得伪造"], en: ["ancient pictorial schemas recomposed into layered peaks, level distance, and scroll sections with variable density distinct from Wu garden vignettes", "calligraphic contours and modular texture strokes using repetition, accumulation, and intervals to articulate structure", "graded ink, pale ochre, gray-green, and warm paper as common systems adjusted to the historical model being reworked", "even viewing light preserving accumulated ink and transparent color instead of naturalistic cast-shadow space", "ink on paper, dry-wet accumulation, archaizing texture strokes, colophons, and historically layered collectors' seals", "set an inscription only when wording is exact and does not impersonate Dong Qichang or another master; never fabricate seals"] },
  "four-wangs-school": { period: "17世纪，明末清初至清初", year: 1680, summary: "“四王”指王时敏、王鉴、王翚、王原祁四位山水画家，并非同一时段共同成立的正式画派。他们共享对董其昌所建正统谱系和古代笔墨的重视，但各自的构图、用笔和综合色并不相同，也不能把仿古误解为机械复制。", influencedBy: "董其昌和松江画派、元代文人山水、明清收藏鉴赏与摹古实践", influenced: "清代宫廷和正统山水教学、娄东虞山等地域传统及后世山水规范", related: ["songjiang-school", "yuan-literati-painting", "four-monks-painting", "jinling-school"], sources: BATCH_07_SOURCES.fourWangs, zh: ["古代山水结构被重新组合为严谨层次和卷轴节奏，四位画家的空间密度分别处理", "皴法模块、书写轮廓和积墨形成受控笔墨系统，而不是复制同一古画表面", "墨色、淡赭、灰绿、青绿和纸本暖白按画家与仿古对象改变", "综合色和积墨层次建立空间，不添加现代景观摄影式光影", "纸绢、水墨、层层皴染、淡彩、题跋和经核实的印章", "只使用准确且不冒充四王本人书法的题款；不得伪造姓名、年代和鉴藏印"], en: ["older landscape schemas recomposed into measured layers and scroll rhythm, with spatial density differentiated among the four painters", "modular texture strokes, calligraphic contours, and accumulated ink forming controlled systems rather than copying one antique surface", "ink, pale ochre, gray-green, blue-green, and warm paper varying by painter and archaizing model", "space built through color and accumulated ink without modern landscape-photography lighting", "paper or silk, ink, layered texture and wash, light color, colophons, and verified seals", "use only accurate inscriptions that do not impersonate a Four Wangs hand; never fabricate names, dates, or collectors' seals"] },
  "four-monks-painting": { period: "17世纪至18世纪初，明末清初", year: 1680, summary: "“四僧”通常指弘仁、髡残、八大山人和石涛，是后世将四位明遗民或僧人画家并置的称谓，而非共同纲领的组织。他们的冷峻几何山水、密厚积墨、怪诞花鸟和高度个体化笔法差异极大，不能统一成孤寂留白与狂放墨线。", influencedBy: "晚明文人画、元代山水、遗民处境、禅宗文化和各自地域师承", influenced: "清代个性主义绘画、扬州画坛及近现代对表现性笔墨的重估", related: ["four-wangs-school", "jinling-school", "eight-eccentrics-of-yangzhou", "ink-wash"], sources: BATCH_07_SOURCES.fourMonks, zh: ["按弘仁、髡残、八大或石涛的具体路线选择疏峻、密厚、怪奇或游动空间", "几何化轮廓、积墨、奇崛变形或自由皴点必须对应具体画家而非拼合", "墨色和纸白为重要基础，也有淡赭、花鸟设色和局部强烈墨块", "虚实、墨阶和笔触密度生成空间，各画家不共享统一冷光或苍凉滤镜", "纸本水墨、干皴、积墨、泼墨、淡彩和个体化书画题跋", "文字必须准确并明确为现代内容；不得仿造四僧的书法、别号、印章或题诗"], en: ["sparse severity, dense accumulation, uncanny form, or mobile space selected specifically for Hongren, Kuncan, Bada Shanren, or Shitao", "geometric contour, accumulated ink, eccentric distortion, or free texture marks tied to one painter rather than blended together", "ink and paper white as major bases alongside pale ochre, colored flora and fauna, and concentrated dark accents", "space produced by solid-void relation, ink value, and mark density without one cold or desolate filter", "ink on paper, dry texture, accumulated or splashed ink, light color, and individualized painting-calligraphy relations", "text must remain exact and be identified as modern content; never imitate the Four Monks' handwriting, sobriquets, seals, or poems"] },
  "jinling-school": { period: "约17世纪，明末清初南京画坛", year: 1660, summary: "金陵画派是对明末清初南京一带若干画家及“金陵八家”的后设地域称谓，成员名单和风格边界并不完全固定。南京实景、遗民文化与个体笔墨重要，但龚贤的积墨山水不能代表樊圻、高岑等全部金陵画家。", influencedBy: "晚明南京文化、宋元山水、吴门和松江影响、地方实景与遗民经验", influenced: "清初南京绘画、个性主义山水和近现代对龚贤积墨的研究", related: ["four-monks-painting", "four-wangs-school", "songjiang-school", "eight-eccentrics-of-yangzhou"], sources: BATCH_07_SOURCES.jinling, zh: ["南京实景、层峦全景、册页小景或偏置景物按具体画家选择", "从龚贤层层积墨到其他金陵画家的细线、淡设色和职业笔法均须区分", "浓淡墨阶、纸白、淡赭和有限青绿，不以黑密积墨统一全派", "墨层和虚实建立空气与距离，保留不同画家的明暗差异", "纸绢、水墨、积墨或淡墨、细线、设色和真实题跋印记", "仅在原作证据充分或用户提供准确文字时加入题款，不伪造金陵画家姓名与印章"], en: ["Nanjing sites, layered panoramas, album vignettes, or off-center motifs selected by individual painter", "Gong Xian's accumulated ink distinguished from the fine line, light color, and professional handling of other Nanjing painters", "dark and pale ink, paper white, pale ochre, and limited blue-green without making dense black ink universal", "ink layering and solid-void relation building atmosphere and distance while retaining painter-specific value systems", "paper or silk, accumulated or pale ink, fine line, color, and genuine colophon and seal evidence", "add inscriptions only with strong source evidence or exact supplied wording; never fabricate Nanjing painters' names or seals"] },
  "eight-eccentrics-of-yangzhou": { period: "18世纪，清代扬州画坛", year: 1750, summary: "“扬州八怪”是对18世纪扬州一批以书画谋生、风格不循正统的画家的弹性称谓，名单不止一种，也不是恰好八人组成的宣言团体。金农、郑燮、李鱓等人的金石书写、兰竹花卉和泼写设色差异明显。", influencedBy: "扬州商业与盐商赞助、金石学、文人花鸟和明清个性主义绘画", influenced: "海上画派、近现代写意花鸟、书画市场与金石审美", related: ["four-monks-painting", "shanghai-school-painting", "jinling-school", "ink-wash"], sources: BATCH_07_SOURCES.yangzhou, zh: ["偏心、满幅、册页或条幅布局按具体画家题材选择，不固定为一物加大片留白", "金石线、兰竹笔、泼写花卉和夸张造型必须区分画家，不混成统一怪笔", "墨黑、纸白、朱砂、花青、藤黄和淡彩均可，综合色不必克制到单色", "墨色与设色层次塑形，书写速度和纸性比模拟自然投影更关键", "纸本水墨、枯湿笔、泼写设色、金石题跋和真实印章", "只有原文准确且不冒充画家手迹时使用题款；不得伪造郑燮、金农等书法印记"], en: ["off-center, full-field, album, or hanging-scroll layouts selected by painter and subject rather than one motif in a large void", "epigraphic line, orchid-bamboo strokes, splashed flora, and exaggerated form differentiated by artist rather than merged as one eccentric hand", "ink black, paper white, cinnabar, indigo, yellow, and light color all possible without mandatory monochrome restraint", "form built by ink and color layers, with writing speed and paper response more important than natural cast-shadow simulation", "ink and color on paper, dry-wet brushwork, splashed color, epigraphic colophons, and genuine seals", "use inscriptions only when wording is exact and does not impersonate an artist; never forge the calligraphy or seals of Zheng Xie, Jin Nong, or others"] },
  "shanghai-school-painting": { period: "约19世纪中期–20世纪初", year: 1890, summary: "海上画派形成于开埠后的上海艺术市场，汇聚来自江浙等地的职业和文人画家，以金石书法、写意花鸟、人物和适应城市销售的画幅与题材见长。鲜艳综合色和近距裁切很常见，但任伯年、吴昌硕等人的造型与笔墨不能被合并为一种商业风格。", influencedBy: "扬州画坛、金石学、民间图像、传统人物花鸟和上海城市艺术市场", influenced: "近现代中国画、岭南画派的部分交流、月份牌和城市视觉文化", related: ["eight-eccentrics-of-yangzhou", "lingnan-school", "yuefenpai-calendar-art", "chinese-new-year-print"], sources: BATCH_07_SOURCES.shanghai, zh: ["条幅、册页、扇面和近距花鸟人物按市场与题材组织，可疏可满", "金石书写、写生人物、没骨或勾线花鸟随画家变化，不设统一粗线", "墨、朱砂、花青、石绿、藤黄和纸本暖白形成从淡雅到浓艳的范围", "墨色和综合色层次结合观察塑形，不把西式明暗或平光设为统一模式", "纸绢、水墨、矿物或植物综合色、书法题跋、印章和商品化装裱", "只在给定文字准确时安排题款和印章，并明确不仿造任伯年、吴昌硕等手迹"], en: ["hanging scrolls, albums, fans, and closely framed flora or figures organized by market and subject with variable density", "epigraphic brushwork, observed figures, and boneless or outlined flora varying by painter without one coarse-line formula", "ink, cinnabar, indigo, mineral green, yellow, and warm paper ranging from restrained to vivid", "observational modeling combined with ink and color layers without one Western chiaroscuro or flat-light rule", "paper or silk, ink, mineral or vegetable color, calligraphic colophons, seals, and market-oriented mounting", "arrange inscriptions and seals only when supplied wording is exact, and never imitate the hands of Ren Bonian, Wu Changshuo, or other masters"] },
  "lingnan-school": { period: "约1900年代–20世纪中期及其延续", year: 1920, summary: "岭南画派是20世纪初以广东为中心的改革中国画网络，通常联系高剑父、高奇峰、陈树人等人，吸收日本画、西方写生与摄影，同时重估中国笔墨。它不是单纯“水墨加明亮水彩”，成员对政治、教育和风格的立场也不完全相同。", influencedBy: "中国画传统、日本画教育、西方写生和摄影、晚清民国改革思想", influenced: "广东和港澳现代中国画、美术教育及20世纪中国画革新", related: ["shanghai-school-painting", "nihonga", "ink-wash", "gongbi"], sources: BATCH_07_SOURCES.lingnan, zh: ["近代裁切、明确焦点、卷轴留白或叙事场景按画家和题材选用", "观察性轮廓、水墨线、湿润综合色面和局部精描形成中外方法交汇", "墨、灰绿、明亮水彩或日本画综合色及纸本暖白，不设统一岭南综合色谱", "方向性自然光、空气综合色和水墨晕染可共同塑形，但须服从具体作品", "纸本水墨、水彩或日本画综合色、撞水撞粉、细颗粒和现代装裱", "仅在用户提供准确内容时使用清楚现代题款；不仿造岭南画家书法、印章或政治文字"], en: ["modern cropping, clear focal points, scroll-like open ground, or narrative scenes selected by painter and subject", "observed contours, ink line, wet color masses, and local meticulous detail bringing several methods into relation", "ink, gray-green, bright watercolor or nihonga color, and warm paper without one Lingnan palette", "directional natural light, atmospheric color, and diffused ink washes combined only where appropriate to the work", "ink on paper, watercolor or nihonga pigment, water-and-powder blooming, fine granulation, and modern mounting", "use a clear modern inscription only with exact supplied content; never imitate Lingnan painters' handwriting, seals, or political text"] },
  "chinese-new-year-print": { period: "明代后期至今，清代各产地繁盛", year: 1800, summary: "中国木版年画是为岁时、家庭祭祀、门神、戏曲故事和吉祥装饰生产的广泛民间印刷传统，明清以来形成杨柳青、桃花坞、杨家埠、绵竹等不同工艺中心。正面对称、红黄绿和粗线只适用于部分题材，不能覆盖套色、半印半绘与单版手绘等差异。", influencedBy: "雕版印刷、民间信仰与岁时习俗、戏曲小说、城市出版和地方绘画工艺", influenced: "近现代大众图像、月份牌、节庆包装与地方非遗传承", related: ["yangliuqing-new-year-print", "taohuawu-new-year-print", "mianzhu-new-year-print", "weifang-new-year-print"], sources: BATCH_07_SOURCES.nianhua, zh: ["门画可成对对称，故事画、历画和风俗画则采用分场、连续叙事或城市景观", "木刻轮廓、套版色块和手工开脸填色按产地工艺区分", "朱红、黄、绿、蓝、粉和墨黑常见，但综合色数量和调性随产地、年代与题材变化", "印刷综合色保持平面明度，手绘部分可有有限晕染；不添加写实投影", "木版、颜料或油墨、纸纤维、套印微差、手工彩绘和真实使用磨损", "只呈现准确可读的门联、榜题或吉语；不杜撰神名、符咒和历史文字"], en: ["paired symmetry for door prints, while story, calendar, and genre pictures use compartments, continuous narrative, or urban views", "woodcut contours, registered color blocks, and hand-painted faces or fills distinguished by production center", "vermilion, yellow, green, blue, pink, and black as common colors whose number and tone vary by place, date, and subject", "flat value for printed color with limited hand-painted gradation where appropriate and no realistic cast shadow", "woodblocks, pigment or ink, paper fiber, small registration shifts, hand coloring, and genuine use wear", "show only accurate legible couplets, labels, or auspicious phrases; never invent deity names, talismans, or historical text"] },
  "yangliuqing-new-year-print": { period: "约17世纪后期至今，清代繁盛", year: 1800, summary: "天津杨柳青年画以木版套印轮廓和色版后再手工开脸、晕染及局部描金著称，属于“半印半绘”的代表传统。工艺与题材随年代和作坊变化，丰满人物、中心对称和金粉不能成为所有杨柳青作品的必要条件。", influencedBy: "天津地区雕版印刷、工笔人物画、城市市场和岁时民俗", influenced: "北方年画、清代民间人物图像和现代年画保护复兴", related: ["chinese-new-year-print", "weifang-new-year-print", "taohuawu-new-year-print", "gongbi"], sources: BATCH_07_SOURCES.yangliuqing, zh: ["门神可成对中心组织，娃娃、仕女、故事和风俗画按题材采用群组或多场景", "木版轮廓结合手工开脸、晕染和细部描绘，手绘程度依版次与作坊而变", "朱红、粉、黄、绿、蓝及局部金色常见，但不设固定综合色配方", "平面套印综合色与受控手绘明暗结合，不模拟油画式强投影", "木版套印、手工施彩、颜料晕染、金粉或金泥和纸面压痕", "只有来源或用户提供准确文字时使用可读榜题吉语；不得伪造神名与符箓"], en: ["paired central organization for door gods, with grouped or multiscene layouts for children, beauties, stories, and genre subjects", "woodblock contours combined with hand-painted faces, gradation, and detail in degrees that vary by edition and workshop", "vermilion, pink, yellow, green, blue, and occasional gold as common but nonfixed choices", "flat printed color combined with controlled hand modeling without oil-paint-like cast shadow", "multi-block printing, hand-applied pigment, graded color, gold powder or shell gold, and paper impression", "use legible labels or auspicious phrases only from a source or exact user text; never fabricate deity names or talismans"] },
  "taohuawu-new-year-print": { period: "约17世纪后期至今，清代苏州繁盛", year: 1750, summary: "苏州桃花坞年画源于城市版刻环境，涵盖门画、戏曲故事、风俗、美人和城市图景，常见精细线版与多版套色，也曾吸收西洋透视和铜版图像。所谓雅致桃红嫩绿或较深建筑空间只代表部分作品。", influencedBy: "苏州版画和出版、地方绘画、戏曲小说、城市消费文化及部分西洋图像交流", influenced: "江南年画、日本浮世绘研究中的交流讨论及现代苏州版画复兴", related: ["chinese-new-year-print", "yangliuqing-new-year-print", "mianzhu-new-year-print", "ukiyo-e"], sources: BATCH_07_SOURCES.taohuawu, zh: ["可采用门画对幅、故事分场、城市全景、室内人物或装饰边框，不统一为建筑深景", "细密木刻线、精确或可见偏差的套色，以及部分作品中的透视缩短", "桃红、黄、绿、蓝、墨黑和纸白范围随时期版次变化，不固定柔和综合色", "平面印刷明度为主，透视作品可用有限明暗说明空间而非写实光效", "多版木刻、印刷颜料、细纸纤维、版次叠印、套准差和真实磨损", "只使用准确可读的题名、店号或故事文字；不得虚构历史版号与作坊标记"], en: ["paired door prints, compartmented stories, urban panoramas, interiors, or decorative borders rather than one deep architectural view", "fine woodcut line, registration from precise to visibly shifted, and perspectival recession in some works", "peach red, yellow, green, blue, black, and paper white varying by date and edition without one soft palette", "primarily flat printed value, with limited modeling in perspectival works rather than realistic lighting effects", "multiblock woodcut, printing pigment, fine paper fiber, layered impressions, registration variation, and genuine wear", "use only accurate legible titles, shop names, or story text; never invent historical edition or workshop marks"] },
  "mianzhu-new-year-print": { period: "明清以来，清代至今持续发展", year: 1800, summary: "四川绵竹年画以木版墨线后自由手绘施彩的做法最具代表性，也包含素版等类型。综合色、刷痕和造型随作坊与画师而变；粗放边缘、粉笺和中心主图不是所有绵竹作品的固定条件。", influencedBy: "四川雕版、民间绘画、戏曲与岁时信仰、地方纸张和手工施彩", influenced: "西南年画、现代民间美术研究和当代非遗创作", related: ["chinese-new-year-print", "yangliuqing-new-year-print", "taohuawu-new-year-print", "weifang-new-year-print"], sources: BATCH_07_SOURCES.mianzhu, zh: ["单幅、对幅、条屏或故事场景按用途组织，保留手绘施彩的自由密度", "木版墨线提供骨架，手工填色、勾染和夸张造型因画师而异", "大红、桃红、黄、绿、蓝、墨和纸白可明快碰撞，也存在素版与有限色版本", "印线平面清楚，手绘综合色保留刷色浓淡，不用立体投影统一塑形", "木版墨线、手绘颜料、地方纸张或粉笺、刷痕、印压与使用磨损", "只有文字来源可靠或由用户准确提供时呈现吉语题名，不生成伪符咒"], en: ["single sheets, pairs, hanging strips, or story scenes organized by use while retaining variable density from hand coloring", "woodblock key lines providing structure, with hand fill, wash, and exaggeration varying by painter", "bright red, pink, yellow, green, blue, ink, and paper white in vivid combinations alongside uncolored or restricted-color editions", "clear flat printed line with visible density changes in hand-applied color and no universal dimensional shadow", "woodblock ink, hand pigment, local paper or prepared tinted sheet, brush traces, impressions, and use wear", "show auspicious text or titles only from a reliable source or exact user input; never generate pseudo-talismans"] },
  "weifang-new-year-print": { period: "明代后期至今，以山东潍坊杨家埠传统为核心", year: 1800, summary: "潍坊年画通常主要指杨家埠木版年画，以分版刻印、直接套色和面向乡村市场的门神、灶神、戏曲、故事与讽喻题材著称。强中心粗线适合部分门画，但多格故事、历画和风俗画具有不同版面，不能统一为对称门神模板。", influencedBy: "山东雕版印刷、乡村集市、民间信仰、戏曲小说和岁时生活", influenced: "华北年画、现代民间美术研究和杨家埠非遗传承", related: ["chinese-new-year-print", "yangliuqing-new-year-print", "mianzhu-new-year-print", "chinese-lianhuanhua"], sources: BATCH_07_SOURCES.yangjiabu, zh: ["对幅门画、单幅神像、多格故事、历画或讽喻画按实际功能选择版面", "木刻主线、概括人物和直接套色强调远观辨识，线条粗细依版次题材变化", "朱红、黄、绿、蓝、紫和黑常见，综合色来自分版印刷且不限定五色", "保持套色平面明度和纸面透底，不添加柔光晕染或写实投影", "分版木刻、直接套印、粗细不同的纸纤维、套准微差、墨色不均和压印", "准确呈现可核实的神名、历文、店号和故事题名；不得生成伪神名、符咒或乱码"], en: ["paired door prints, single deity sheets, multiframe stories, calendars, or satirical pictures laid out according to actual function", "key-block lines, simplified figures, and direct registered color designed for distance, with line weight varying by edition and subject", "vermilion, yellow, green, blue, violet, and black as common block colors without a fixed five-color rule", "flat registered values and visible paper ground without soft painted glow or realistic cast shadow", "separate woodblocks, direct color printing, varied paper fiber, small registration shifts, uneven ink, and impression pressure", "render only verifiable deity names, calendar text, shop marks, and story titles; never generate false sacred names, talismans, or gibberish"] }
};

