  yamato: [{ label: "The Met：Yamato-e painting", url: "https://www.metmuseum.org/essays/yamato-e-painting" }, { label: "Wikipedia：Yamato-e", url: "https://en.wikipedia.org/wiki/Yamato-e" }],
