const BATCH_08_REVIEWS = {
  "yamato-e": { period: "约9世纪形成，平安至江户持续演变", year: 1150, summary: "大和绘是平安时代以来相对于唐绘等分类形成的日本绘画传统，题材涉及宫廷文学、名所、四季、寺社缘起和历史叙事。吹拔屋台、连续卷轴和浓丽设色是重要方法，却不能覆盖屏风、册页、白描式作品或不同阶段。", influencedBy: "奈良和平安宫廷绘画、唐绘的选择性吸收、日本文学和四季名所文化", influenced: "土佐派、琳派、绘卷传统和近代对日本本土绘画的建构", related: ["tosa-school", "rinpa", "ukiyo-e", "nihonga"], sources: BATCH_08_SOURCES.yamato, zh: ["斜向俯视、连续绘卷、屏风跨幅或册页分场按作品选择，不强制吹拔屋台", "细线、平涂、引目钩鼻式人物或写实细节依时代题材变化", "群青、朱红、石绿、金银和纸绢底色常见，也有水墨与白描路线", "以色区、重叠和金银反光组织浅空间，不套用统一平面柔光", "纸绢、矿物综合色、墨线、金银箔、颜料脱落和卷轴折痕", "只在原作有可考词书或用户提供准确文字时加入，不仿造古代假名书法"], en: ["oblique views, continuous handscrolls, multipanel screens, or album compartments selected by work without requiring roofless interiors", "fine line, flat color, codified faces, or observed detail varying by date and subject", "ultramarine, vermilion, mineral green, gold-silver, and paper or silk alongside ink and monochrome branches", "shallow space built through color zones, overlap, and metallic reflection rather than one flat soft-light formula", "paper or silk, mineral pigment, ink line, metal leaf, pigment loss, and scroll creases", "add text only from a documented source or exact user input; never imitate ancient kana calligraphy"] },
  "tosa-school": { period: "约15–19世纪，前史可追溯至更早宫廷画所", year: 1550, summary: "土佐派是室町至江户时期与宫廷画所和大和绘传统密切相关的职业画家家系，并非从9世纪持续不变的统一画派。精细绘卷、古典文学和金云设色重要，但尺幅、题材和笔法随成员与委托而变。", influencedBy: "大和绘、宫廷绘所、古典文学绘卷和中世职业画家制度", influenced: "江户宫廷绘画、住吉派、复古大和绘和近代日本画", related: ["yamato-e", "kano-school", "rinpa", "nihonga"], sources: BATCH_08_SOURCES.tosa, zh: ["绘卷、册页、小屏风或扇面采用紧密分场和叙事节奏，金云只按作品需要使用", "极细轮廓、程式化人物和精密衣纹建筑随题材调整", "群青、朱红、石绿、金和高明度纸绢常见，也有较克制方案", "综合色分区和金属反光建立层次，不以金色辉光覆盖全部表面", "纸绢、矿物综合色、金箔、精细墨线、反复罩染和装裱接缝", "题签和词书必须准确且有来源；不得仿造土佐家画家署名和印章"], en: ["handscrolls, albums, small screens, or fans using dense compartments and narrative rhythm, with gold clouds only where appropriate", "extremely fine contours, codified figures, and precise textile or architecture adjusted to subject", "ultramarine, vermilion, mineral green, gold, and light supports as common but not mandatory choices", "depth through color zones and metal reflection without a universal golden glow", "paper or silk, mineral color, gold leaf, fine ink line, repeated glazing, and mounting seams", "titles and text must be exact and sourced; never fabricate a Tosa-family signature or seal"] },
  "japanese-zen-ink-painting": { period: "约13世纪末–16世纪，后续影响延长", year: 1450, summary: "日本禅宗水墨画在镰仓、室町时期借僧侣、寺院和中日交流吸收宋元水墨，涵盖道释人物、山水、顶相和诗画轴。简笔留白只是部分路线，周文、雪舟、牧谿接受等传统的构图与墨法并不相同。", influencedBy: "中国宋元禅宗绘画和水墨、五山寺院网络、僧侣交流与日本绘画传统", influenced: "室町水墨、狩野派早期、日本南画和后世禅画接受", related: ["zen-painting", "kano-school", "japanese-nanga", "zhe-school"], sources: BATCH_08_SOURCES.zenInk, zh: ["偏心小景、全景山水、诗画轴或正面顶相按门类选择，不固定为单一焦点大留白", "迅疾简笔、层层皴染、精确肖像线或浓淡突变依据具体画家作品", "墨黑、淡墨、纸绢底和少量淡彩，不将单色设为绝对规则", "墨阶、虚实和雾化边缘建空间，不模拟统一禅意柔光", "纸绢、水墨、飞白、积墨、渗化、题诗轴和真实保存痕迹", "只在诗文原文可靠且能准确呈现时加入；不生成伪汉诗、伪禅语或僧名"], en: ["off-center vignettes, panoramic landscapes, poem-painting scrolls, or frontal portraits selected by genre rather than one isolated focus", "abbreviated marks, layered texture, precise portrait line, or abrupt ink contrast grounded in a specific painter and work", "deep and pale ink, paper or silk, and occasional light color without mandatory monochrome", "space through ink value, solid-void relation, and misted edges rather than one meditative soft-light effect", "paper or silk, ink, flying-white breaks, accumulated washes, poem scrolls, and genuine condition traces", "add poetry only when the source is reliable and exact; never fabricate Chinese verse, Zen sayings, or monks' names"] },
  "kano-school": { period: "约15世纪中期–19世纪", year: 1600, summary: "狩野派是从室町延续至江户末期、服务幕府和众多委托人的大型职业画家家系，内部跨越水墨、金碧屏障画、人物花鸟和不同地域支系。金地巨幅和强劲墨线是显著路线，但不能代表四百余年全部狩野绘画。", influencedBy: "中国宋元水墨、日本禅宗绘画、大和绘和武家宫廷委托制度", influenced: "桃山江户屏障画、各地职业画坛和日本近世绘画教育", related: ["japanese-zen-ink-painting", "tosa-school", "rinpa", "nihonga"], sources: BATCH_08_SOURCES.kano, zh: ["大画面屏风、襖绘、卷轴或扇面按建筑和委托组织，可纪念性也可细密", "强劲墨线、概括体块、精细鸟兽人物和装饰性色面随支系时期变化", "水墨、金地、矿物蓝绿、朱红和纸绢本色均可，不固定黑金综合色", "真实室内环境光与金箔反射或墨阶共同塑形，避免统一辉光", "屏风纸、金箔、水墨、矿物综合色、木构接缝和可见笔触", "仅在来源作品确有题记或用户文字准确时加入；不得仿造狩野家署名印章"], en: ["large screens, sliding doors, hanging scrolls, or fans organized by architecture and commission at monumental or intimate scale", "forceful ink, reduced masses, meticulous flora-fauna or figures, and decorative color varying by branch and date", "ink, gold ground, mineral blue-green, vermilion, and exposed support without one black-gold palette", "real interior light and gold reflection or graded ink building form without a universal glow", "screen paper, gold leaf, ink, mineral color, wooden joins, and visible brushwork", "add text only when documented on the work or supplied exactly; never fabricate Kano-family signatures or seals"] },
  "rinpa": { period: "17世纪初形成，18–19世纪多次复兴并延续至今", year: 1700, summary: "琳派是后世用于概括俵屋宗达、尾形光琳及酒井抱一等跨世代复兴网络的称谓，不是同时成立的正式画派。屏风跨幅、金银地、节奏化形体和湿中叠染重要，但成员、年代和媒介差异很大。", influencedBy: "大和绘、古典文学与书法、工艺设计、俵屋工房和宫廷文化", influenced: "江户装饰艺术、日本画、现代设计和国际对日本平面性的接受", related: ["yamato-e", "tosa-school", "ukiyo-e", "nihonga"], sources: BATCH_08_SOURCES.rinpa, zh: ["跨屏非对称、偏置重心、重复裁切或图案满幅按具体世代和媒介选择", "简化流线、植物动物节奏和书写形体可平面也可保留观察细节", "金银地、群青、朱红、石绿、墨和纸色随作品变化，不限定华丽综合色", "金属箔真实反射、综合色层和湿中叠染产生空间，不统一为无影平面", "纸绢、金银箔、矿物综合色、云母、墨和垂らし込み形成的潮边", "只在作品需要且文字准确时使用书法；不得仿造宗达、光琳、抱一的落款印章"], en: ["multipanel asymmetry, offset centers, repeated crops, or all-over pattern selected by generation and medium", "reduced flowing forms, rhythmic flora-fauna, and calligraphic shapes ranging from flat to observant detail", "gold-silver grounds, ultramarine, vermilion, mineral green, ink, and support color varying by work", "real metal-leaf reflection, color layers, and wet-on-wet pooling creating space rather than universal shadowless flatness", "paper or silk, metal leaf, mineral pigment, mica, ink, and tarashikomi tide lines", "use calligraphy only when needed and exact; never imitate the signatures or seals of Sotatsu, Korin, or Hoitsu"] },
  "ukiyo-e": { period: "约17世纪后期–19世纪，江户时期为核心", year: 1800, summary: "浮世绘是江户城市文化中的绘画与木版画体系，题材包括役者、美人、名所、相扑、春画、武者和讽刺等，并依赖版元、绘师、雕师和摺师协作。大胆裁切与平面套色很重要，但早期墨摺、锦绘、风景和肉笔画不共享固定靛蓝朱红综合色。", influencedBy: "江户城市出版、绘本和肉笔画、歌舞伎与游里文化、大和绘和汉画资源", influenced: "日本近代版画、印象派和新艺术、现代漫画与全球大众图像", related: ["shin-hanga", "sosaku-hanga", "manga", "art-nouveau"], sources: BATCH_08_SOURCES.ukiyoe, zh: ["非对称裁切、连续组画、扇面或较稳定中心构图依题材和时期变化", "清楚主版线、平面色块、云母或空摺细节，也包括无综合色墨摺与肉笔绘画", "综合色从墨摺单色到多版锦绘，靛蓝、朱红和纸色只是常见选择", "印刷图像多以综合色边界和重叠建空间，风景版可有大气综合色而非写实投影", "多版木刻、和纸、颜料、云母、空摺、木纹和可辨套印微差", "准确保留题名、役者名、版元印和改印；不杜撰历史署名、审查印或日文"], en: ["asymmetric crops, print-series continuity, fan formats, or stable centering varying by subject and period", "clear key-block line, flat color, mica or blind-print detail alongside monochrome prints and hand paintings", "color ranging from monochrome ink to multiblock brocade prints, with indigo, vermilion, and paper only common options", "space mainly through color boundaries and overlap, with atmospheric color in landscapes rather than realistic cast shadow", "multiblock woodcut, washi, pigment, mica, blind printing, wood grain, and legible registration variation", "preserve titles, actor names, publisher and censor seals accurately; never fabricate signatures, marks, or Japanese text"] },
  "japanese-nanga": { period: "约18–19世纪，江户时期", year: 1800, summary: "日本南画或文人画是江户画家通过中国画谱、输入绘画、诗文与想象重构的文人实践，并非中国文人画的直接复制。职业身份、社交和地方网络多样，池大雅、与谢芜村等人的笔墨、设色和题材也不一致。", influencedBy: "中国明清文人画和画谱、输入书画、汉诗文化与日本文人社交", influenced: "近代日本南画、日本画讨论和东亚文人画接受史", related: ["yuan-literati-painting", "japanese-zen-ink-painting", "nihonga", "ink-wash"], sources: BATCH_08_SOURCES.nanga, zh: ["平远层叠、密集山水、诗画轴或册页按画家选择，不统一为疏淡书斋小景", "干笔皴擦、松动轮廓、点线和设色形态来自对中国图像的个体再解释", "墨、淡赭、透明青绿和纸色常见，也有综合色更丰富作品", "墨阶与设色层建立空间，不强制均匀柔光和无投影审美", "纸绢、水墨、透明淡彩、干湿笔触、汉诗题跋和印章", "只在汉诗或日文原文可准确呈现时加入；不得仿造池大雅、芜村等手迹"], en: ["level distance, dense landscape, poem-painting scrolls, or albums selected by painter rather than one sparse studio vignette", "dry texture, loosened contour, dots, lines, and color arising from individual reinterpretations of Chinese imagery", "ink, pale ochre, transparent blue-green, and paper alongside more varied color in some works", "space built through ink and color layers without mandatory even soft light or shadowless aesthetics", "paper or silk, ink, transparent light color, dry-wet brushwork, Chinese-style poetry, and seals", "add Chinese verse or Japanese only when exact; never imitate the hands of Ike no Taiga, Buson, or other painters"] },
  "nihonga": { period: "约1880年代至今", year: 1910, summary: "日本画是明治时期在现代美术制度和西洋画对照中形成的分类，使用胶彩、矿物综合色、纸绢等传统资源，同时不断吸收写生、透视和现代题材。它不是古代日本绘画的原样延续，也没有统一的柔和综合色与浅空间。", influencedBy: "江户诸画派、明治美术教育、传统材料复兴、西洋画和现代展览制度", influenced: "20世纪日本绘画、东亚胶彩画和现代传统绘画教育", related: ["rinpa", "kano-school", "yamato-e", "lingnan-school"], sources: BATCH_08_SOURCES.nihonga, zh: ["屏风、卷轴、展览画幅和现代裁切均可，空间从平面装饰到写实纵深", "精细勾线、没骨、颗粒综合色面或写生造型按艺术家和时期选择", "矿物综合色、胡粉、墨、金属箔与现代综合色构成广泛范围，不强制低饱和", "综合色层、胡粉和金属反射或现代观察光共同塑形，避免统一柔光", "和纸或绢、岩综合色、胶、胡粉、墨、金属箔和颗粒哑光表面", "只在作品需要且文字准确时使用现代题款，不仿造艺术家署名印章"], en: ["screens, scrolls, exhibition-scale formats, and modern cropping with space ranging from decorative flatness to observed depth", "fine contour, boneless color, granular pigment planes, or observational modeling selected by artist and date", "mineral pigment, gofun, ink, metal leaf, and modern color across a broad range without mandatory muted tones", "form through pigment layers, gofun, metal reflection, or modern observed light without one soft-light formula", "washi or silk, mineral pigment, animal glue, gofun, ink, metal leaf, and granular matte surfaces", "use a modern inscription only when needed and exact; never imitate an artist's signature or seal"] },
  "shin-hanga": { period: "约1915–1960年代", year: 1930, summary: "新版画由渡边庄三郎等版元推动，以绘师、雕师、摺师分工更新浮世绘版画，面向国内外市场并吸收写实光色。雨雪夜景和美人风景著名，却只是题材路线之一；其核心也不是所有作品都柔和怀旧。", influencedBy: "浮世绘协作生产、明治新版技术、西方写实和国际版画市场", influenced: "20世纪日本木版画、旅游图像和国际对现代日本版画的收藏", related: ["ukiyo-e", "sosaku-hanga", "japanese-modern-poster", "nihonga"], sources: BATCH_08_SOURCES.shinHanga, zh: ["现代裁切、单一焦点、纵深风景或人物半身像按题材选择", "精细主版线、多版渐层、空摺和写实细节由专业雕摺协作完成", "综合色可柔和或鲜明，深蓝夜色、暖红和纸白并非固定配方", "日光、夜光、雨雪和室内光通过版次渐层表达，而非数字柔光滤镜", "精细木版、和纸、颜料、ぼかし渐层、空摺、云母和准确套印", "只准确呈现原作题名、版元印和艺术家署名；现代新增文字用可读字体并明确区分"], en: ["modern crops, single focal points, deep landscapes, or half-length figures selected by subject", "fine key-block line, multiblock gradation, blind printing, and observed detail produced through specialist collaboration", "color ranging from muted to vivid without fixing deep night blue, warm red, and paper white as a formula", "day, night, rain, snow, and interior light translated through printed gradation rather than a digital soft-glow filter", "fine woodblocks, washi, pigment, bokashi gradation, blind printing, mica, and precise registration", "preserve original titles, publisher marks, and signatures accurately; distinguish any modern added text in legible type"] },
  "sosaku-hanga": { period: "约1904年起，20世纪前中期集中发展", year: 1935, summary: "创作版画以“自画、自刻、自摺”强调艺术家的直接创作，反对版元分工成为定义艺术价值的唯一机制，但实践中也有协作和多种版种。粗刀痕与错版并非必然，木版、水印、拓印和抽象路线差异明显。", influencedBy: "近代个人艺术观、浮世绘和民间版画、欧洲版画与日本美术教育", influenced: "日本现代版画、战后国际版画交流和个人工作室印刷", related: ["shin-hanga", "ukiyo-e", "woodcut-aesthetic", "japanese-modern-poster"], sources: BATCH_08_SOURCES.sosakuHanga, zh: ["直接不对称、块面构成、具象场景或抽象结构按艺术家选择，保留版面决策", "刀刻粗线、细线、木纹、拓印或几何块面皆可，不把粗糙当作真实性标志", "黑色主版、有限套色、多综合色或纸张本色随版种与艺术家改变", "平面综合色关系、透明水印和纸面吸收建立层次，不强制无影", "自刻木版、和纸、刀痕、水性或油性油墨、套印微差和手工压印", "文字只在作品需要且准确时与版块关系整合，不伪造艺术家刻款"], en: ["direct asymmetry, block construction, observed scenes, or abstraction selected by artist with visible compositional decisions", "coarse or fine carving, wood grain, rubbing, or geometric planes without treating roughness as proof of authenticity", "black key blocks, restricted or multicolor printing, and exposed paper varying by process and artist", "flat color relations, transparent water-based impressions, and paper absorption creating depth without mandatory shadowlessness", "artist-cut blocks, washi, knife marks, water- or oil-based ink, registration variation, and hand pressure", "integrate text with the block only when needed and exact; never fabricate an artist's carved signature"] },
  "kawaii": { period: "约1970年代至今，前史更早", year: 1985, summary: "卡哇伊是日本关于可爱、幼态和亲和感的广泛文化概念，1970年代后通过少女书写、角色商品、时尚和媒体显著扩展。它不是一套固定粉彩大眼比例，也包含简朴、怪趣、成人化和品牌化等不同路线。", influencedBy: "少女文化、丸文字等青年书写、角色商品、漫画动画和消费媒体", influenced: "日本及全球角色设计、时尚、品牌、界面和网络亚文化", related: ["manga", "anime", "superflat", "decora-kei"], sources: BATCH_08_SOURCES.kawaii, zh: ["贴纸模块、角色中心、重复小图标或留白式商品布局按媒介选择", "圆润幼态是常见机制，也可用极简符号、怪趣反差和非人角色，不固定大眼", "粉彩、高明度原色、黑白或品牌标准色均可，不设糖果综合色规则", "平面印刷、赛璐璐或商品展示光按载体处理，不统一为柔亮发光", "纸品、塑料、毛绒、乙烯基、印刷和干净数字表面依商品媒介变化", "文字必须准确可读；可采用圆润、手写或品牌字体，但不得生成无义日文"], en: ["sticker modules, centered characters, repeated small icons, or spacious product layouts selected by medium", "rounded juvenile form as one common mechanism alongside minimal symbols, odd-cute contrast, and nonhuman characters without mandatory large eyes", "pastels, high-key primaries, black-white, or brand standards without one candy palette", "flat print, cel treatment, or product display light selected by support rather than one soft glow", "paper goods, plastic, plush, vinyl, print, and clean digital surfaces varying by product medium", "text must remain exact and legible; rounded, handwritten, or brand type is possible, but never generate meaningless Japanese"] },
  "manga": { period: "现代漫画约19世纪末至今，1945年后产业扩张", year: 1970, summary: "漫画是日本多类型的连续图像与出版文化，现代形式在19世纪末至战后发展，横跨儿童、少女、少年、青年和实验漫画。分格、网点、速度线和夸张表情只是可选语法；绘本式全页、写实剧画和数字彩漫同样存在。", influencedBy: "日本绘卷和图像出版、讽刺漫画、西方连环漫画、战后出版与动画产业", influenced: "日本动画、游戏、全球漫画生产和当代艺术", related: ["anime", "ukiyo-e", "gekiga", "superflat"], sources: BATCH_08_SOURCES.manga, zh: ["规则或破格分镜、全页画面、跨页和留白按叙事节奏组织", "线条从简化卡通到剧画写实，速度线、表情符号和网点按类型选用", "黑白墨稿和网点长期重要，也有双色、全彩和数字综合色漫画", "明暗由墨块、线影、网点或综合色完成，不设统一赛璐璐光", "纸墨、蘸水笔、网点纸、印刷网纹、修正痕迹或数字线稿", "对白、拟声词和阅读顺序必须准确；不生成乱码日文，不让装饰字破坏可读叙事"], en: ["regular or broken panels, splash pages, spreads, and open intervals organized by narrative pacing", "line ranging from simplified cartooning to realistic gekiga, with speed lines, symbols, and screentone selected by genre", "black-white ink and screentone as important traditions alongside two-color, full-color, and digital manga", "value through solid ink, hatching, screentone, or color without one cel-lighting formula", "paper and ink, dip-pen line, adhesive tone, printed halftone, correction traces, or digital linework", "dialogue, sound effects, and reading order must be exact; generate no gibberish Japanese and keep display lettering narratively legible"] },
  "anime": { period: "日本动画约1910年代至今，战后电视与电影体系扩张", year: 1980, summary: "日本动画是由不同工作室、技术、题材和受众构成的动画产业与创作传统，不是固定角色比例或大眼赛璐璐风。有限动画、分镜和分层摄影影响深远，但全动画、木偶、实验、数字三维与作者电影也属于其范围。", influencedBy: "早期国际动画、日本漫画和电影、战后工作室体系、电视生产和数字技术", influenced: "全球动画、游戏、角色产业、网络影像和当代视觉文化", related: ["manga", "kawaii", "superflat", "jrpg-interface-aesthetic"], sources: BATCH_08_SOURCES.anime, zh: ["电影化分镜、有限动画的关键姿势、长镜头或实验节奏按作品生产方式选择", "角色、机械、背景和抽象形态从高度简化到写实，不固定外轮廓与比例", "赛璐璐综合色、综合色摄影、手绘水彩背景或数字三维综合色均可", "综合色分区、摄影台光效、自然观察或数字合成依年代与场景处理", "赛璐璐、铅笔线、背景画、摄影颗粒、数字上色、合成和三维渲染", "片名、字幕和画内文字必须准确并符合年代；不得生成无义日文或仿造作品标志"], en: ["cinematic boards, limited-animation key poses, long takes, or experimental pacing selected by work and production method", "characters, machines, backgrounds, and abstract forms ranging from highly reduced to realistic without fixed outline or proportion", "cel color, color photography, painted watercolor backgrounds, or digital three-dimensional color as appropriate", "color separation, rostrum-camera effects, observed light, or digital compositing selected by date and scene", "cels, pencil line, background painting, photographic grain, digital color, compositing, and 3D rendering", "titles, subtitles, and diegetic text must be exact and date-appropriate; never generate gibberish Japanese or copy a production logo"] },
  "japanese-modern-poster": { period: "约1950年代至今", year: 1970, summary: "日本现代海报不是单一“留白、红黑、太阳圆”的民族样式，而是战后设计师在摄影、字体、丝网、传统图像、超现实拼合和商业文化之间形成的多条路线。龟仓雄策、田中一光、横尾忠则等人的视觉机制差异尤其显著。", influencedBy: "战前日本商业美术、国际现代主义、摄影印刷、传统表演图像和战后消费文化", influenced: "国际海报、企业与文化视觉、时尚和当代日本平面设计", related: ["swiss", "japanese-corporate-identity-design", "pop-art", "psychedelic"], sources: BATCH_08_SOURCES.poster, zh: ["强中心图形、非对称留白、密集拼贴或网格信息结构按设计师与委托选择", "摄影、几何符号、书写线、历史图像和超现实合成各自保持来源关系", "黑白红只是常见方案，也使用综合色摄影、荧光、传统综合色和复杂印刷色", "平面印刷光与来源摄影明暗协调，丝网叠印可形成综合色透明层", "胶印、丝网、照片网点、套印、纸张和后期数字合成随年代变化", "日文与拉丁字必须准确可读；字体、基线和尺度服从信息，不以伪日文制造地域感"], en: ["strong central images, asymmetric open ground, dense collage, or gridded information selected by designer and commission", "photography, geometric signs, written marks, historical images, and surreal composites preserving their source relations", "black-white-red as one common option alongside color photography, fluorescent ink, traditional color, and complex process color", "flat print illumination coordinated with source-photograph light, with transparent color possible through screen overprinting", "offset, screenprint, photographic halftone, overprint, paper, and later digital compositing varying by date", "Japanese and Latin text must be exact and legible; typeface, baseline, and scale serve information rather than using pseudo-Japanese for locality"] },
  "japanese-corporate-identity-design": { period: "约1950–1980年代形成重要体系并延续至今", year: 1975, summary: "战后日本企业识别涵盖标志、字体、色彩、包装、导视和应用规范，是企业现代化与国际化的一部分；几何徽记和留白常见，却受到公司、行业、技术和设计师方法影响。它不能被归结为黑白加朱红的紧凑圆形标志。", influencedBy: "国际现代主义、战前商标、战后工业与企业扩张、设计组织和印刷标准化", influenced: "日本企业品牌、公共导视、产品设计和东亚现代视觉识别", related: ["swiss", "japanese-modern-poster", "international-corporate-identity", "japanese-modernism"], sources: BATCH_08_SOURCES.identity, zh: ["标志、标准字、网格和应用载体形成系统，单个徽记不代替完整识别", "几何、文字标、负形、汉字假名或具象符号按企业语义和缩放要求构造", "标准色可红、蓝、绿、多色或材料本色，不设日本企业统一配色", "标志本体保持平面清楚，产品、建筑和导视保留真实环境光", "印刷硬边、珐琅标牌、包装纸、塑料、金属和数字矢量应用", "公司名和日文必须准确；标准字与拉丁字协同并满足小尺寸可读性，不伪造品牌"], en: ["marks, logotypes, grids, and applications forming a system rather than treating one emblem as the whole identity", "geometry, wordmarks, negative space, kanji-kana, or pictorial signs constructed for corporate meaning and scale", "standard color in red, blue, green, multicolor, or inherent material without one Japanese corporate palette", "the mark remains flat and clear while products, architecture, and signage retain real ambient light", "crisp print, enamel signs, packaging paper, plastic, metal, and digital vector applications", "company names and Japanese text must be exact; coordinate logotype and Latin text for small-size legibility and never fabricate brands"] },
  "superflat": { period: "约2000年前后提出并延续至今", year: 2000, summary: "超扁平由村上隆在2000年前后以展览和论述提出，既指压缩图像纵深的视觉语言，也批判性连接日本战后消费、御宅文化、动画漫画和艺术市场。糖果色、可爱角色只是部分作品；其理论和参与艺术家不能缩减为通用扁平插画。", influencedBy: "日本画平面性论述、漫画动画、御宅文化、波普艺术、消费与战后社会批评", influenced: "当代日本艺术、角色和品牌跨界，以及全球对动画式艺术的接受", related: ["pop-art", "manga", "anime", "kawaii"], sources: BATCH_08_SOURCES.superflat, zh: ["无纵深满幅、商品陈列、重复角色或空旷色场按艺术家作品选择", "均匀轮廓和平面剪影可与怪诞、性化、暴力或传统图像引用并存", "高饱和综合色常见，也有黑白、有限色和传统日本画综合色", "视觉纵深被压缩，但光泽、综合色层与物件展示光依媒介区分", "丙烯、丝网、数字印刷、雕塑光泽、动画线和日本画材料均可", "文字、商标和引用必须准确并说明挪用关系；不得复制村上隆等艺术家的受保护角色"], en: ["depthless all-over fields, product display, repeated characters, or sparse color expanses selected by artist and work", "uniform contours and flat silhouettes alongside grotesque, sexual, violent, or historical-image references", "high saturation as common alongside black-white, restricted color, and traditional nihonga systems", "compressed pictorial depth with gloss, color layers, and object-display light differentiated by medium", "acrylic, screenprint, digital print, glossy sculpture, animation line, and nihonga materials", "text, brands, and quotations must be exact and their appropriated status clear; do not copy protected characters by Murakami or other artists"] },
  "ainu-pattern-aesthetic": { period: "传统至今，具体形式因地区、社群和载体而异", year: 1850, summary: "阿伊努纹样属于阿伊努社群的服饰、刺绣、木雕和器物传统，不应被泛称为“北海道装饰”。括弧状与涡旋母题常见，但名称、组合、性别分工和意义依地区与家族而变；当代使用必须尊重文化归属，避免伪造神圣意义。", influencedBy: "阿伊努社群的纤维、服饰、木雕与口传知识，以及区域间材料交流", influenced: "当代阿伊努艺术、博物馆复兴、服饰设计和原住民文化教育", related: ["ryukyu-bingata-aesthetic", "japanese-folk-craft-aesthetic", "indigenous-contemporary-art"], sources: BATCH_08_SOURCES.ainu, zh: ["衣领、袖口、下摆和背部等载体位置形成边带、镜像或中心结构，按真实物件选择", "括弧状、涡旋和连续护边线按具体地区与制作者使用，不拼造成通用部落纹", "靛蓝、黑、白、红和树皮纤维本色来自染布、贴布和刺绣材料", "均匀织物光显示线迹、贴布厚度和纤维，不添加神秘发光效果", "树皮布、棉布、贴布、刺绣、植物染、可见针迹和真实使用磨损", "现代文字用中性可读字体并与纹样分开；不得发明阿伊努语、仪式符号或神圣释义"], en: ["bands, mirror relations, or centered structures placed at collars, cuffs, hems, backs, and other object-specific locations", "bracket-like, spiral, and continuous guarding lines used from a specific region and maker rather than assembled as generic tribal pattern", "indigo, black, white, red, and bark-fiber color derived from dyed cloth, applique, and embroidery", "even textile light revealing stitches, applique thickness, and fiber without mystical glow", "attush bark cloth, cotton, applique, embroidery, plant dye, visible stitching, and genuine use wear", "keep modern text separate in neutral legible type; never invent Ainu language, ritual signs, or sacred meanings"] },
  "ryukyu-bingata-aesthetic": { period: "约14–15世纪形成，琉球王国时期发展并延续至今", year: 1750, summary: "红型是琉球群岛发展出的型纸防染传统，与王府服饰、地域材料和东亚海上贸易密切相关。花鸟、风景和重复纹样及鲜明综合色常见，但阶层、用途、地色、工序和岛屿传统有差异，不能作为泛日本热带纹样随意挪用。", influencedBy: "琉球纺织和王府文化、型纸防染、东亚及东南亚海上贸易中的综合色与纹样交流", influenced: "冲绳染织、当代琉球工艺复兴、服饰和区域文化设计", related: ["ainu-pattern-aesthetic", "katazome-aesthetic", "okinawan-cultural-aesthetic"], sources: BATCH_08_SOURCES.bingata, zh: ["布面满幅、分区重复、衣片位置或中心留地按服饰和用途组织", "型纸边缘、防染留线、花鸟风景和重复单元保持手工套版关系", "综合色主色、布底和综合色叠加依用途阶层变化，不固定高饱和热带配色", "均匀织物光显示染料吸收和布纹，不使用塑料高光或数码霓虹", "棉麻或芭蕉布、型纸、糊防染、颜料与染料、刷染、纤维渗化和套版微差", "现代文字须准确并与传统纹样区分；不得伪造琉球语、王府纹章或文化含义"], en: ["all-over cloth, compartmented repeats, garment-piece placement, or reserved centers organized by dress and use", "stencil edges, resist lines, flora-fauna or landscapes, and repeated units retaining hand-registered relations", "primary dyes, cloth ground, and layered mixed color varying by function and status without one saturated tropical palette", "even textile light revealing dye absorption and weave without plastic highlights or digital neon", "cotton, hemp or bashofu, stencils, rice-paste resist, pigment and dye, brushing, fiber bleed, and small registration variation", "keep modern text exact and distinct from the traditional pattern; never invent Ryukyuan language, royal emblems, or cultural meanings"] }
};

