const BATCH_09_REVIEWS = {
  "korean-minhwa": { period: "约18世纪后期–20世纪初，后续复兴延长", year: 1850, summary: "民画（minhwa）是后世用于概括朝鲜王朝后期及近代多类非宫廷或民间绘画的弹性称谓，题材包括文字图、虎鹊、花鸟、山水、册架与吉祥图像。它不是单一“稚拙”风格，作者、用途、制作水平和与宫廷图像的关系差异很大。", influencedBy: "朝鲜宫廷绘画、儒释道与民间信仰、岁时生活、工匠和城市图像市场", influenced: "韩国现代民俗图像、设计和对朝鲜绘画的再评价", related: ["chaekgeori", "korean-ink-abstraction", "chinese-new-year-print", "gongbi"], sources: BATCH_09_SOURCES.minhwa, zh: ["正面、对称、屏风分幅、连续故事或不稳定透视按题材使用，不设统一满幅布局", "轮廓从精细宫廷式到大胆概括不等，程式化动物器物须按真实题材选择", "朱红、蓝绿、黄、墨与纸绢底常见，也有淡彩或单色作品", "平面色区、有限晕染和物体叠置建立层次，不强制反常透视", "纸绢、墨、矿物或植物色、屏风装裱、手工线和真实老化", "准确保留文字图汉字、题记和印章；无法核实时不生成伪汉字或吉语"], en: ["frontal, symmetrical, screen-panel, continuous-story, or unstable-perspective layouts selected by subject rather than one all-over formula", "contours ranging from courtly precision to bold reduction, with codified animals and objects used from real subject traditions", "vermilion, blue-green, yellow, ink, and paper or silk alongside light-color and monochrome works", "depth through flat color, limited shading, and object overlap without mandatory reverse perspective", "paper or silk, ink, mineral or vegetable color, screen mounting, handmade line, and genuine aging", "preserve characters, inscriptions, and seals accurately in munjado and related works; omit them when they cannot be verified"] },
  "chaekgeori": { period: "约18世纪后期–19世纪，朝鲜王朝后期", year: 1800, summary: "册架图（chaekgeori）以书籍、文房、古董和珍奇物陈列表达学问、身份与愿望，18世纪后期从宫廷屏风扩展到民间版本。架格式结构和多重透视很重要，但无架册巨里、宫廷精绘与民画化作品并不共享同一密集格柜。", influencedBy: "朝鲜宫廷文化、儒家尚学观念、清代多宝格与输入图像、透视和静物画交流", influenced: "朝鲜后期民画、屏风陈设和当代韩国对书籍图像的复兴", related: ["korean-minhwa", "gongbi", "jiehua", "chinese-new-year-print"], sources: BATCH_09_SOURCES.chaekgeori, zh: ["格柜分区、无架物件堆叠或屏风跨幅陈列按宫廷与民间版本选择", "书册、瓷器、文房和珍奇物以清楚轮廓及多角度物面组合，不套用单一反向透视", "矿物红绿蓝、墨黑、金和纸绢底色从克制宫廷色到鲜明民画色不等", "局部明暗、物件重叠和多重视点共同建空间，不使用统一均匀柔光", "纸绢设色、细墨线、矿物综合色、屏风接缝和物件表面细节", "只有书脊和题签文字可核实时准确呈现；不生成看似汉字的装饰乱码"], en: ["shelved compartments, shelf-free object stacks, or multipanel displays selected by courtly or popular version", "books, ceramics, scholars' objects, and curios combined through clear contour and several object viewpoints rather than one reverse-perspective rule", "mineral red, green, blue, black, gold, and the support ranging from restrained court color to vivid popular color", "local modeling, overlap, and multiple viewpoints building space without one even-soft-light formula", "color on paper or silk, fine ink line, mineral pigment, screen joins, and specific object surfaces", "render book-spine and label text only when verifiable and exact; never generate decorative pseudo-characters"] },
  "dansaekhwa": { period: "约1970年代形成，术语与国际接受后期固化并延续至今", year: 1975, summary: "韩国单色画（Dansaekhwa）是对1970年代起若干韩国艺术家近单色、重复动作和材料过程的后设集合称谓，而非当时纲领统一的团体。白色和禅意并非必要条件；刮、推、浸透、折叠与画布关系因艺术家而异，也不能简单等同西方极简主义。", influencedBy: "韩国战后艺术、实验艺术、传统材料观、现代抽象和日本及国际展览网络", influenced: "韩国当代艺术、过程性绘画和21世纪国际市场对战后亚洲抽象的重估", related: ["korean-ink-abstraction", "minimalism", "monochrome-painting", "post-minimalism"], sources: BATCH_09_SOURCES.dansaekhwa, zh: ["满幅、网格、重复线或材料渗透按艺术家过程组织，不以空白中心代表单色画", "推、刮、点、压、折或反面渗透产生微小单元和真实表面起伏", "白、灰、土色、深蓝和其他窄综合色域均可，不把白色设为韩国性", "柔侧光揭示真实低浮雕、纤维和微综合色差，避免精神化辉光", "油彩、铅笔、麻布、韩纸、颜料吸收、重复劳动和物理磨损", "文字通常不进入画面；如需说明，只用画面外中性准确标签"], en: ["all-over fields, grids, repeated lines, or material penetration organized by an artist's process without making a blank center definitive", "pushing, scraping, dotting, pressing, folding, or reverse soaking producing minute units and real relief", "white, gray, earth color, deep blue, and other narrow ranges without treating white as an ethnic essence", "soft grazing light revealing actual low relief, fiber, and minute color differences without spiritualized glow", "oil paint, pencil, hemp cloth, hanji, pigment absorption, repeated labor, and physical abrasion", "text normally remains outside the work; when needed, use a neutral accurate label beyond the pictorial field"] },
  "korean-ink-abstraction": { period: "约1950年代至今", year: 1980, summary: "韩国水墨抽象是对战后至当代艺术家以墨、韩纸、书写和现代抽象进行实验的宽泛描述，不是成员固定的画派。它与传统书画、国际抽象、政治社会经验和材料实验的关系因世代而异，也不能只用留白、泼墨和黑白概括。", influencedBy: "朝鲜书画传统、现代主义抽象、战后韩国经验、书法和韩纸材料", influenced: "韩国当代绘画、装置、纸本艺术和跨媒介水墨", related: ["dansaekhwa", "ink-wash", "abstract-expressionism", "contemporary-ink"], sources: BATCH_09_SOURCES.koreanInk, zh: ["开放留白、满幅墨场、拼接纸面、网格或装置尺度按艺术家路线变化", "书写线、泼洒、渗透、撕裂、拓印和抽象结构不必保留传统题材", "墨黑灰阶、韩纸本色及综合色介入均可，单色不是定义条件", "墨色浓淡、纸面吸收和真实展场光共同产生空间，不设统一柔光", "韩纸、墨、综合色、拼接、揉皱、渗化、皴擦和跨媒介材料", "文字或书法仅在作品确有语义且可准确呈现时使用，不生成伪韩文或伪汉字"], en: ["open ground, all-over ink fields, joined paper, grids, or installation scale varying by artist", "written line, pouring, penetration, tearing, rubbing, and abstract structures without requiring traditional subject matter", "black-gray ink, natural hanji, and chromatic interventions all possible, with monochrome not definitive", "space through ink value, paper absorption, and real exhibition light rather than one soft-light treatment", "hanji, ink, color, joins, crumpling, diffusion, texture strokes, and cross-media materials", "use text or calligraphy only when semantically part of the work and exact; never generate pseudo-Korean or pseudo-Chinese writing"] },
  "dong-ho-painting": { period: "约17世纪至今，以越南北宁东湖村传统为核心", year: 1850, summary: "东湖民间木版画以越南北宁地区作坊、节庆市场和日常讽喻题材著称，常用由贝壳粉制成的điệp纸及多个色版和主线版印刷。单一主图和天然综合色常见，但题材、版次与当代材料已发生变化，不能借用南亚细密画模板。", influencedBy: "越南雕版印刷、春节习俗、村落市场、民间故事和社会讽喻", influenced: "越南大众图像、现代版画、节庆设计和非遗保护", related: ["chinese-new-year-print", "ukiyo-e", "woodcut-aesthetic", "vietnamese-lacquer-painting"], sources: BATCH_09_SOURCES.dongHo, zh: ["单幅主图、平面基线或简短群组服务寓意和讽喻，保留明确边缘空地", "不同综合色版配黑色主线形成概括人兽轮廓，套准保留手工微差", "传统红、黄、绿、黑与điệp纸银白来自不同综合色版，现代版可有材料变化", "完全平面印刷明度，纸面贝壳粉产生细微散射而非金属高光", "木版、水性综合色、竹纸与贝壳粉涂层、版痕、套印微差和纤维", "准确呈现可核实的越南文题名或说明；不生成乱码越南语和伪作坊印"], en: ["single main images, flat baselines, or concise groups serving allegory and satire with clear edge ground", "separate color blocks and a black key block forming reduced human and animal contours with handmade registration variation", "traditional red, yellow, green, black, and the silvery diep-paper ground from separate impressions, with modern material changes possible", "fully flat print value with subtle shell-powder diffusion rather than metallic highlights", "woodblocks, water-based color, bamboo paper with shell-powder coating, block marks, registration variation, and fiber", "show Vietnamese titles or explanations only when verifiable and exact; never generate gibberish or false workshop marks"] },
  "vietnamese-lacquer-painting": { period: "约1920–1930年代形成现代画种并延续至今", year: 1940, summary: "越南现代漆画（sơn mài）在印度支那美术学院语境中由艺术家把传统漆器材料转化为架上绘画，通过多层天然漆、朱砂、金银、蛋壳与反复研磨显露综合色层。它既涉及殖民教育也包含越南艺术家的技术创新，不能等同黑红金的光滑装饰画。", influencedBy: "越南漆器工艺、法国殖民美术教育、现代绘画和本地艺术家的材料实验", influenced: "越南现代主义、东南亚漆画和当代综合材料绘画", related: ["nanyang-style", "philippine-modernism", "modern-asian-art", "dong-ho-painting"], sources: BATCH_09_SOURCES.vietnameseLacquer, zh: ["大色面、浅层叠置、叙事群像、风景或抽象结构按艺术家安排", "轮廓、蛋壳拼接、金属箔边缘和磨显色层共同构形，不固定平面剪影", "漆黑、朱红、金银、蛋壳白及现代综合色构成宽范围，不限黑红金", "抛光反射、磨显综合色深度和真实展场光共同作用，避免镜面塑料质感", "天然漆层、朱砂、金银箔、蛋壳、木板或布底、研磨与抛光痕迹", "题名和签名只在来源可靠时准确呈现；现代新增文字与作品表面分开"], en: ["large color zones, shallow layering, narrative groups, landscapes, or abstraction organized by the artist", "contours, eggshell joins, metal-leaf edges, and revealed lacquer strata building form beyond flat silhouettes", "black lacquer, vermilion, gold-silver, eggshell white, and modern color across a broad range rather than one black-red-gold scheme", "polished reflection, sanded chromatic depth, and real exhibition light without plastic mirror gloss", "natural lacquer layers, vermilion, metal leaf, eggshell, wood or cloth ground, sanding, and polishing traces", "show titles and signatures only from reliable sources; keep any modern added typography separate from the lacquer surface"] },
  "traditional-balinese-painting": { period: "卡马桑传统约17世纪至今，相关巴厘仪式绘画传统更广", year: 1800, summary: "该条更准确指巴厘卡马桑式绘画：以村落工坊为核心，在寺庙、宫廷和仪式布画中表现印度教史诗与地方叙事。密集分层、程式人物和天然综合色重要，但不能代表全部“巴厘传统绘画”，也不应脱离宗教题材随意拼造神灵。", influencedBy: "爪哇—巴厘宫廷传统、印度教史诗、寺庙仪式、哇扬图像和地方工坊传承", influenced: "巴厘其他绘画中心、20世纪旅游艺术和当代卡马桑复兴", related: ["wayang-aesthetic", "ubud-school-painting", "classical-javanese-art", "thai-temple-mural"], sources: BATCH_09_SOURCES.balinese, zh: ["横向叙事层、等级群组和连续满幅按仪式布、寺庙或宫廷位置组织", "程式侧面、手势、服饰和尺度等级源自卡马桑图像规范，不生成混合神像", "土黄、赭红、黑白和有限靛蓝等传统综合色，也允许有据可查的现代材料变化", "综合色分区和线密度建立层次，实际展示保留织物或墙面的环境光", "棉布、传统综合色、墨线、工坊笔触、装裱和真实使用磨损", "只有经核实的巴厘文字或题名才可出现；不得发明神名、咒语和仪式符号"], en: ["horizontal narrative registers, hierarchical groups, and continuous fields organized for ritual cloth, temple, or palace location", "codified profiles, gestures, dress, and scale derived from Kamasan conventions without hybrid invented deities", "earth yellow, ochre red, black-white, and restrained indigo in traditional work, with documented modern material changes", "depth through bounded color and line density while retaining real ambient light on cloth or wall", "cotton cloth, traditional color, ink contours, workshop brushwork, mounting, and genuine use wear", "include Balinese writing or titles only when verified; never invent deity names, spells, or ritual symbols"] },
  "ubud-school-painting": { period: "约1930年代形成并延续至今", year: 1950, summary: "乌布绘画在20世纪30年代巴厘艺术家、宫廷赞助与Pita Maha等网络中发展，并与Walter Spies、Rudolf Bonnet等外来艺术家互动。纸本、日常题材、综合色明暗和个体风格扩展了早期传统，但这种变化不能被写成欧洲人单向“现代化”巴厘艺术。", influencedBy: "巴厘寺庙宫廷绘画、当地艺术家网络、Pita Maha、旅游市场和跨文化交流", influenced: "巴厘现代绘画、国际收藏和乌布旅游视觉经济", related: ["traditional-balinese-painting", "wayang-aesthetic", "nanyang-style", "modern-asian-art"], sources: BATCH_09_SOURCES.ubud, zh: ["高密度日常场景、弯曲路径、多点观察或较集中主体按艺术家选择", "细密流线、人物植物节奏、个体比例和综合色阴影不再服从单一仪式程式", "墨褐、灰绿、土色和更宽现代综合色域随纸张与艺术家变化", "漫射日光、综合色明暗和线密度形成浅层体积，不套用统一热带滤镜", "纸或布、墨、水彩或综合色层染、细密手绘和真实老化", "文字只在作品有可核实内容时出现；不添加泛异国标签或伪巴厘文字"], en: ["dense everyday scenes, winding paths, multiple viewpoints, or concentrated subjects selected by artist", "fine flowing line, rhythmic figures and vegetation, individualized proportion, and tonal shading beyond one ritual formula", "ink brown, gray-green, earth color, and broader modern palettes varying by support and painter", "diffuse daylight, tonal color, and line density creating shallow volume without one tropical filter", "paper or cloth, ink, watercolor or layered pigment, minute handwork, and genuine aging", "include text only when verifiable in the work; add no generic exotic labels or pseudo-Balinese writing"] },
  "wayang-aesthetic": { period: "传统久远并延续至今，不同地区和类型年代各异", year: 1800, summary: "哇扬是爪哇、巴厘等地多种戏偶和表演传统的总称；该条视觉机制主要对应以水牛皮雕刻穿孔、杆件操控和灯光投影的wayang kulit。人物比例、综合色、角色类型和表演语境依地区而变，不能用一种拉长侧影代表全部哇扬。", influencedBy: "爪哇和巴厘表演、印度史诗与地方故事、宫廷仪式、皮革工艺和口传音乐", influenced: "印度尼西亚戏剧、视觉叙事、现代舞台动画和国家文化表达", related: ["classical-javanese-art", "traditional-balinese-painting", "shadow-puppetry", "chinese-shadow-puppetry"], sources: BATCH_09_SOURCES.wayang, zh: ["皮偶沿表演屏幕和树干式中心结构组织，真实表演包含操偶、乐队和观众双侧关系", "穿孔水牛皮、侧面角色、关节杆和比例编码按爪哇或巴厘具体传统选择", "皮革本色、黑、红、金和综合色用于实体皮偶，影幕版本以明暗剪影为主", "油灯或电灯背光产生真实剪影、穿孔光点和杆件影，不添加电影式轮廓光", "雕刻水牛皮、穿孔、综合色和金彩、角或木杆、屏幕织物与使用磨损", "只使用可核实的角色名和语言；不得拼造神名、爪哇文字或仪式符号"], en: ["puppets organized along the performance screen and central tree-like structure, with actual puppetry, musicians, and two-sided audience relations", "perforated buffalo hide, profile characters, joint rods, and coded proportions selected from a specific Javanese or Balinese tradition", "hide, black, red, gold, and color on physical puppets, with silhouette values dominating the screen view", "oil-lamp or electric backlight producing real silhouettes, perforated light points, and rod shadows without cinematic rim light", "carved buffalo hide, perforation, pigment and gilding, horn or wood rods, screen textile, and use wear", "use only verified character names and language; never invent deities, Javanese script, or ritual symbols"] },
  "classical-javanese-art": { period: "约8–15世纪为古典核心，后续传统延长", year: 1000, summary: "爪哇古典艺术主要联系中爪哇和东爪哇印度教—佛教王国的石造寺庙、浮雕、青铜与建筑装饰，阶段、宗教和地域差异显著。它不是哇扬皮偶的同义词，也不能以拉长侧面剪影、金彩皮革描述婆罗浮屠或普兰巴南。", influencedBy: "爪哇本地政治与工艺、印度教和佛教思想、南亚及东南亚海上交流", influenced: "东爪哇和巴厘艺术、寺庙建筑、浮雕叙事与现代印度尼西亚文化遗产", related: ["wayang-aesthetic", "traditional-balinese-painting", "khmer-art", "southeast-asian-buddhist-art"], sources: BATCH_09_SOURCES.java, zh: ["寺庙轴线、环行礼拜路径、连续浮雕带或独立青铜像按遗址与宗教用途组织", "石刻高低浮雕、圆雕、建筑构件和青铜体积保持具体时代比例", "火山石灰、青铜综合色、残存金色和材料风化为主，不设皮影综合色", "自然侧光揭示石刻深度，青铜使用克制反射，避免戏剧背光剪影", "火山石、安山岩凿痕、青铜铸造、建筑接缝、风化和残存表面", "铭文和古爪哇文字只在来源可核实时准确呈现；不得发明符号"], en: ["temple axes, circumambulatory paths, continuous relief bands, or freestanding bronzes organized by site and religious use", "high-low stone relief, sculpture in the round, architectural members, and bronze volume retaining period-specific proportions", "gray volcanic stone, bronze, surviving gold, and material weathering rather than puppet color", "natural sidelight revealing carving and restrained reflection on bronze without theatrical backlit silhouettes", "volcanic stone, andesite chisel marks, cast bronze, architectural joints, weathering, and surviving surface", "show inscriptions and Old Javanese only when verifiable and exact; never invent signs"] },
  "bagan-mural-painting": { period: "约11–13世纪为核心，后世有增绘与修复", year: 1200, summary: "蒲甘壁画主要存于缅甸蒲甘王朝佛教寺塔内部，以佛传、本生故事、供养人、宇宙图和巴利—孟文等题记构成复杂图像系统。不同寺院和时期的综合色、布局、重绘与保存状态差异大，不能用通用泰老寺院壁画字段替代。", influencedBy: "上座部与大乘佛教图像、孟和缅甸传统、南亚及斯里兰卡交流、蒲甘寺塔建筑", influenced: "缅甸后世寺院绘画、佛教叙事和蒲甘文化遗产保护", related: ["thai-temple-mural", "lao-temple-painting", "kandyan-temple-painting", "southeast-asian-buddhist-art"], sources: BATCH_09_SOURCES.bagan, zh: ["按寺塔墙面、拱顶和礼拜路径设置佛传、本生、供养人或小格佛像，不统一为横向边框", "细线人物、建筑、重复佛像和装饰几何依寺院阶段变化", "赭红、黄、黑、白、绿及残存蓝色依据颜料调查，不把金色设为必要", "室内克制侧光用于阅读现存壁画，原始综合色与当代照明、重绘状态分开", "灰泥、矿物与有机综合色、线刻底稿、烟尘、盐害、脱落和历史重绘", "巴利、孟文、缅文题记仅在准确转写可用时呈现；不得生成伪经文"], en: ["Buddha-life, jataka, donor, cosmological, or repeated-image programs placed by temple wall, vault, and ritual path rather than one bordered register", "fine figures, architecture, repeated Buddhas, and geometric ornament varying by monument and phase", "ochre red, yellow, black, white, green, and surviving blue based on pigment evidence without mandatory gold", "restrained interior sidelight for current murals, distinguishing original color from modern illumination and repainting", "plaster, mineral and organic color, incised underdrawing, soot, salts, losses, and historical repainting", "show Pali, Mon, or Burmese inscriptions only with accurate transcription; never generate pseudo-scripture"] },
  "thai-temple-mural": { period: "现存重要体系主要属阿瑜陀耶晚期至拉达那哥欣时期，约17–19世纪", year: 1800, summary: "泰国寺院壁画通常围绕佛传、本生、宇宙观和世俗细节布置于佛殿墙面，阿瑜陀耶与曼谷时期的空间、人物、金饰和西方透视吸收不同。把约11至19世纪写成统一风格会掩盖王国、区域与修复差异。", influencedBy: "泰国佛教、宫廷与寺院赞助、本生和宇宙图像、周边地区及后期西方图像交流", influenced: "泰国宗教绘画、插图、建筑装饰和现代文化遗产", related: ["lao-temple-painting", "bagan-mural-painting", "kandyan-temple-painting", "thai-folk-pop"], sources: BATCH_09_SOURCES.thaiMural, zh: ["壁面上方天界、中段叙事、门窗间场景或连续城市景观按寺院方案组织", "细线人物、尖顶建筑、云焰分隔和后期透视元素须按时期选择", "红、赭、绿、黑白与金色常见，也有综合色更克制或后期扩展的版本", "室内墙面光和金饰反射揭示实际综合色，不将金色小节点夸张成发光场", "灰泥、矿物或有机综合色、金箔、黑线、烟尘、裂缝和经证实的修复", "泰文榜题和经文只有准确可核实时使用；不得生成伪佛经和错误字符"], en: ["celestial upper zones, middle narratives, scenes between openings, or continuous urban landscapes organized by a particular temple program", "fine figures, tiered roofs, flame-cloud separators, and later perspective elements selected by date", "red, ochre, green, black-white, and gold as common alongside restrained or later expanded palettes", "interior wall light and real gold reflection revealing current color without turning small metallic details into a glowing field", "plaster, mineral or organic color, gold leaf, black line, soot, cracks, and documented conservation", "use Thai labels and scripture only when accurate and verifiable; never generate false Buddhist text or malformed characters"] },
  "lao-temple-painting": { period: "现存传统主要见于约18–20世纪，地区和寺院差异显著", year: 1850, summary: "老挝寺院绘画分布于琅勃拉邦等地佛寺，表现佛传、本生、地方史诗和日常生活，并与泰、兰纳、缅甸和高棉图像交流。现有笼统的11–19世纪范围和泰国壁画模板缺乏依据，应按具体寺院年代、修复和地方风格说明。", influencedBy: "老挝上座部佛教、兰沧王国文化、地方史诗和泰兰纳等区域交流", influenced: "老挝宗教图像、寺院保护和现代国家文化表达", related: ["thai-temple-mural", "bagan-mural-painting", "kandyan-temple-painting", "southeast-asian-buddhist-art"], sources: BATCH_09_SOURCES.laoMural, zh: ["佛殿墙面、门窗间隔和连续故事带按具体寺院组织，可结合地方生活场景", "细线人物、建筑、树木和装饰分隔保持老挝地方服饰与形态，不复制泰国模板", "赭红、黄、绿、黑白和局部金色依据原作，第四色域随寺院与修复改变", "柔和室内光显示墙面和综合色层，明确现状、重绘与原始部分", "灰泥、手绘综合色、金饰、墨线、烟尘、剥落和历史修补", "老挝文与经文只在可准确转写时呈现；不得生成伪文字或混用泰文"], en: ["sanctuary walls, spaces between openings, and continuous story bands organized by a specific temple, sometimes incorporating local life", "fine figures, buildings, trees, and separators retaining Lao dress and forms rather than copying a Thai template", "ochre red, yellow, green, black-white, and local gold based on the work, with palettes varying by temple and restoration", "soft interior light revealing wall and pigment while distinguishing original passages, repainting, and current condition", "plaster, hand-applied color, gilding, ink line, soot, losses, and historical repairs", "show Lao and scripture only with accurate transcription; never invent writing or substitute Thai script"] },
  "kandyan-temple-painting": { period: "约17世纪末–19世纪，康提王国及后续", year: 1800, summary: "康提时期寺院绘画是斯里兰卡上座部佛教视觉传统的重要阶段，常以横向连续画格表现佛传和本生，并使用平面综合色、侧面人物和花饰边带。它与缅甸、泰国、老挝壁画各有独立语言，不能共享一套通用寺院模板。", influencedBy: "斯里兰卡佛教和早期壁画传统、康提王室寺院赞助、南亚及区域交流", influenced: "斯里兰卡宗教绘画、民间图像和现代文化遗产保护", related: ["bagan-mural-painting", "thai-temple-mural", "newar-paubha-painting", "south-asian-buddhist-art"], sources: BATCH_09_SOURCES.kandyan, zh: ["长条连续画格、稳定基线和装饰边框依墙面礼拜路径展开", "清楚侧面人物、重复姿态、树木建筑符号和有限尺度等级", "红、黄、白、黑和绿等平面综合色为主，按遗址保留综合色差异", "综合色区和线条建立叙事层次，文物记录光不添加金色辉光", "灰泥墙、矿物或植物综合色、黑色轮廓、花饰边带、裂缝和修复痕迹", "僧伽罗文题记和经文必须准确且有来源；不得生成装饰性伪文字"], en: ["long continuous registers, stable baselines, and ornamental borders unfolding along the ritual wall path", "clear profile figures, repeated gestures, emblematic trees and buildings, and limited hierarchical scale", "flat red, yellow, white, black, and green based on the monument with site-specific variation", "narrative depth through bounded color and line, with conservation light adding no golden glow", "plastered walls, mineral or vegetable color, black contours, floral borders, cracks, and conservation traces", "Sinhala inscriptions and scripture must be accurate and sourced; never generate ornamental pseudo-writing"] },
  "newar-paubha-painting": { period: "约13世纪至今，前史更早", year: 1500, summary: "paubha 是尼泊尔谷地纽瓦尔艺术家制作的宗教布画传统，用于佛教和印度教仪式、供养与冥想，并有严格图像、比例和开光语境。它与藏传唐卡关系密切但不等同；现代应用不能随意替换主尊、手印、文字或把神圣图像当装饰边框。", influencedBy: "纽瓦尔佛教与印度教、尼泊尔谷地工坊、南亚图像和西藏喜马拉雅交流", influenced: "西藏与喜马拉雅宗教绘画、尼泊尔当代传统艺术和博物馆收藏", related: ["thangka", "kandyan-temple-painting", "mughal-miniature", "newar-art"], sources: BATCH_09_SOURCES.paubha, zh: ["严格中心主尊、同心眷属、供养人和边界层级必须来自具体仪轨图像，不自由改组", "连续精线、规定比例、手印、持物和珠宝细节须有可靠图像依据", "朱红、群青、绿、金和深底按传统工坊与神格选择，不设通用珠宝综合色", "平面综合色层和真实金色反射保持仪式图像可读，不制造奇幻神光", "棉布底、胶质矿物综合色、金、细密勾线、装裱和经记录的使用老化", "咒语、种子字、题记和神名只有准确且获授权时使用；不得伪造神圣文字"], en: ["a central deity, concentric retinue, donors, and boundary hierarchy derived from a specific ritual iconography rather than freely rearranged", "continuous fine line, prescribed proportion, mudras, attributes, and jewelry grounded in reliable iconographic evidence", "vermilion, ultramarine, green, gold, and dark grounds selected by workshop and deity without one jewel palette", "flat color layers and real gold reflection preserving ritual legibility without fantasy radiance", "prepared cotton, glue-bound mineral pigment, gold, fine outlines, mounting, and documented ritual wear", "mantras, seed syllables, inscriptions, and deity names require exactness and appropriate authorization; never fabricate sacred writing"] },
  "nanyang-style": { period: "约1930–1960年代，后续影响延长", year: 1955, summary: "南洋画派是对新加坡和马来亚若干华人艺术家现代实践的后设称谓，成员来自不同教育与媒介背景，以东南亚现场、移民经验、水墨、巴黎现代主义和地方文化相遇为重要议题。它不是综合色赭黄加“热带光”的统一风格，且“南洋”一词本身具有历史地域视角。", influencedBy: "中国水墨与上海美术教育、巴黎现代主义、移民网络、英属马来亚和东南亚现场", influenced: "新加坡马来西亚现代艺术、区域艺术史和后殖民身份讨论", related: ["ubud-school-painting", "vietnamese-lacquer-painting", "philippine-modernism", "ink-wash"], sources: BATCH_09_SOURCES.nanyang, zh: ["现场速写、人物群像、村落河景、静物或现代主义分区按艺术家与媒介选择", "书写线、简化综合色块、立体主义分解或观察性形体不混成一种南洋笔法", "综合色从水墨淡彩到高纯度油彩，赭黄、热带绿蓝只是部分作品选择", "赤道日光、室内观察光或画面综合色关系按作品处理，不套用暖湿滤镜", "油彩、纸本水墨、水彩、粉彩、画布或纸纹和可见个体笔触", "题名和多语言文字须准确并尊重历史用语；不得用伪汉字或泛异国字体"], en: ["on-site sketches, figure groups, village and river scenes, still life, or modernist zoning selected by artist and medium", "calligraphic line, reduced color masses, cubist fragmentation, or observed form without merging them as one Nanyang hand", "color ranging from light ink wash to saturated oil, with ochre and tropical green-blue only partial choices", "equatorial daylight, observed interior light, or pictorial color relations selected by work without a warm-humid filter", "oil, ink on paper, watercolor, pastel, canvas or paper grain, and individual brushwork", "titles and multilingual text must be exact and historically sensitive; never use pseudo-characters or generic exotic type"] },
  "philippine-modernism": { period: "约1920年代末–1980年代，内部阶段多样", year: 1960, summary: "菲律宾现代主义涵盖殖民末期、独立和马科斯时期多种具象、社会现实、抽象和材料实践，年代早于原条目的1950年代。Victorio Edades等早期现代派、战后抽象与地方现代主义立场不同，不能用热带高纯度综合色、民俗节奏和粗糙材料统一概括。", influencedBy: "西班牙和美国殖民美术教育、菲律宾本地视觉文化、国际现代主义、独立与社会政治经验", influenced: "菲律宾当代艺术、社会现实主义、区域现代主义和国家收藏叙述", related: ["nanyang-style", "vietnamese-lacquer-painting", "social-realism", "abstract-expressionism"], sources: BATCH_09_SOURCES.philippineModern, zh: ["纪念群像、城市劳动、现代主义平面、抽象场或装置结构按艺术家阶段选择", "厚重具象、几何抽象、表现笔触和地方材料均存在，不设统一简化轮廓", "土色、综合色高纯度、黑白或综合色场均可，热带综合色不是国别本质", "观察光、表现性明暗或抽象综合色关系按作品而变，不统一强侧光", "油彩、木材、纸、纤维、金属、拼贴和从精细到粗粝的制作表面", "文字和政治口号仅在来源准确时使用；不仿造艺术家署名或国家标志"], en: ["monumental groups, urban labor, modernist planes, abstract fields, or installation structures selected by artist and phase", "weighty figuration, geometric abstraction, expressive marks, and local materials without one simplified-contour formula", "earth color, high saturation, black-white, or chromatic fields without treating tropical color as a national essence", "observed light, expressive value, or abstract color relations varying by work rather than one strong sidelight", "oil, timber, paper, fiber, metal, collage, and surfaces ranging from precise to rough", "use text and political slogans only from accurate sources; never fabricate artists' signatures or state symbols"] },
  "jeepney-art": { period: "约1945年后形成，持续演变至今", year: 1980, summary: "吉普尼由战后军用吉普改装的公共交通发展而来，其视觉来自车身制造、路线经营、手绘标牌、镀铬、贴花、宗教和流行图像等多方实践。装饰程度依地区、法规、运营和年代不同，不能把所有车辆写成满版高饱和民俗拼贴。", influencedBy: "战后美国军用车辆、菲律宾车身工艺、公共交通、手绘招牌、宗教与流行文化", influenced: "菲律宾城市视觉、交通设计、字体文化和国家身份象征", related: ["philippine-modernism", "hand-painted-signage", "lowrider-art", "pop-art"], sources: BATCH_09_SOURCES.jeepney, zh: ["车头、侧板、车尾、路线牌和乘客开口按真实车体功能分区，装饰密度可高可低", "手绘字、镀铬构件、几何边带、贴花和图像引用服从车身接缝与法规", "高饱和红黄蓝绿、铬银、金属本色或运营标准色均可，不固定彩虹渐变", "户外日光和夜间街灯产生真实镀铬反射、漆面高光和车体阴影", "搪瓷或汽车漆、铬钢、不锈钢、贴花、手绘标牌、铆钉、磨损和维修补丁", "路线、目的地、车名和运营文字必须准确可读；不得伪造车牌、公司或宗教文字"], en: ["front, side panels, rear, route board, and passenger openings zoned by actual vehicle function with decoration from sparse to dense", "hand lettering, chrome components, geometric bands, decals, and quoted images fitted to body seams and regulation", "saturated red-yellow-blue-green, chrome, inherent metal, or operator standard colors without mandatory rainbow gradients", "outdoor daylight and night streets producing real chrome reflection, paint highlights, and vehicle shadows", "enamel or automotive paint, chrome or stainless steel, decals, sign painting, rivets, wear, and repair patches", "routes, destinations, vehicle names, and operator text must be exact and legible; never fabricate plates, companies, or religious wording"] }
};

