const BATCH_10_REVIEWS = {
  "gandhara-art": { period: "约前1世纪–7世纪，1–5世纪为重要发展期", year: 200, summary: "犍陀罗艺术形成于今巴基斯坦北部和阿富汗东部等地的佛教文化网络，吸收希腊化、罗马、伊朗和南亚多重资源。灰色片岩佛像和深衣褶最著名，但灰泥、陶塑、叙事浮雕与后期阶段同样重要，不能简单称为“希腊罗马造型加佛教题材”。", influencedBy: "南亚佛教、希腊化与罗马视觉传统、贵霜政治、伊朗和中亚交流", influenced: "中亚、中国和东亚佛教图像，以及南亚西北部雕塑传统", related: ["mathura-art", "gupta-art", "pala-art", "dunhuang"], sources: BATCH_10_SOURCES.gandhara, zh: ["正面像、浅龛、连续佛传浮雕或建筑构件按原物用途组织", "自然主义体积、深褶、波浪发束和地域化图像特征须按时期材料选择", "片岩灰、灰泥白、陶土和残存综合色来自原物，不统一为灰石单色", "擦边或柔侧光揭示真实雕刻和灰泥体积，不制造电影式神圣光", "灰色片岩、灰泥、陶塑、石刻凿痕、残色和风化边缘", "铭文只在佉卢文、婆罗米文等可准确转写时呈现；不生成伪古文字"], en: ["frontal icons, shallow niches, continuous life-of-the-Buddha reliefs, or architectural components organized by original function", "naturalistic volume, deep drapery, waved hair, and regional iconographic features selected by date and material", "schist gray, stucco white, terracotta, and surviving pigment derived from the object rather than one gray monochrome", "grazing or soft sidelight revealing real carving and stucco volume without cinematic sacred light", "gray schist, stucco, terracotta, chisel marks, pigment traces, and weathered edges", "show Kharosthi, Brahmi, or other inscriptions only with accurate transcription; never fabricate ancient writing"] },
  "mathura-art": { period: "约前2世纪–12世纪，贵霜和笈多时期尤重要", year: 200, summary: "秣菟罗艺术是印度北部秣菟罗长期雕塑中心的传统，贵霜至笈多时期以红斑砂岩制作佛教、耆那教和婆罗门教图像，并延续后世。正面体量与饱满轮廓重要，但宗教、年代和材料变化不能被1–16世纪的通用神像模板抹平。", influencedBy: "印度北部早期石雕、夜叉图像、贵霜赞助和佛教、耆那教、婆罗门教传统", influenced: "笈多雕塑、北印度宗教图像和亚洲佛教造像", related: ["gandhara-art", "gupta-art", "pala-art", "chola-art"], sources: BATCH_10_SOURCES.mathura, zh: ["正面立像、坐像、纪念柱或叙事浮雕按宗教与原物结构组织", "饱满体量、清楚手印、贴体衣纹或裸露躯干须依据具体时代和神格", "红斑砂岩、石灰综合色、残存综合色和其他地方石材，不混入南印度花岗岩通例", "柔侧光和擦边光显示砂岩体积、浅浮雕与表面磨损", "红斑砂岩、凿痕、抛光、残色、断损和后期风化", "神名、手印和婆罗米等铭文必须有图像与文字依据；不得随意替换"], en: ["frontal standing or seated icons, pillars, and narrative reliefs organized by religion and original object", "full volume, legible mudras, clinging drapery or exposed torso grounded in a specific date and deity", "mottled red sandstone, lime traces, surviving color, and other local stones without default South Indian granite", "soft sidelight and grazing light revealing sandstone volume, shallow relief, and wear", "mottled red sandstone, chisel marks, polish, pigment traces, damage, and weathering", "deity names, mudras, and Brahmi inscriptions require iconographic and textual evidence; never substitute them freely"] },
  "gupta-art": { period: "约4–6世纪，相关后笈多传统延续", year: 500, summary: "笈多艺术主要指4至6世纪笈多帝国及相关区域的宗教建筑、雕塑、钱币与绘画，以萨尔纳特和秣菟罗等不同中心形成多种佛教、婆罗门教和耆那教图像。柔和体积和克制表情常被视为典型，但不存在跨1–16世纪不变的笈多样式。", influencedBy: "贵霜与秣菟罗传统、南亚宗教图像、帝国赞助和区域工坊", influenced: "后笈多和帕拉艺术、东南亚及东亚佛教造像、印度寺庙雕塑", related: ["mathura-art", "gandhara-art", "pala-art", "vijayanagara-art"], sources: BATCH_10_SOURCES.gupta, zh: ["独立神像、寺庙龛位、叙事浮雕或壁画按宗教建筑关系组织", "平滑连续体积、克制姿态和薄衣处理是部分中心特征，须区分萨尔纳特与秣菟罗", "浅砂岩、红砂岩、陶土、青铜和残色依据产地材料选择", "柔侧光揭示连续体积与浅衣纹，不把宁静表情转译为发光滤镜", "砂岩、陶塑、金属铸造、石刻抛光、凿痕和残存表面", "宗教图像和铭文必须对应原物与神格；不生成伪梵文、伪婆罗米文"], en: ["freestanding icons, temple niches, narrative reliefs, or murals organized by religious architecture", "smooth continuous volume, restrained posture, and thin drapery as features of some centers, distinguishing Sarnath from Mathura", "pale or red sandstone, terracotta, bronze, and pigment traces selected by place of production", "soft sidelight revealing continuous volume and shallow drapery without turning serenity into a glow filter", "sandstone, terracotta, metal casting, polish, chisel marks, and surviving surface", "religious iconography and inscriptions must match the object and deity; never generate pseudo-Sanskrit or pseudo-Brahmi"] },
  "pala-art": { period: "约8–12世纪，印度东部和孟加拉地区", year: 1000, summary: "帕拉艺术在比哈尔和孟加拉等地佛教大寺院与王朝赞助中发展，涵盖石雕、铜像和贝叶写本，并与尼泊尔、西藏及东南亚交流。狭长贝叶构图只适用于写本，不能代表全部帕拉艺术；宗教图像也须遵循具体仪轨。", influencedBy: "后笈多艺术、东印度佛教寺院、密教图像和地方石铜工艺", influenced: "尼泊尔纽瓦尔、西藏和喜马拉雅佛教艺术，以及东印度后续图像", related: ["gupta-art", "newar-paubha-painting", "thangka", "gandhara-art"], sources: BATCH_10_SOURCES.pala, zh: ["贝叶写本采用狭长中心图像与文字区，石铜造像则按龛位和独立礼拜结构组织", "细密图像、复杂手印持物、珠宝或石雕体积必须依据具体神格与媒介", "朱红、深蓝、绿、黑、金及石铜本色按写本或造像分别处理", "写本保持平面阅读光，石雕与铜像用真实侧光揭示体积", "贝叶、矿物综合色、墨、金、黑色玄武岩、失蜡铜像和风化", "经文、种子字、神名和铭文仅在准确可核实时使用；不得伪造密教文字"], en: ["narrow central images and text zones for palm-leaf manuscripts, versus niches or freestanding devotional structures for stone and bronze icons", "fine iconography, complex mudras and attributes, jewelry, or sculptural volume grounded in a specific deity and medium", "vermilion, deep blue, green, black, gold, and inherent stone or bronze treated according to manuscript or sculpture", "flat reading light for manuscripts and real sidelight revealing stone or bronze volume", "palm leaf, mineral color, ink, gold, black basalt, lost-wax bronze, and weathering", "scripture, seed syllables, deity names, and inscriptions require exact verification; never fabricate tantric writing"] },
  "chola-art": { period: "约9–13世纪，朱罗王朝核心期", year: 1100, summary: "朱罗艺术以泰米尔地区大型湿婆神庙、花岗岩建筑雕刻和失蜡青铜闻名，尤其包括用于节庆游行的可移动神像。青铜舞王是代表性图像但不覆盖全部朱罗艺术；石造、壁画、宗教功能和后世复制必须区分。", influencedBy: "帕拉瓦和泰米尔寺庙传统、湿婆与毗湿奴信仰、王室和寺庙经济", influenced: "南印度寺庙建筑、青铜铸造、东南亚印度教艺术和现代印度艺术史", related: ["vijayanagara-art", "gupta-art", "classical-javanese-art", "khmer-angkor-art"], sources: BATCH_10_SOURCES.chola, zh: ["寺庙轴线、塔门与龛位、独立青铜或仪式游行关系按原物功能组织", "花岗岩雕刻与失蜡青铜采用不同体量、姿态、手印和饰物结构", "花岗岩灰、青铜棕金、残存综合色和仪式装饰须区分永久材料与临时装扮", "自然侧光显示建筑石刻，青铜以克制反射揭示圆润体积", "花岗岩、失蜡青铜、铸造细节、石刻凿痕、壁画残层和仪式磨损", "神名、泰米尔文铭文和手印必须准确；不得将舞王姿势套用于无关主体"], en: ["temple axes, towers and niches, freestanding bronzes, or processional relations organized by original ritual function", "granite carving and lost-wax bronze using distinct volume, posture, mudras, and ornaments", "gray granite, brown-gold bronze, pigment traces, and ritual adornment distinguished between permanent material and temporary dressing", "natural sidelight for architectural carving and restrained reflection revealing rounded bronze volume", "granite, lost-wax bronze, casting detail, chisel marks, mural traces, and ritual wear", "deity names, Tamil inscriptions, and mudras must be exact; never impose the Nataraja pose on an unrelated subject"] },
  "vijayanagara-art": { period: "约14–17世纪，帝国核心期1336–1565年", year: 1500, summary: "维查耶那伽罗艺术以亨比等都城和南印度寺庙网络的建筑、雕塑、壁画、青铜和宫廷设施为核心，融合早期南印度传统并发展巨型柱厅、塔门和世俗建筑。它不是从1世纪延续至16世纪的通用神像风格。", influencedBy: "朱罗、曷萨拉、卡卡提亚和潘迪亚建筑传统、南印度宗教与宫廷文化", influenced: "纳亚克时期寺庙扩建、南印度建筑雕塑和现代亨比遗产叙述", related: ["chola-art", "classical-javanese-art", "khmer-angkor-art", "south-indian-temple-art"], sources: BATCH_10_SOURCES.vijayanagara, zh: ["城市轴线、院落、柱厅、塔门、神庙和水利设施按真实建筑功能形成复合空间", "花岗岩柱雕、神话叙事、动物复合体和建筑构件必须对应具体遗址", "花岗岩、灰泥残色、壁画综合色和金属本色按媒介分开", "强烈自然日光与深檐阴影说明建筑，壁画使用克制文物记录光", "花岗岩砌筑、石刻、灰泥、壁画、青铜、接缝、风化和损毁", "卡纳达文、泰卢固文、泰米尔文和梵文铭文仅在准确释读时使用"], en: ["urban axes, courts, pillared halls, gateways, temples, and waterworks forming complex space according to actual function", "granite pillars, mythic narratives, composite animals, and architectural members tied to a specific monument", "granite, stucco traces, mural color, and metal treated separately by medium", "strong natural sun and deep-eave shadow explaining architecture, with restrained conservation light for murals", "granite masonry, carving, stucco, mural, bronze, joints, weathering, and damage", "use Kannada, Telugu, Tamil, and Sanskrit inscriptions only when accurately read and transcribed"] },
  "persian-miniature": { period: "约13–17世纪为经典发展期，传统延续至后世", year: 1500, summary: "波斯细密画在伊儿汗、帖木儿、萨法维等不同宫廷与城市工坊中发展，常作为诗歌、史书和相册的一部分，并涉及画家、书法家、装帧者等协作。高视点、密集细节和宝石色很重要，但赫拉特、设拉子、大不里士等中心并不共享一个综合色和空间公式。", influencedBy: "伊朗写本传统、伊斯兰书法装帧、蒙古和中国图像交流、宫廷诗歌文化", influenced: "莫卧儿、德干、奥斯曼和中亚细密画，以及欧洲和现代书籍艺术", related: ["mughal-miniature", "deccani-painting", "ottoman-miniature", "nastaliq-calligraphy-aesthetic"], sources: BATCH_10_SOURCES.persian, zh: ["高视点、垂直叠置、建筑剖开、庭园或较疏人物页按时期工坊和文本选择", "精细轮廓、平面纹样、人物比例与岩石云树程式依城市和画家变化", "群青、朱红、粉、绿、金和纸色形成广泛综合色，不固定“珠宝色”强度", "综合色层和重叠建立空间，金色仅产生真实细微反光，不模拟自然投影", "抛光纸、不透明水彩、金银、精细墨线、边饰、书法和装帧接缝", "只准确呈现原诗文、书法和题记；不得生成伪波斯语、伪纳斯塔利克或名家署名"], en: ["high viewpoints, vertical stacking, opened architecture, gardens, or sparse figure pages selected by period, workshop, and text", "fine contours, flat pattern, figure proportions, and codified rocks, clouds, and trees varying by center and painter", "ultramarine, vermilion, pink, green, gold, and paper across a broad range without one jewel-tone intensity", "space through color layers and overlap, with gold producing only real small reflections rather than naturalistic shadow", "burnished paper, opaque watercolor, gold-silver, fine ink, borders, calligraphy, and binding seams", "render original poetry, calligraphy, and inscriptions accurately; never generate pseudo-Persian, false Nastaliq, or a master's signature"] },
  "mughal-miniature": { period: "约1550年代–19世纪，16–17世纪宫廷工坊尤重要", year: 1600, summary: "莫卧儿绘画由胡马雍和阿克巴时期宫廷工坊发展，在波斯写本基础上吸收印度画师传统、欧洲版画和自然观察，涵盖巨型史诗写本、肖像、动物植物、历史和相册页。所谓“波斯线描、印度综合色、欧洲写实”的公式过度简化了皇帝、画家和阶段差异。", influencedBy: "波斯和中亚写本、印度画师传统、莫卧儿宫廷赞助、欧洲版画与自然观察", influenced: "德干、拉贾斯坦、帕哈里和公司画，以及南亚肖像与自然史图像", related: ["persian-miniature", "deccani-painting", "rajasthani-miniature", "company-painting"], sources: BATCH_10_SOURCES.mughal, zh: ["多人物叙事、单幅肖像、动物植物研究、相册边饰或历史场景按皇帝和工坊选择", "精细轮廓、个体肖像、自然观察和综合色渐层与程式化边饰并存", "矿物综合色、透明洗染、金、纸色和欧洲来源明暗按阶段作品变化", "综合色体积、局部投影或平面叙事光均可，不以统一自然主义定义", "抛光纸、不透明与透明水彩、金、精细毛笔、拼贴边饰和题记", "波斯文、阿拉伯文、天城文和署名只在准确可核实时呈现；不伪造皇帝印和画家题名"], en: ["multifigure narratives, single portraits, flora-fauna studies, album borders, or histories selected by emperor and workshop", "fine contour, individualized portraiture, natural observation, tonal gradation, and codified border work in varying combinations", "mineral color, transparent wash, gold, paper, and European-derived modeling varying by phase and work", "tonal volume, local shadow, or flat narrative illumination without making naturalism universal", "burnished paper, opaque and transparent watercolor, gold, fine brushes, collaged borders, and inscriptions", "show Persian, Arabic, Devanagari, signatures, and seals only when accurately verified; never fabricate imperial marks or artist attributions"] },
  "deccani-painting": { period: "约16–18世纪，德干苏丹国和后续宫廷", year: 1650, summary: "德干绘画形成于艾哈迈德讷格尔、比贾布尔、戈尔康达等宫廷，后续亦受海得拉巴环境影响。拉长人物、浓郁综合色、奇异尺度和幻想空间是部分特征，但各苏丹国、时期及与莫卧儿交流存在差别，不能一律写成夜色珠宝光。", influencedBy: "波斯和南亚绘画、德干苏丹国宫廷、区域纺织金工和莫卧儿交流", influenced: "海得拉巴绘画、拉贾斯坦和南印度宫廷艺术，以及现代德干艺术史", related: ["persian-miniature", "mughal-miniature", "rajasthani-miniature", "islamic-geometry"], sources: BATCH_10_SOURCES.deccani, zh: ["高视点宫廷、偏心肖像、建筑庭园或大面积空地按具体苏丹国选择", "拉长比例、精细轮廓、综合色体积和不寻常尺度不是每个中心的共同规则", "深群青、孔雀绿、紫红、金、粉和综合色背景依工坊变化，不强制夜色", "综合色层、金属细节和局部柔化形成空间，不添加奇幻光晕", "纸本不透明水彩、金、精线、抛光表面、边框和题记", "只在准确时使用波斯文、达克尼语或阿拉伯文题签；不得制造伪书法"], en: ["high-view courts, off-center portraits, architectural gardens, or broad open grounds selected by a specific sultanate", "elongation, fine contour, tonal volume, and uncanny scale used where documented rather than as universal Deccani rules", "deep ultramarine, peacock green, magenta, gold, pink, and varied grounds by workshop without mandatory night color", "space through color layers, metallic detail, and local softening without fantasy halos", "opaque watercolor on paper, gold, fine line, burnishing, borders, and inscriptions", "use Persian, Dakhni, or Arabic labels only when exact; never generate pseudo-calligraphy"] },
  "rajasthani-miniature": { period: "约16–19世纪，多个拉其普特宫廷传统", year: 1750, summary: "拉贾斯坦绘画是梅瓦尔、马尔瓦、布恩迪—科塔、斋浦尔、比卡内尔等多个宫廷传统的总称，题材与综合色、空间和莫卧儿影响程度差异很大。强烈平涂和侧面人物常见，但不能统一为红黄蓝绿的单焦点矩形画。", influencedBy: "西印度写本、地方宫廷和宗教诗歌、莫卧儿绘画及区域工坊交流", influenced: "帕哈里绘画、地方宫廷图像和现代印度细密画复兴", related: ["mughal-miniature", "deccani-painting", "pahari-painting", "pattachitra"], sources: BATCH_10_SOURCES.rajasthani, zh: ["宫廷、狩猎、宗教诗歌、季节图或风景按具体中心使用平面分区、连续叙事或纵深", "硬边侧面、精细肖像、动物和建筑形式随梅瓦尔、科塔、比卡内尔等中心变化", "朱红、黄、蓝绿、黑、金和淡色综合色按宫廷工坊选择，不设综合色定式", "平面综合色、重叠、局部渐层和环境表现均可，不能一律无投影", "纸本不透明水彩、矿物综合色、金、精线、边框和抛光", "边栏题签、天城文或波斯文只在原文准确时使用，不混写语言与伪造署名"], en: ["court, hunt, devotional poetry, seasonal imagery, or landscape using flat compartments, continuous narration, or depth according to a specific center", "hard profile, fine portraiture, animals, and architecture varying among Mewar, Kota, Bikaner, and other courts", "vermilion, yellow, blue-green, black, gold, and pale color selected by workshop without one palette", "flat color, overlap, local gradation, and environmental treatment all possible rather than universal shadowlessness", "opaque watercolor on paper, mineral color, gold, fine line, borders, and burnishing", "use marginal labels, Devanagari, or Persian only with exact text; never mix scripts carelessly or fabricate signatures"] },
  "pahari-painting": { period: "约17–19世纪，西喜马拉雅多个山地宫廷", year: 1780, summary: "帕哈里绘画涵盖巴索利、古勒尔、康格拉、昌巴等山地宫廷，综合色和造型从巴索利的强烈几何与浓色到古勒尔—康格拉的抒情自然主义差异显著。把整个传统写成柔绿薄雾和细腻恋爱情境，会把康格拉路线泛化。", influencedBy: "西喜马拉雅地方宫廷、宗教诗歌、拉贾斯坦和莫卧儿画师交流", influenced: "北印度宗教图像、现代细密画收藏和喜马拉雅区域艺术史", related: ["rajasthani-miniature", "mughal-miniature", "newar-paubha-painting", "deccani-painting"], sources: BATCH_10_SOURCES.pahari, zh: ["巴索利式强中心、康格拉式层叠风景或宫廷叙事按具体山地中心选择", "从硬朗几何脸型到柔和人物和细密叶簇均存在，不设统一圆润线", "浓黄红、深绿和金可与嫩绿、天蓝、淡粉等不同中心综合色并存", "平面强综合色或柔和自然光和薄雾层次按学校与作品选择", "纸本不透明水彩、透明层染、矿物综合色、金、精线和抛光", "天城文、塔克里文或其他题签必须准确并对应原作；不生成伪诗文"], en: ["strong Basohli centering, layered Kangra landscapes, or court narratives selected by a specific hill center", "forms ranging from forceful geometric faces to soft figures and minute foliage without one rounded-line rule", "strong yellow-red, deep green, and gold alongside fresh green, sky blue, and pale pink in different centers", "flat intense color or soft natural light and atmosphere selected by school and work", "opaque watercolor on paper, transparent glazing, mineral pigment, gold, fine line, and burnishing", "Devanagari, Takri, and other labels must be exact and tied to the source; never fabricate poetry"] },
  "company-painting": { period: "约1760年代–1850年代，地区延续不一", year: 1820, summary: "所谓“公司画”是殖民时期欧洲雇主和东印度公司相关市场委托印度艺术家制作的一组跨地区作品，名称具有殖民史视角。它涵盖人物、建筑、植物动物、职业和风俗记录，制作中心与艺术家策略多样，不能只写成白底单标本自然史图。", influencedBy: "莫卧儿及地方宫廷画师、欧洲殖民委托、自然史分类、地图测绘和水彩纸张", influenced: "殖民档案图像、印度现代绘画、博物馆分类和后殖民视觉研究", related: ["mughal-miniature", "kalighat-painting", "bengal-school", "orientalist-painting"], sources: BATCH_10_SOURCES.company, zh: ["单体标本、成组人物、建筑全景、职业图谱或相册页按地区委托选择", "精确观察、地方细密线、透明水彩和欧洲阴影机制以不同程度结合", "透明水彩、纸白、植物综合色、服饰色和土色按主题与画师变化", "自然史可用轻投影，建筑人物可有更复杂环境光，不统一档案柔光", "欧洲或印度纸、水彩和不透明综合色、云母、精笔、题记和装帧", "标签必须准确并说明殖民命名语境；不伪造物种、族群、职业或画家署名"], en: ["single specimens, figure groups, architectural panoramas, occupational series, or album leaves selected by region and commission", "observational precision, local miniature line, transparent watercolor, and European shading combined in varying degrees", "transparent watercolor, paper white, botanical color, dress, and earth tones varying by subject and artist", "slight specimen shadows or more complex environmental light for architecture and figures rather than one archival softness", "European or Indian paper, transparent and opaque watercolor, mica, fine brushes, inscriptions, and binding", "labels must be exact and contextualize colonial naming; never fabricate species, community, occupation, or artist attribution"] },
  "bengal-school": { period: "约1890年代末–1930年代，影响延续", year: 1915, summary: "孟加拉画派形成于英属印度民族主义、殖民美术教育和亚洲主义讨论中，以阿巴宁德拉纳特·泰戈尔等人为核心，但成员和立场并不统一。洗染和诗性淡色是部分重要路线，不能覆盖其历史画、宗教图像、日中交流及后续分歧。", influencedBy: "印度民族主义、莫卧儿和拉其普特绘画、日本画交流、殖民美术学校与东方主义思想", influenced: "印度现代美术教育、圣蒂尼克坦、亚洲主义和反学院绘画讨论", related: ["company-painting", "kalighat-painting", "nihonga", "indian-modernism"], sources: BATCH_10_SOURCES.bengal, zh: ["疏朗中心、历史叙事、人物组像或装饰画面按艺术家与题材选择", "柔线洗染、细密画引用、写生或更坚实轮廓并存，不统一雾化", "淡褐、灰绿、靛蓝和低饱和暖色常见，也有更强综合色与墨线", "薄洗低对比或明确叙事明暗按作品处理，不以朦胧等同民族性", "吸水纸、水彩洗染、蛋彩、墨、日式材料影响和手工底层", "题名与孟加拉文、天城文、英文须准确；不仿造艺术家书写或民族主义口号"], en: ["sparse centers, historical narratives, figure groups, or decorative fields selected by artist and subject", "soft-line wash, miniature references, observation, and firmer contours coexisting without universal mistiness", "pale brown, gray-green, indigo, and muted warm color as common alongside stronger color and ink", "thin low-contrast wash or explicit narrative modeling selected by work without equating haze with national identity", "absorbent paper, watercolor wash, tempera, ink, Japanese material influence, and handmade grounds", "titles and Bengali, Devanagari, or English must be exact; never imitate artists' hands or nationalist slogans"] },
  "kalighat-painting": { period: "约1830–1930年代，以19世纪加尔各答为核心", year: 1870, summary: "卡利卡特画（Kalighat painting）由加尔各答卡利神庙周边市场的画工面向朝圣者和城市消费者制作，题材从神祇扩展到巴布文化、社会讽刺和都市事件。快速刷线和素底单体是典型，但版画竞争、作坊复制和综合色变化也属于其历史。", influencedBy: "孟加拉卷轴画师传统、加尔各答城市市场、神庙朝圣、殖民现代生活和印刷竞争", influenced: "印度大众艺术、民族主义和现代主义对民间图像的重估、讽刺漫画", related: ["company-painting", "bengal-school", "pattachitra", "pop-art"], sources: BATCH_10_SOURCES.kalighat, zh: ["单一放大主体、成对人物或少量互动场景置于素纸，保持快速市场图像的直接性", "粗黑连续轮廓、扫刷体积和概括姿态按神祇、都市或讽刺题材调整", "墨黑、纸白、有限鲜明综合色和局部金属色，不固定单一综合色组", "平面画面光与宽笔综合色提示体积，不添加油画式投影", "纸本水彩或不透明色、松鼠毛刷线、平滑综合色、作坊复制差异和老化", "孟加拉文题名、神名和讽刺文字必须准确；不生成伪文字或神圣标志"], en: ["one enlarged subject, paired figures, or limited interaction on open paper retaining the directness of market production", "heavy continuous contours, sweeping volume, and reduced gesture adjusted to deity, urban, or satirical subject", "ink black, paper white, limited bright color, and occasional metallic detail without one fixed palette", "flat pictorial light with broad tonal strokes suggesting volume and no oil-paint cast shadow", "watercolor or opaque color on paper, squirrel-hair brush line, smooth sweeps, workshop repetition, and aging", "Bengali titles, deity names, and satire must be exact; never generate false writing or sacred marks"] },
  "madhubani": { period: "米提拉地区墙面传统久远；纸本商业与公共传播自1960年代显著扩展", year: 1970, summary: "米提拉绘画（常称Madhubani）由印度比哈尔和尼泊尔特莱米提拉地区不同社群与女性传统发展，墙面、地面和纸本绘画在仪式、婚礼、市场与社会议题中作用不同。双线满纹和彩色密填是若干流派特征，不应掩盖kachni、bharni、godna等方法及身份差异。", influencedBy: "米提拉婚礼与宗教仪式、女性家居绘画、种姓社群传统和地方自然材料", influenced: "印度民间与当代艺术、女性艺术史、纸本市场和社会倡议图像", related: ["gond-painting", "warli-painting", "pattachitra", "rangoli-aesthetic"], sources: BATCH_10_SOURCES.madhubani, zh: ["边框满幅、中心仪式图、重复线场或保留空地按kachni、bharni、godna等路线选择", "双线、单线、密集排线、综合色填充和纹身式图形依社群与艺术家不同", "天然或商业综合色、黑白线画、纸墙本色并存，不强制高饱和满色", "完全平面或由线密度产生明度，不使用写实投影和综合色渐变", "泥墙、手工纸、布、天然或商业综合色、竹笔和真实手工不均", "只有准确且适当的迈蒂利文、天城文或题名才可出现；不伪造仪式符号"], en: ["bordered all-over fields, central ritual images, repeated line zones, or reserved ground selected among kachni, bharni, godna, and other practices", "double or single line, dense hatching, color fill, and tattoo-related forms varying by community and artist", "natural or commercial color, black-white line work, and wall or paper ground without mandatory saturation", "fully flat value or tone through line density, without realistic cast shadow or gradient modeling", "mud wall, handmade paper, cloth, natural or commercial color, bamboo tools, and genuine handmade variation", "use Maithili, Devanagari, or titles only when exact and appropriate; never fabricate ritual symbols"] },
  "gond-painting": { period: "当代纸本绘画约1980年代形成，源于更早贡德社群视觉与叙事传统", year: 1990, summary: "当代贡德绘画并非不变的古老纸本风格，而是在1980年代后由Jangarh Singh Shyam等来自印度中部贡德社群的艺术家，把地方叙事、墙面记忆和个体想象转化到纸与画布。点线填充很常见，但艺术家、氏族和世代语言并不统一。", influencedBy: "贡德社群叙事、房屋装饰和自然观、博帕尔艺术机构及个体艺术家创新", influenced: "印度当代原住民艺术、国际展览和后续贡德艺术家世代", related: ["madhubani", "warli-painting", "indigenous-contemporary-art", "aboriginal-dot-painting"], sources: BATCH_10_SOURCES.gond, zh: ["轮廓内纹理、满幅分叉、独立主体或复杂叙事按具体艺术家组织", "点、线、鳞片、网格和分叉结构是可选个体语汇，不生成通用“贡德纹”", "高饱和多色、黑白和有限综合色均可，综合色方案依艺术家与媒介", "平面综合色与纹样密度建立明暗，画布作品保留真实展场光", "纸或画布、墨水、丙烯、细笔点线、版画和可见手工节奏", "只在艺术家作品确有文字或用户提供准确内容时加入；不得伪造部族语言与签名"], en: ["textured outlined forms, all-over branching, isolated subjects, or complex narrative organized by a specific artist", "dots, lines, scales, grids, and branching structures as individual vocabularies rather than generic Gond pattern", "saturated multicolor, black-white, or restricted palettes varying by artist and medium", "flat color and pattern density building value, with real exhibition light for canvas objects", "paper or canvas, ink, acrylic, fine pen or brush marks, printmaking, and visible handmade rhythm", "add text only when present in an artist's work or supplied exactly; never fabricate community language or signatures"] },
  "warli-painting": { period: "仪式墙画传统久远；纸本和当代艺术自1970年代显著发展", year: 1980, summary: "瓦尔利绘画源于印度马哈拉施特拉瓦尔利社群的仪式墙面与女性绘画传统，1970年代后Jivya Soma Mashe等艺术家推动纸本个人创作。红褐墙与稻米白几何是仪式语境的重要机制，但当代作品的综合色、叙事和作者身份已扩展。", influencedBy: "瓦尔利社群仪式、婚礼墙画、农耕生活、泥墙与稻米浆材料", influenced: "印度原住民当代艺术、纸本市场、公共设计和社群文化表达", related: ["gond-painting", "madhubani", "indigenous-contemporary-art", "pattachitra"], sources: BATCH_10_SOURCES.warli, zh: ["中心环舞、婚礼方框、基线叙事或当代满幅场景按仪式与艺术家选择", "圆、三角、短线组成的人物和动物须保留动作逻辑，不当作任意图标库", "仪式墙画以稻米白和红褐泥底为主，当代纸布可有其他综合色", "传统墙面完全平面，当代材料保留真实纸布光，不添加体积投影", "泥墙、稻米浆、竹笔、纸或画布、商业综合色和手工不均", "仪式符号与社群名称须准确尊重；现代文字分开排版，不伪造瓦尔利语义"], en: ["central dances, wedding squares, baseline narratives, or contemporary all-over scenes selected by ritual and artist", "figures and animals assembled from circles, triangles, and short lines with coherent action rather than an arbitrary icon library", "rice-paste white on red-brown mud for ritual walls, with other colors possible in contemporary paper and cloth", "fully flat traditional walls and real paper or cloth light in contemporary work without volumetric shadow", "mud plaster, rice paste, bamboo tools, paper or canvas, commercial color, and handmade variation", "treat ritual symbols and community names accurately and respectfully; separate modern type and never invent Warli meanings"] },
  "pattachitra": { period: "奥迪沙和孟加拉相关传统延续至今，具体谱系年代各异", year: 1850, summary: "pattachitra 字面指布画，但常涉及奥迪沙围绕贾格纳特信仰的布本绘画，也与孟加拉卷轴pata传统在中文中混称。两者的叙事、表演、材料和图像体系不同；密集边框、满幅平涂只适合部分奥迪沙作品，不能覆盖所有pata绘画。", influencedBy: "奥迪沙贾格纳特寺院和画工传统、孟加拉卷轴歌唱传统、地方宗教与手工材料", influenced: "印度民间绘画、旅游工艺、当代卷轴叙事和公共文化", related: ["kalighat-painting", "madhubani", "warli-painting", "rajasthani-miniature"], sources: BATCH_10_SOURCES.pattachitra, zh: ["奥迪沙单幅或连环布画与孟加拉长卷叙事须分别组织，不统一为无空白边框画", "均匀轮廓、装饰节点、神像或连续故事按地区工坊和表演用途选择", "朱红、黄、绿、黑、白、蓝和布底按天然或现代材料变化", "综合色块对比建立层级，卷轴表演在真实环境光下展开，不添加金色辉光", "处理布或纸、天然与商业综合色、胶、精细线、卷折、使用和修复痕迹", "神名、奥迪亚文、孟加拉文和叙事文字必须准确；不得混用地区文字或伪经文"], en: ["Odishan single or serial cloth paintings and Bengali long-scroll narratives organized separately rather than one border-filled formula", "uniform contours, ornament, deity images, or continuous stories selected by regional workshop and performance use", "vermilion, yellow, green, black, white, blue, and support color varying with natural and modern materials", "hierarchy through flat color contrast, with scroll performance unfolding in real ambient light and no golden glow", "prepared cloth or paper, natural and commercial color, binder, fine line, rolling, use, and repair traces", "deity names, Odia, Bengali, and narrative text must be exact; never mix regional scripts or fabricate scripture"] }
};

