const BATCH_11_REVIEWS = {
  "kufic-calligraphy-aesthetic": { period: "约7世纪形成，后续产生多种地域和装饰分支", year: 800, summary: "库法体是早期阿拉伯书法多类角折或纪念性书体的宽泛称谓，见于《古兰经》写本、建筑、钱币和工艺。方整、延长横画和几何化只描述部分类型；东库法、叶饰库法、方形库法等在年代、媒介和可读性上不能混为一体。", influencedBy: "早期阿拉伯文字、伊斯兰宗教书写、羊皮纸写本和建筑铭文", influenced: "伊斯兰建筑书法、手抄本、钱币和当代阿拉伯字体设计", related: ["naskh-calligraphy-aesthetic", "islamic-geometry", "islamic-manuscript-illumination", "seljuk-art"], sources: BATCH_11_SOURCES.kufic, zh: ["基线、横向展开、行距和字间比例按早期写本、建筑或方形库法具体类型组织", "角折、宽笔、延长横画、叶饰或网格结构须来自可识别字形而非任意几何", "墨黑、羊皮纸、石材、砖、釉色和金依据载体，不设黑金统一方案", "写本平面阅读光，石刻砖铭用克制侧光显示真实深度", "羊皮纸墨迹、芦苇笔、石刻、砖砌、釉砖、钱币和真实磨损", "文字是内容主体；只有在阿拉伯文准确、方向正确且可辨识时使用，不生成伪经文"], en: ["baseline, horizontal extension, spacing, and line measure selected for a specific early manuscript, architectural, or square-Kufic type", "angular broad strokes, elongated horizontals, foliated forms, or grids derived from recognizable letters rather than arbitrary geometry", "ink, parchment, stone, brick, glaze, and gold determined by support without one black-gold formula", "flat reading light for manuscripts and restrained sidelight revealing real carved or brick depth", "parchment ink, reed pen, carved stone, brickwork, glazed tile, coinage, and genuine wear", "text is the content; use only exact correctly directed and recognizable Arabic, and never fabricate scripture"] },
  "naskh-calligraphy-aesthetic": { period: "约9–10世纪规范化并延续至今", year: 1100, summary: "纳斯赫体在中世纪伊斯兰书写中逐步规范化，以圆润、紧凑和较高可读性广泛用于《古兰经》、书籍与日常抄写。它不是几何纹样，也不能把点画、基线和字母连接替换成装饰边框；不同地区和书家仍有比例差异。", influencedBy: "早期阿拉伯书写、阿拔斯时期书法规范、芦苇笔与纸张传播", influenced: "阿拉伯语和奥斯曼书籍、印刷与现代标准字体", related: ["kufic-calligraphy-aesthetic", "diwani-calligraphy-aesthetic", "islamic-manuscript-illumination", "ottoman-decorative-art"], sources: BATCH_11_SOURCES.naskh, zh: ["稳定基线、清楚行距、页边和正文层级服务连续阅读，不作放射几何布局", "圆润比例、可辨点画、字母连接和粗细变化须按真实纳斯赫书法", "墨黑、纸色、朱砂标题和金饰按写本用途选择，不设珠宝综合色", "均匀平面阅读光保持小字号字形和点画清楚", "纸本墨迹、芦苇笔切锋、抛光纸、校勘痕和装帧", "必须准确保留阿拉伯文、字母顺序、连接和附加符号；不得伪造宗教文本"], en: ["stable baselines, clear leading, margins, and text hierarchy serving continuous reading rather than radial geometry", "rounded proportions, legible dots, letter joins, and stroke modulation grounded in real Naskh", "black ink, paper, rubrication, and gold selected by manuscript function without jewel color", "even flat reading light keeping small letterforms and diacritics clear", "ink on paper, cut reed-pen strokes, burnished paper, corrections, and binding", "preserve exact Arabic, letter order, joining, and diacritics; never fabricate religious text"] },
  "nastaliq-calligraphy-aesthetic": { period: "约14世纪形成，15世纪成熟并延续至今", year: 1500, summary: "纳斯塔利克体在伊朗及波斯语文化圈形成，尤其适用于波斯诗歌、书信和相册页，以斜行、悬垂节奏和强烈粗细变化著称。它不是所有波斯文的默认字体，也不适合在无法准确排写连字时被模拟为流动曲线。", influencedBy: "纳斯赫与塔利克书体、波斯语诗歌文化、帖木儿和伊朗书法工坊", influenced: "波斯、莫卧儿和南亚书籍艺术、相册页与现代波斯字体", related: ["persian-miniature", "safavid-miniature", "islamic-manuscript-illumination", "naskh-calligraphy-aesthetic"], sources: BATCH_11_SOURCES.nastaliq, zh: ["斜向下降行列、悬挂式词组和宽阔页边按诗歌或书信篇章组织", "短竖、长横、流畅弧线和字间连带必须来自准确纳斯塔利克结构", "墨黑、纸色、金饰和克制矿物边饰从写本或书法页取得", "均匀阅读光突出墨色和斜行节奏，金饰只保留真实反光", "芦苇笔墨迹、抛光纸、剪贴书法、金饰和装帧纤维", "只在波斯文或相关语言准确、连接正确时使用；不得伪造诗句、署名或书法"], en: ["descending diagonal lines, suspended word groups, and broad margins organized for a poem or letter", "short verticals, long horizontals, flowing curves, and joins derived from exact Nastaliq structure", "black ink, paper, gold, and restrained mineral borders derived from a manuscript or calligraphy page", "even reading light emphasizing ink and diagonal rhythm, with only real reflection from gold", "reed-pen ink, burnished paper, cut calligraphy, gold illumination, and binding fibers", "use only when Persian or another appropriate language is exact and correctly joined; never fabricate verse, signatures, or calligraphy"] },
  "diwani-calligraphy-aesthetic": { period: "约15世纪后期形成，16世纪奥斯曼宫廷成熟并延续", year: 1650, summary: "迪瓦尼体在奥斯曼宫廷文书体系中发展，以紧密连写、上升曲线和复杂点画形成难以仿造的行政书写；jali diwani 又有更密集装饰。它不是一般阿拉伯装饰字，也不等同印玺轮廓或任意回旋线。", influencedBy: "奥斯曼宫廷文书、波斯塔利克书写、行政保密和专业书记训练", influenced: "奥斯曼官方书法、证书、现代阿拉伯书法与展示字体", related: ["naskh-calligraphy-aesthetic", "ottoman-decorative-art", "islamic-manuscript-illumination", "tughra-aesthetic"], sources: BATCH_11_SOURCES.diwani, zh: ["紧密行块、上升走势和空隙填点按普通迪瓦尼或jali diwani分别组织", "高度连写、回旋曲线、粗细变化和点画必须保持准确字母关系", "黑墨、金墨、纸色与少量朱红按宫廷文书或书法页选择", "完全平面阅读光保证密集字势仍可辨，不添加金属立体光效", "抛光纸、芦苇笔、墨或金泥、细点、校正和文书折痕", "必须准确保留奥斯曼土耳其文或阿拉伯文；无法保证连接时不得模拟迪瓦尼体"], en: ["compact line blocks, rising movement, and filled interstices organized separately for Diwani or Jali Diwani", "dense joining, looping curves, modulation, and dots preserving exact letter relations", "black or gold ink, paper, and limited red selected for a court document or calligraphy sheet", "fully flat reading light keeping dense forms discernible without metallic dimensional effects", "burnished paper, reed pen, ink or shell gold, fine dots, corrections, and document folds", "preserve Ottoman Turkish or Arabic exactly; do not simulate Diwani when correct joining cannot be guaranteed"] },
  "islamic-geometry": { period: "约8世纪至今，跨地域和媒介持续发展", year: 1200, summary: "伊斯兰艺术中的几何装饰是跨西亚、北非、伊比利亚、南亚等地发展的构造方法，使用圆规直尺、星形多边形、交织和镶嵌；它不是宗教统一规定，也不是所有伊斯兰艺术的本质。综合色、网格复杂度和材料随地域与时代显著变化。", influencedBy: "晚期古代和区域几何传统、数学实践、建筑工艺与伊斯兰世界跨地域交流", influenced: "建筑、木石金属、瓷砖和书籍装饰，以及现代图案和数学设计", related: ["islamic-arabesque", "zellige-aesthetic", "andalusian-ornament", "seljuk-art"], sources: BATCH_11_SOURCES.geometry, zh: ["放射、星网、交织带或周期镶嵌按具体遗址和构造系统展开，不强制中心对称", "多边形、星形、strapwork和节点须保持可施工连接与一致拓扑", "综合色来自砖、木、石、釉砖、马赛克和写本，不固定钴蓝绿松石金", "平面图样保持清楚；建筑和物件使用真实环境光、凹凸阴影和釉面反射", "砖、石木雕、石膏、马赛克、釉砖、金属、纸和手工接缝", "文字不是几何填充；若有铭文必须准确、独立可读且不得伪造经文"], en: ["radial, star-grid, interlaced-band, or periodic tessellation selected from a specific monument and construction system without mandatory central symmetry", "polygons, stars, strapwork, and nodes maintaining buildable joins and consistent topology", "color derived from brick, timber, stone, tile, mosaic, and manuscript rather than fixed cobalt-turquoise-gold", "clear flat pattern for drawings, with real ambient light, relief shadow, and glaze reflection on architecture and objects", "brick, carved stone or wood, stucco, mosaic, glazed tile, metal, paper, and handmade joints", "text is not geometric filler; inscriptions must be exact, separately legible, and never fabricated scripture"] },
  "islamic-arabesque": { period: "约9世纪至今，跨地域植物装饰传统", year: 1200, summary: "Arabesque 是欧洲艺术史中用于描述伊斯兰艺术连续卷草、分叉叶茎和抽象植物填充的术语，其涵盖范围宽且外部命名色彩明显。它与几何纹样、书法可组合却不等同，也不能代表所有伊斯兰装饰。", influencedBy: "晚期古代卷草、萨珊和拜占庭植物装饰、伊斯兰建筑与工艺抽象化", influenced: "伊斯兰建筑和书籍装饰、欧洲arabesque接受及现代图案设计", related: ["islamic-geometry", "islamic-manuscript-illumination", "ottoman-decorative-art", "mamluk-decorative-art"], sources: BATCH_11_SOURCES.arabesque, zh: ["连续边带、对称生长、旋转填充或满幅卷草按具体媒介组织，不设一种无限模板", "分叉茎线、叶片、花苞和正负形连接保持植物节律与手工结构", "综合色来自灰泥、木石、釉彩、织物和金饰，不固定蓝绿金", "平面装饰和真实浮雕、釉面或金属反光分别处理", "彩绘灰泥、木石雕、陶瓷、织物、金属、纸本综合色与金饰", "书法带如存在必须准确并与植物纹样层级清楚，不用伪文字补空"], en: ["continuous borders, mirrored growth, rotational fill, or all-over scrollwork organized by medium without one infinite template", "branching stems, leaves, buds, and positive-negative joins retaining vegetal rhythm and handmade structure", "color derived from stucco, wood, stone, glaze, textile, and gold rather than fixed blue-green-gold", "flat ornament and real relief, glaze, or metal reflection treated separately", "painted stucco, carved wood or stone, ceramic, textile, metal, manuscript color, and gold", "when present, calligraphic bands must be exact and hierarchically distinct; never fill gaps with pseudo-writing"] },
  "islamic-manuscript-illumination": { period: "约8世纪至今，不同地区类型各异", year: 1400, summary: "伊斯兰写本金饰涵盖《古兰经》、文学、科学和相册等书籍的篇章页、题签、页边与书法周边装饰，跨阿拉伯、波斯、奥斯曼、莫卧儿等多种传统。它不必有中心图像或首字母，也不能把基督教手抄本结构套用为统一模板。", influencedBy: "早期《古兰经》制作、晚期古代书籍工艺、纸张传播、书法和各宫廷装帧作坊", influenced: "波斯、奥斯曼、莫卧儿书籍艺术和现代手工装帧", related: ["kufic-calligraphy-aesthetic", "naskh-calligraphy-aesthetic", "nastaliq-calligraphy-aesthetic", "persian-miniature"], sources: BATCH_11_SOURCES.illumination, zh: ["篇章页、题签、页框、行间金饰或边际图案围绕文本功能组织，不强制中心图像", "几何、卷草、云纹、花卉和金点按地区工坊使用，保持精密手工边缘", "金、群青、朱红、绿、纸或羊皮纸本色依文本、时期和资源变化", "均匀阅读光保留书法与装饰层级，金箔只呈真实小反射", "羊皮纸或纸、墨、金箔或金泥、矿物综合色、抛光和装帧", "经文、诗文、题签和页码必须准确；不能用装饰性伪阿拉伯或波斯文字"], en: ["chapter openings, title panels, frames, interlinear gold, or marginal motifs organized around textual function without a required central image", "geometry, scrollwork, clouds, flora, and gold dots selected by regional workshop with precise handmade edges", "gold, ultramarine, vermilion, green, and paper or parchment varying by text, date, and resources", "even reading light retaining hierarchy between calligraphy and ornament, with only small real gold reflection", "parchment or paper, ink, gold leaf or shell gold, mineral color, burnishing, and binding", "scripture, poetry, titles, and foliation must be exact; never use decorative pseudo-Arabic or pseudo-Persian"] },
  "andalusian-ornament": { period: "约8–15世纪安达卢斯核心期，后续保存与复兴延长", year: 1350, summary: "安达卢斯装饰是对伊比利亚伊斯兰政权建筑和工艺中几何、植物、书法、木作、灰泥与瓷砖的宽泛概括，从科尔多瓦到纳斯里德格拉纳达差异显著。它不能与摩洛哥泽利吉同文，也不应把10世纪至今写成连续不变样式。", influencedBy: "倭马亚、北非和伊比利亚晚期古代传统、地方工匠与宫廷建筑", influenced: "穆德哈尔艺术、马格里布建筑、伊比利亚装饰和现代安达卢西亚复兴", related: ["zellige-aesthetic", "islamic-geometry", "islamic-arabesque", "mudejar-art"], sources: BATCH_11_SOURCES.andalusian, zh: ["建筑轴线、庭院水景、墙面分带、拱券和连续铭文按具体遗址与王朝组织", "马蹄拱、sebka网、灰泥卷草、木作几何和瓷砖各有材料结构", "石灰白、赭红、木色、釉彩和残存综合色依据遗址，不固定宝石色", "庭院日光、深檐阴影、灰泥低浮雕和水面反射按真实建筑处理", "石、砖、雕灰泥、木作、釉砖、马赛克、灰缝和风化", "阿拉伯铭文、赞词和王朝格言只在准确释读时使用；不生成阿尔罕布拉伪文"], en: ["architectural axes, court water, wall registers, arches, and continuous inscriptions organized by a specific monument and dynasty", "horseshoe arches, sebka grids, stucco scrollwork, timber geometry, and tile each retaining its material structure", "lime white, ochre red, timber, glaze, and surviving pigment based on the monument rather than jewel color", "courtyard sun, deep-eave shadow, low stucco relief, and water reflection treated as real architecture", "stone, brick, carved stucco, timber, glazed tile, mosaic, grout, and weathering", "use Arabic inscriptions, praise, and dynastic mottos only when accurately read; never generate false Alhambra text"] },
  "zellige-aesthetic": { period: "约10世纪以后发展，马林王朝及后世马格里布尤重要", year: 1400, summary: "泽利吉（zellij）是摩洛哥及马格里布以手切单色釉陶片拼装几何图案的建筑工艺，网格、综合色和切片尺寸取决于墙裙、地面、喷泉等位置。它不是安达卢西亚装饰的同义词，也不等于任何彩色几何瓷砖。", influencedBy: "马格里布陶工和建筑工艺、伊斯兰几何构造、安达卢斯与北非交流", influenced: "摩洛哥建筑、马格里布工艺、当代室内和全球瓷砖设计", related: ["andalusian-ornament", "islamic-geometry", "mamluk-decorative-art", "islamic-arabesque"], sources: BATCH_11_SOURCES.zellige, zh: ["星网、辐射或条带按墙裙、地坪、喷泉和柱面尺度切分并无缝连接", "手切多边陶片、窄灰缝和节点保持真实拼装逻辑与微小尺寸差", "白、黑、绿、蓝、赭黄和棕等单色釉片按时代地区组合，不设金色", "真实环境光在釉面产生小高光，灰缝与微起伏形成细阴影", "手切釉陶片、陶胎断面、灰浆、细灰缝、釉面针孔和手工偏差", "通常不嵌文字；若与铭文相邻，文字必须准确且保持独立可读"], en: ["star grids, radial systems, or bands divided for dadoes, floors, fountains, and columns with seamless construction", "hand-cut polygonal tesserae, narrow grout, and nodes retaining real assembly logic and small dimensional variation", "white, black, green, blue, ochre yellow, and brown monochrome glazes combined by place and date without gold", "real ambient light making small glaze highlights, with grout and slight relief producing fine shadows", "hand-cut glazed tesserae, ceramic bodies, mortar, fine grout, glaze pinholes, and handmade variation", "text is usually separate; adjacent inscriptions must be exact and independently legible"] },
  "iznik-aesthetic": { period: "约15世纪末–17世纪，16世纪为高峰", year: 1570, summary: "伊兹尼克陶瓷由奥斯曼时期安纳托利亚伊兹尼克工坊生产，涵盖器皿和建筑砖，釉下钴蓝、绿松石、绿色和凸起铁红随阶段发展。郁金香、康乃馨、saz叶和中国瓷器影响重要，但白地花簇不是每件作品的固定构图。", influencedBy: "奥斯曼宫廷设计工坊、中国青花瓷、伊朗陶瓷和安纳托利亚制陶", influenced: "奥斯曼建筑瓷砖、欧洲陶瓷收藏和现代土耳其装饰", related: ["ottoman-decorative-art", "islamic-arabesque", "islamic-geometry", "chinoiserie"], sources: BATCH_11_SOURCES.iznik, zh: ["器皿曲面、盘心边带或建筑砖连续面按载体组织花卉、saz叶和几何", "钴蓝主线、闭合色区、弧叶花瓣和手绘接笔随阶段工坊变化", "钴蓝、绿松石、绿色、锰紫、凸起铁红和白地按年代选择", "柔和环境光显示透明釉和凸红小高光，不做玻璃镜面反射", "石英质陶胎、釉下彩、透明釉、烧成微差、裂纹和手绘边缘", "只有原物确有且可准确转写时使用阿拉伯书法；不把伪文字当花纹"], en: ["vessel curvature, dish centers and borders, or continuous architectural tiles organizing flora, saz leaves, and geometry by support", "cobalt key lines, closed color cells, curved petals and leaves, and hand-painted joins varying by phase and workshop", "cobalt, turquoise, green, manganese purple, raised bole red, and white selected by date", "soft ambient light showing clear glaze and small highlights on raised red without mirror-glass reflection", "quartz-rich ceramic body, underglaze color, clear glaze, firing variation, craquelure, and hand-painted edges", "use Arabic calligraphy only when present and accurately transcribed; never treat pseudo-writing as floral pattern"] },
  "seljuk-art": { period: "约11–13世纪，伊朗与安纳托利亚等地区差异显著", year: 1200, summary: "塞尔柱艺术横跨大塞尔柱和安纳托利亚塞尔柱等不同政权，涵盖清真寺、学院、商队驿站、陶瓷、金属和写本。砖几何、铭文、釉砖与石雕很重要，但伊朗砖建筑和安纳托利亚石门廊不能统一成同一蓝砖风格。", influencedBy: "伊朗、中亚、安纳托利亚与亚美尼亚等区域工艺、伊斯兰建筑和游牧宫廷网络", influenced: "伊尔汗、安纳托利亚诸侯与奥斯曼建筑、伊朗陶瓷金属和几何装饰", related: ["ilkhanid-art", "ottoman-decorative-art", "islamic-geometry", "kufic-calligraphy-aesthetic"], sources: BATCH_11_SOURCES.seljuk, zh: ["伊朗砖砌穹顶和伊万、安纳托利亚石门廊或器物表面按地区功能组织", "砖砌几何、石雕卷草、穆卡纳斯、釉砖和书法带依材料与政权区分", "砖红、石色、钴蓝、绿松石、黑白来自地区材料，不强制蓝色主导", "真实强日光和擦边光显示砖缝、石刻、穆卡纳斯与釉面", "砖、石、灰泥、木雕、釉砖、陶瓷、金属嵌饰和风化", "铭文必须准确并区分库法、纳斯赫等实际书体，不伪造宗教和建造文字"], en: ["Iranian brick domes and iwans, Anatolian stone portals, or object surfaces organized by region and function", "brick geometry, carved vegetal stone, muqarnas, tile, and calligraphic bands distinguished by material and polity", "brick red, stone, cobalt, turquoise, black-white from regional materials without mandatory blue dominance", "real strong sun and grazing light revealing joints, carving, muqarnas, and glaze", "brick, stone, stucco, carved wood, glazed tile, ceramic, metal inlay, and weathering", "inscriptions must be exact and use the actual Kufic, Naskh, or other script; never fabricate sacred or foundation text"] },
  "ilkhanid-art": { period: "1256–1353年，后续影响延长", year: 1320, summary: "伊尔汗艺术形成于蒙古统治伊朗时期，涵盖巨构建筑、釉砖、金属、陶瓷和大型历史与宗教写本。中国和蒙古图像、伊朗传统及跨欧亚交流显著；现有13–19世纪年代错误，且不能只用波斯细密画页描述整个王朝艺术。", influencedBy: "伊朗和伊斯兰艺术、蒙古帝国跨欧亚交流、中国绘画与纸张书籍技术", influenced: "帖木儿和萨法维艺术、波斯历史写本及伊朗建筑陶瓷", related: ["seljuk-art", "timurid-art", "persian-miniature", "islamic-manuscript-illumination"], sources: BATCH_11_SOURCES.ilkhanid, zh: ["建筑纪念轴线、穹顶和书法带，或写本多焦点叙事按媒介分别组织", "砖石体量、釉砖、精细人物动物、云山和中国来源线索按具体作品使用", "砖石本色、钴蓝绿松石、群青、朱红、金和纸色依建筑或写本变化", "建筑使用真实日光，写本保持平面阅读光与有限金色反射", "砖石、釉砖、灰泥、金属、纸本不透明水彩、金和装帧", "阿拉伯文和波斯文历史宗教文字必须准确；不伪造拉施特丁等写本题记"], en: ["monumental architectural axes, domes, and inscription bands, or multifocal manuscript narratives organized separately by medium", "brick-stone mass, tile, fine figures and animals, clouds, mountains, and Chinese-derived elements used from a specific work", "brick and stone, cobalt-turquoise, ultramarine, vermilion, gold, and paper varying between architecture and manuscript", "real daylight for architecture and flat reading light with restrained gold reflection for books", "brick, stone, glazed tile, stucco, metal, opaque watercolor on paper, gold, and binding", "Arabic and Persian historical or religious text must be exact; never fabricate Rashid al-Din manuscript inscriptions"] },
  "timurid-art": { period: "约1370–1507年", year: 1450, summary: "帖木儿艺术以撒马尔罕、赫拉特等宫廷的宏大建筑、釉砖、金工、书法和书籍艺术著称，并通过跨地区艺术家迁徙形成多样中心。蓝色建筑和精密写本重要，但不能把建筑瓷砖纹理塞入每幅细密画或把宫廷风格视为整个中亚。", influencedBy: "伊尔汗和中亚艺术、蒙古帝国交流、伊朗书籍工坊与被迁徙的区域工匠", influenced: "萨法维、莫卧儿和乌兹别克艺术，以及波斯细密画和中亚建筑", related: ["ilkhanid-art", "safavid-miniature", "persian-miniature", "mughal-miniature"], sources: BATCH_11_SOURCES.timurid, zh: ["城市纪念轴线和庭院、或写本高视点多焦点空间按建筑和书籍分开", "高耸门廊、穹顶、釉砖网格与精细人物山水分别服从媒介", "钴蓝、绿松石、砖色、群青、朱红、金和纸色按遗址或工坊变化", "建筑真实日光与写本平面阅读光分开，不统一蓝金辉光", "砖、马赛克釉砖、石膏、纸本综合色、金、书法和抛光装帧", "波斯文、阿拉伯文和察合台文题记必须准确，不生成伪帖木儿铭文"], en: ["monumental urban axes and courts, or high-view multifocal manuscript space treated separately for architecture and books", "towering portals, domes, tile grids, and fine figures or landscapes each governed by its medium", "cobalt, turquoise, brick, ultramarine, vermilion, gold, and paper varying by monument or workshop", "real architectural daylight separated from flat manuscript reading light without one blue-gold glow", "brick, mosaic tile, plaster, manuscript pigment, gold, calligraphy, and burnished binding", "Persian, Arabic, and Chagatai inscriptions must be exact; never generate false Timurid text"] },
  "safavid-miniature": { period: "1501–1736年，16–17世纪宫廷和城市工坊尤重要", year: 1600, summary: "萨法维绘画涵盖大不里士、加兹温、伊斯法罕等阶段的皇家写本、单页人物、相册与市场作品。花园式层叠和纳斯塔利克书法重要，但16世纪大型写本与17世纪单人画页的构图、综合色和赞助机制不同。", influencedBy: "帖木儿和土库曼书籍艺术、波斯诗歌书法、萨法维宫廷与城市市场", influenced: "莫卧儿、德干、奥斯曼和卡扎尔绘画，以及波斯相册页传统", related: ["persian-miniature", "timurid-art", "mughal-miniature", "qajar-painting"], sources: BATCH_11_SOURCES.safavid, zh: ["多焦点写本、花园宫廷、单页人物或相册边饰按阶段与画家选择", "精细轮廓、流动衣线、织纹、岩石云树和17世纪拉长人物依作品使用", "群青、朱红、粉、绿、金和纸色范围随大不里士至伊斯法罕阶段变化", "综合色区、重叠和金饰构成页面空间，不设统一宝石光", "抛光纸、不透明水彩、金、精线、剪贴书法、边饰和装帧", "纳斯塔利克题签、诗文和署名必须准确；不得伪造礼萨·阿巴西等名家题款"], en: ["multifocal manuscripts, court gardens, single figures, or album borders selected by phase and painter", "fine contour, flowing drapery, textile pattern, rocks, clouds, trees, and later elongated figures used where documented", "ultramarine, vermilion, pink, green, gold, and paper varying from Tabriz through Isfahan phases", "page space through bounded color, overlap, and gold without one jewel-like glow", "burnished paper, opaque watercolor, gold, fine line, cut calligraphy, borders, and binding", "Nastaliq labels, poetry, and signatures must be exact; never fabricate a Riza Abbasi or other master's inscription"] },
  "ottoman-decorative-art": { period: "约14世纪末–20世纪初，16世纪宫廷体系尤重要", year: 1600, summary: "奥斯曼装饰艺术跨建筑、伊兹尼克陶瓷、书籍、纺织、木作、金属和宫廷设计工坊，不能用11–19世纪的通用卷草模板概括。rumi、hatayi、saz、郁金香等纹样及综合色随媒介和世纪变化，也不等同马穆鲁克艺术。", influencedBy: "安纳托利亚塞尔柱、拜占庭、伊朗和中亚艺术、宫廷设计工坊及地中海交流", influenced: "巴尔干、中东和北非建筑工艺、欧洲装饰和现代土耳其设计", related: ["iznik-aesthetic", "ottoman-miniature", "diwani-calligraphy-aesthetic", "islamic-arabesque"], sources: BATCH_11_SOURCES.ottoman, zh: ["穹顶墙面、瓷砖连续面、书页、纺织或器物曲面按载体分区组织", "rumi、hatayi、saz叶、花卉、几何和书法依世纪与工坊选择", "钴蓝、绿松石、红、绿、金、木和金属本色按媒介变化", "建筑环境光、釉面反射、金属高光和写本平面光分别处理", "釉砖陶瓷、纸本金饰、丝绒、木嵌、金属、石和灰泥", "奥斯曼土耳其文、阿拉伯文和书法徽记必须准确；不得伪造图格拉或经文"], en: ["domes and walls, continuous tile fields, pages, textiles, or vessel curves zoned by support", "rumi, hatayi, saz leaves, flora, geometry, and calligraphy selected by century and workshop", "cobalt, turquoise, red, green, gold, timber, and metal color varying by medium", "architectural ambient light, glaze reflection, metal highlight, and flat manuscript light treated separately", "glazed tile and ceramic, illuminated paper, velvet, wood inlay, metal, stone, and stucco", "Ottoman Turkish, Arabic, and calligraphic emblems must be exact; never fabricate a tughra or scripture"] },
  "mamluk-decorative-art": { period: "1250–1517年，后续工艺影响延长", year: 1400, summary: "马穆鲁克艺术形成于埃及和叙利亚的马穆鲁克苏丹国，以开罗等城市的宗教和慈善建筑、纪念性铭文、嵌错金属、珐琅玻璃、木作和写本闻名。其年代不是11–19世纪，也不能复制奥斯曼卷草和釉砖体系。", influencedBy: "阿尤布和地区伊斯兰工艺、开罗与大马士革城市赞助、地中海和红海贸易", influenced: "后续埃及叙利亚建筑、奥斯曼工艺和欧洲对伊斯兰金属玻璃的收藏", related: ["islamic-geometry", "islamic-arabesque", "islamic-manuscript-illumination", "ottoman-decorative-art"], sources: BATCH_11_SOURCES.mamluk, zh: ["建筑立面、穹顶、木屏、器物铭文带和写本页按功能建立纪念层级", "几何木作、石材综合色镶嵌、粗壮铭文、金属嵌错和珐琅图案各自独立", "石材黑白红、黄铜银、综合色玻璃、木色和写本金色依媒介变化", "建筑用强日光和深凹阴影，金属玻璃保留真实反射，写本用平面光", "石材、木嵌、黄铜银嵌、珐琅玻璃、灰泥、纸和装帧", "阿拉伯铭文、头衔和捐建文字必须准确；不得伪造苏丹名号和经文"], en: ["architectural facades, domes, wooden screens, inscribed vessels, and manuscripts establishing hierarchy by function", "geometric woodwork, polychrome stone, monumental inscriptions, metal inlay, and enamel pattern treated as distinct crafts", "black-white-red stone, brass-silver, colored glass, timber, and manuscript gold varying by medium", "strong sun and deep recesses for architecture, real reflection for metal and glass, and flat reading light for books", "stone, wood inlay, brass with silver, enamel glass, stucco, paper, and binding", "Arabic inscriptions, titles, and foundation text must be exact; never fabricate sultans' names or scripture"] },
  "qajar-painting": { period: "约1780年代–1925年", year: 1850, summary: "卡扎尔绘画涵盖宫廷大型油画、漆器、写本、相册、玻璃画和后来摄影影响下的作品，以王权肖像和欧洲式明暗的选择性吸收著称。正面长身君主与珠宝只是部分宫廷类型，不能覆盖民间、宗教和晚期题材。", influencedBy: "萨法维和赞德绘画、欧洲油画版画、卡扎尔宫廷、漆器与摄影", influenced: "伊朗近现代绘画、摄影、咖啡馆绘画和国家肖像文化", related: ["safavid-miniature", "persian-miniature", "orientalist-painting", "photography"], sources: BATCH_11_SOURCES.qajar, zh: ["纪念性正面肖像、拱形壁龛、相册小像、漆器画或叙事场景按媒介与阶段选择", "平滑综合色体积、拉长比例、精密服饰或较民间化轮廓不设统一宫廷脸型", "深红、孔雀蓝绿、黑、金、综合色肤色和摄影灰阶均可", "正面均匀光、欧洲式柔和明暗或摄影光按作品年代使用，不做电影暗影", "油彩、纸本综合色、漆面、玻璃、镜饰、摄影材料和抛光表面", "波斯文题记与纳斯塔利克必须准确；不得伪造君主名号、名家署名或王室印"], en: ["monumental frontal portraits, arched niches, album miniatures, lacquer painting, or narrative scenes selected by medium and phase", "smooth modeling, elongated proportion, precise dress, or more popular contours without one courtly face type", "deep red, peacock blue-green, black, gold, modeled flesh, and photographic gray as appropriate", "even frontal light, soft European-derived modeling, or photographic light selected by date without cinematic darkness", "oil, pigment on paper, lacquer, glass, mirrorwork, photographic material, and polished surfaces", "Persian inscriptions and Nastaliq must be exact; never fabricate royal titles, artists' signatures, or court seals"] },
  "ottoman-miniature": { period: "约15–18世纪，16–17世纪宫廷工坊尤重要", year: 1600, summary: "奥斯曼细密画主要服务宫廷史书、节庆记录、地理、家谱和图册，由绘画、书法和装帧工坊协作。地图式俯视和纪实群组在部分作品中突出，但幻想文学、肖像和不同宫廷阶段也存在，不能一律写成无装饰的编年图解。", influencedBy: "波斯和帖木儿书籍艺术、拜占庭与地中海图像、奥斯曼宫廷史学和nakkaşhane工坊", influenced: "奥斯曼历史图像、地理绘图、宫廷肖像和现代土耳其书籍艺术", related: ["ottoman-decorative-art", "persian-miniature", "islamic-manuscript-illumination", "timurid-art"], sources: BATCH_11_SOURCES.ottomanMiniature, zh: ["地图式俯视、建筑分区、横向仪典群组、肖像或幻想场景按文本类型组织", "硬边人物、重复姿态、可辨服饰建筑和少量综合色体积随工坊阶段变化", "朱红、群青、绿、赭黄、金和纸色按写本与时期选择", "平面阅读光与综合色分区建立事件次序，金色保持小范围真实反光", "纸本不透明水彩、金、细线、书法、装帧和修订叠层", "奥斯曼土耳其文、阿拉伯文、地名和题签必须准确；不得生成伪历史文书"], en: ["map-like views, architectural zones, horizontal ceremonial groups, portraits, or fantasy scenes organized by textual genre", "hard-edged figures, repeated poses, legible dress and architecture, and limited modeling varying by workshop and phase", "vermilion, ultramarine, green, ochre, gold, and paper selected by manuscript and date", "flat reading light and bounded color ordering events, with small real reflections from gold", "opaque watercolor on paper, gold, fine line, calligraphy, binding, and revision layers", "Ottoman Turkish, Arabic, place names, and labels must be exact; never generate false historical documents"] }
};

