const BATCH_15_REVIEWS = {
  "maximalism": { period: "跨时期倾向；20世纪后期至今作为当代设计标签尤常见", year: 1980, summary: "极繁主义不是边界清楚的单一运动，而是以丰盛、重复、综合色、图案、收藏和多重历史引用对抗简约规范的跨媒介倾向。高密度并不意味着无层级堆砌；巴洛克、维多利亚室内、后现代设计和当代时尚各有不同机制。", influencedBy: "巴洛克与洛可可装饰、历史主义、收藏陈设、波普艺术、后现代主义及反极简立场", influenced: "当代室内、时尚、编辑设计、品牌与沉浸式展览中的高密度表达", related: ["rococo", "baroque", "postmodernism", "pattern-and-decoration"], sources: BATCH_15_SOURCES.maximalism, zh: ["以主次焦点、分区和重复节奏控制高密度，不把所有空白填满", "图案、物件、纹理和历史引用可多层并置，但保持尺度与边界可辨", "综合色可以宝石色、粉彩、黑白或地方综合色体系构成，不固定深色底和金色", "真实环境光区分材质和层级，局部强调不等于全场戏剧照明", "织物、壁纸、木、漆、金属、陶瓷、纸张和收藏物的真实表面", "文字按具体媒介与年代准确可读；不以多字体混排自动代表极繁"], en: ["high density controlled through focal hierarchy, zoning, and repetition rather than filling every void", "patterns, objects, textures, and historical references layered while retaining legible scale and boundaries", "jewel tones, pastels, black-white, or regional color systems possible without fixed dark grounds and gold", "real ambient light differentiating material and hierarchy, with local accents rather than universal theatrical light", "textile, wallpaper, timber, lacquer, metal, ceramic, paper, and actual collected surfaces", "text must be accurate and legible for the medium and period; multiple typefaces alone do not make maximalism"] },
  "neo-futurism": { period: "约1960年代起，20世纪末以来在建筑设计中广泛使用", year: 2000, summary: "新未来主义是对20世纪后期至当代未来导向建筑和设计的宽泛称呼，常强调技术、动态空间和新材料，但不是成员明确的统一运动。连续曲面、轻质结构或可持续系统只是不同路线，不能把参数化白色壳体当作充分定义。", influencedBy: "历史未来主义、战后技术建筑、高技派、太空时代设计、数字建模与环境工程", influenced: "交通枢纽、文化地标、参数化建筑、科技产品与未来城市想象", related: ["futurism", "high-tech-architecture", "parametricism", "solarpunk"], sources: BATCH_15_SOURCES.neoFuturism, zh: ["按交通、文化、居住或基础设施功能组织动态路径和空间序列，不只追求流线轮廓", "壳体、肋骨、张拉结构、曲面或模块依项目技术选用，不固定白色空气动力造型", "材料本色、白灰、综合色表皮和功能色随项目变化", "真实日光与人工环境光显示结构、透明和使用状态，不加无依据未来辉光", "钢、混凝土、玻璃、复合材料、膜材、数字制造节点和可维护接缝", "建筑名、导视与技术标识必须准确；几何宽体字不是必要特征"], en: ["dynamic paths and spatial sequences organized by transport, culture, housing, or infrastructure programs rather than streamlined silhouette alone", "shells, ribs, tensile structures, curves, or modules selected through project technology without fixed white aerodynamic form", "inherent materials, white-gray, colored skins, and functional accents varying by project", "real daylight and artificial ambient light revealing structure, transparency, and use without unsupported futuristic glow", "steel, concrete, glass, composites, membranes, digitally fabricated nodes, and maintainable joints", "building names, wayfinding, and technical signs must be exact; wide geometric type is not required"] },
  "parametricism": { period: "约1990年代起；‘Parametricism’名称于2008年前后推广", year: 2008, summary: "参数化设计以变量和规则之间的关联生成、分析和调整形态，早于“参数主义”这一带有宣言性的风格名称。连续场、梯度和曲面是部分建筑实践的结果，并非参数方法的必然外观；规则、性能、制造和结构关系应可追踪。", influencedBy: "计算机辅助设计、样条与算法几何、系统论、数字制造、结构和环境模拟", influenced: "当代建筑、产品、景观、工程优化与大规模定制，也引发对形式主义和资源成本的批评", related: ["blobitecture", "deconstructivist-architecture", "neo-futurism", "high-tech-architecture"], sources: BATCH_15_SOURCES.parametricism, zh: ["以变量、场地、性能和构件关系组织系统，可连续也可离散，不强制无硬分区流线", "曲面、网格、孔洞和节点须显示可追踪规则，不以随机复杂度冒充参数逻辑", "综合色来自材料、性能分区或数据编码，不固定白银黑渐变", "真实光照揭示几何、遮阳和表皮性能；分析图可用清楚数据综合色", "复合板、金属、玻璃、木、混凝土、数字加工接缝和装配公差", "参数、图例和导视必须准确可读；不生成无意义数据标签"], en: ["systems organized through variables, site, performance, and component relations, whether continuous or discrete, without mandatory fluid zoning", "curves, grids, apertures, and nodes showing traceable rules rather than random complexity", "color derived from materials, performance zones, or data encoding without fixed white-silver-black gradients", "real light revealing geometry, shading, and envelope performance, with clear data color in analysis diagrams", "composite panels, metal, glass, timber, concrete, digitally cut joints, and assembly tolerances", "parameters, legends, and wayfinding must be accurate and legible; never generate meaningless data labels"] },
  "hollywood-regency": { period: "约1920年代末–1960年代，后续复兴延续", year: 1940, summary: "好莱坞摄政是与电影工业、明星住宅、摄影棚布景和装饰师文化相关的美国室内风格标签，融合古典、摄政、Art Deco、亚洲和现代元素以追求镜头中的戏剧效果。镜面、黑白、金色和丝绒常见但不是每个室内的固定清单。", influencedBy: "好莱坞电影布景、Regency与新古典复兴、Art Deco、Chinoiserie、现代家具和明星消费文化", influenced: "战后美国高端室内、酒店、时尚摄影和当代装饰主义复兴", related: ["art-deco", "maximalism", "mid-century-modern", "neoclassicism"], sources: BATCH_15_SOURCES.hollywoodRegency, zh: ["按房间功能建立清楚焦点、对称或舞台式陈设和摄影视线，不堆满镜面家具", "古典曲线、细腿家具、屏风和现代几何依设计师项目混合", "黑白、宝石色、粉彩、金属和漆色可变，不固定黑金综合色", "柔和室内环境光和局部灯具高光显示材质，保留真实镜面反射", "漆面、镜、黄铜、丝绒、玻璃、木和图案织物", "品牌、电影或人物信息必须准确；仅按需使用与室内年代相符的可读展示字"], en: ["clear room focal points, symmetrical or staged furnishing, and camera sightlines organized by use without filling the room with mirrors", "classical curves, slender furniture, screens, and modern geometry mixed according to designer and project", "black-white, jewel tones, pastels, metals, and lacquer color varying without a fixed black-gold palette", "soft ambient interior light and local fixture highlights revealing materials while preserving real mirror reflection", "lacquer, mirror, brass, velvet, glass, timber, and patterned textile", "brand, film, and personal information must be exact; use legible period-suitable display type only when requested"] },
  "miami-modernism": { period: "约1945–1970年代，南佛罗里达为核心", year: 1960, summary: "Miami Modern（MiMo）是战后南佛罗里达酒店、公寓和商业建筑对现代主义、汽车文化、旅游和热带气候的地区性改造。曲面雨棚、阳台、遮阳花格与活泼标识多样并存，粉彩Art Deco立面不能替代MiMo本身。", influencedBy: "国际现代主义、Streamline Moderne、战后汽车与旅游文化、空调技术、热带气候和度假商业", influenced: "南佛罗里达酒店住宅、度假建筑、热带现代设计及当代MiMo保护", related: ["streamline-moderne", "mid-century-modern", "tropical-modernism", "googie-architecture"], sources: BATCH_15_SOURCES.miamiModern, zh: ["按酒店、公寓、汽车入口、泳池和街道组织阳台、雨棚和标识，不复制南海滩Art Deco立面", "薄板、曲面、花格、外廊和装饰构件依具体项目与气候功能使用", "白、综合色灰泥、玻璃铝材和项目特定强调色，不固定粉薄荷珊瑚套色", "强热带日光形成遮阳投影，夜间只呈现真实招牌和室外灯光", "灰泥、混凝土、玻璃、铝、马赛克、水磨石和海滨风化", "酒店名、地址和历史招牌必须准确；不伪造复古旅游品牌"], en: ["balconies, canopies, signs, pools, and vehicular approaches organized by hotel or apartment program without copying South Beach Art Deco facades", "thin slabs, curves, screens, exterior corridors, and decorative elements used through the specific project and climate function", "white, colored stucco, glass, aluminum, and project-specific accents without a fixed pink-mint-coral set", "strong tropical daylight producing shading patterns, with only real signs and exterior lights at night", "stucco, concrete, glass, aluminum, mosaic, terrazzo, and coastal weathering", "hotel names, addresses, and historic signs must be exact; never fabricate retro tourism brands"] },
  "critical-regionalism": { period: "术语约1980年代形成并延续至今", year: 1983, summary: "批判地域主义是亚历山大·楚尼斯、莉亚娜·勒费夫尔和肯尼斯·弗兰姆普顿等人提出的建筑批评框架，主张以地形、气候、触觉和地方建造抵抗无差别全球化，同时避免怀旧民俗复制。它不是可凭石木土色识别的统一风格。", influencedBy: "现代主义、现象学、地方建造与气候知识、后殖民语境，以及对国际风格普遍主义的批评", influenced: "当代场所性建筑、气候响应、材料实践和全球南方现代主义研究", related: ["international-style-architecture", "tropical-modernism", "neo-vernacular-architecture", "organic-architecture"], sources: BATCH_15_SOURCES.criticalRegionalism, zh: ["从地形、朝向、步行体验和公共生活生成空间，不套用地方屋顶或纹样", "现代抽象体量通过墙、檐、庭院和开口回应气候与建造，不追求统一外观", "综合色来自地方材料、光和使用，不把土色当地域性的充分证据", "自然光、阴影、风和热环境是空间机制，而非表面滤镜", "地方石砖木土、混凝土、金属、手工与现代连接按项目整合", "地名、社群和材料术语必须准确；不以伪乡土标识制造地域感"], en: ["space generated from topography, orientation, bodily experience, and public life rather than applied local roofs or patterns", "modern abstract masses responding to climate and construction through walls, eaves, courts, and openings without one appearance", "color derived from local materials, light, and use, with earth tones insufficient as evidence of regionality", "daylight, shade, wind, and thermal conditions functioning spatially rather than as surface filters", "local stone, brick, timber, earth, concrete, metal, craft, and modern joints integrated by project", "place names, communities, and material terms must be exact; never fabricate vernacular signage to imply regional identity"] },
  "tropical-modernism": { period: "约1940年代–1970年代为核心，殖民与独立语境各异", year: 1960, summary: "热带现代主义将现代建筑的结构与规划用于炎热湿润地区，通过遮阳、通风、雨水和室内外过渡回应气候；它同时牵涉殖民机构、独立国家和本地建筑师的复杂历史。花格、架空和深檐重要，但不能抹去国家、作者和政治背景。", influencedBy: "现代主义、殖民热带建筑研究、本地建造与气候知识、公共机构建设及独立后的国家项目", influenced: "非洲、南亚、东南亚与加勒比现代建筑、气候设计和当代低能耗建筑", related: ["international-style-architecture", "critical-regionalism", "miami-modernism", "neo-vernacular-architecture"], sources: BATCH_15_SOURCES.tropicalModernism, zh: ["按风向、雨季、遮阳、公共流线和室内外过渡组织建筑，而非附加棕榈植物", "架空、深檐、百叶、花格、庭院和薄屋顶依据具体气候与项目选用", "混凝土、砖、木、灰泥与地方材料本色为主，综合色不等于热带高饱和", "强日光经遮阳构件过滤，保留真实风雨、阴影与室内亮度", "混凝土、砖花格、木、金属、玻璃、地方工艺和气候老化", "建筑师、国家、机构及殖民或独立语境必须准确；不泛化为无地点度假风"], en: ["buildings organized by wind, monsoon rain, shade, public circulation, and interior-exterior transition rather than added palms", "raised volumes, deep eaves, louvers, screens, courts, and thin roofs selected for the specific climate and project", "concrete, brick, timber, stucco, and local material colors without equating tropicality with saturation", "strong daylight filtered through shading while retaining real rain, shadow, and interior brightness", "concrete, perforated brick, timber, metal, glass, local craft, and climate weathering", "architect, country, institution, and colonial or independence context must be exact; never generalize it into placeless resort style"] },
  "desert-modernism": { period: "约1940年代–1970年代，美国西南部尤具代表性", year: 1960, summary: "沙漠现代主义常指美国西南部、尤其棕榈泉一带的战后现代建筑，以场地视野、遮阳、室内外生活和轻型建造回应干旱环境。它是地区性历史标签，不等于全球所有沙漠建筑，也不能只靠玻璃盒、棕榈和砂色综合色识别。", influencedBy: "中世纪现代建筑、好莱坞与度假文化、汽车生活、钢木结构、沙漠气候和山地景观", influenced: "加州住宅、度假建筑、室内外生活方式及棕榈泉现代主义保护", related: ["mid-century-modern", "organic-architecture", "miami-modernism", "critical-regionalism"], sources: BATCH_15_SOURCES.desertModernism, zh: ["从山景、朝向、泳池或庭院和汽车到达组织低矮空间，不把空旷沙漠当装饰背景", "薄屋顶、深檐、玻璃面、石墙和模块结构按具体项目与热环境使用", "石、木、钢、玻璃和灰泥本色随建筑变化，不固定沙色暖白黑绿", "强日光、深檐阴影和室内外亮度差须符合真实朝向与气候", "地方石、木、钢、玻璃、混凝土砌块、灰泥和干旱风化", "建筑名、地址和设计师必须准确；不添加无依据的度假村品牌"], en: ["low spaces organized by mountain views, orientation, pool or court, and automobile arrival rather than decorative empty desert", "thin roofs, deep eaves, glazing, stone walls, and modular structures used through the project and thermal conditions", "stone, timber, steel, glass, and stucco colors varying by building without a fixed sand-warm-white-black-green set", "strong sun, deep-eave shadow, and interior-exterior contrast matching real orientation and climate", "local stone, timber, steel, glass, concrete block, stucco, and arid weathering", "building names, addresses, and designers must be exact; never add unsupported resort brands"] },
  "blobitecture": { period: "约1990年代起；‘blob architecture’标签在1990年代传播", year: 2000, summary: "团块建筑是对数字建模推动的连续、软性和拓扑形体的非正式标签，常带有批评或戏称意味，并非统一运动。曲面可能来自充气、壳体、网格或分片建造；圆润外观本身不足以证明结构、空间和制造具有连续逻辑。", influencedBy: "数字样条与动画软件、拓扑研究、生物形态设计、复合材料和计算制造", influenced: "21世纪地标建筑、参数化表皮、数字制造与产品设计中的连续形体", related: ["parametricism", "deconstructivist-architecture", "biomorphic", "neo-futurism"], sources: BATCH_15_SOURCES.blobitecture, zh: ["从场地、入口、内部空间和结构组织单体或相连体量，不把任意圆角建筑称为团块", "膨胀曲面、滴状轮廓、壳体或网格必须对应具体几何与建造方法", "综合色来自表皮、玻璃、金属、混凝土或膜材，不固定白银半透明", "真实光照显示曲率、接缝和内部深度，连续高光须来自实际表面", "混凝土壳、钢网格、玻璃、复合板、膜材、分片和数字制造接点", "建筑名和导视必须准确；不以圆润字体重复表面造型"], en: ["single or connected masses organized through site, entry, interior space, and structure without calling every rounded building a blob", "inflated curves, droplet contours, shells, or meshes corresponding to specific geometry and construction", "color derived from skin, glass, metal, concrete, or membrane without fixed white-silver translucency", "real light revealing curvature, seams, and interior depth, with continuous highlights produced by actual surfaces", "concrete shells, steel meshes, glass, composite panels, membranes, segmentation, and digitally fabricated joints", "building names and wayfinding must be exact; rounded lettering need not mimic the envelope"] },
  "romanesque-revival-architecture": { period: "约19世纪中期–20世纪初，地域分支不同", year: 1880, summary: "新罗马式建筑是19世纪对11至12世纪罗马式建筑的多种复兴，涵盖教堂、公共建筑、校园和北美Richardsonian Romanesque等分支。半圆拱和厚重石作常见，但对称、堡垒感和粗琢石并非所有地区与用途的统一规则。", influencedBy: "中世纪罗马式遗存、浪漫主义与民族建筑研究、教会复兴、19世纪材料和工程", influenced: "欧美教堂、大学与公共建筑、Richardsonian Romanesque及后续重型石作传统", related: ["romanesque-art", "gothic-revival-architecture", "chicago-school", "arts-crafts"], sources: BATCH_15_SOURCES.romanesqueRevival, zh: ["按教堂、校园或公共功能组织塔、拱廊、入口和体量，不固定对称堡垒轮廓", "半圆拱、厚墙、粗短柱和雕刻按具体地区与分支使用", "石、砖、瓦、木和室内综合色来自材料与项目，不固定暖褐砖红", "真实日光显示开口深度和砌体重量，室内保留窗洞造成的明暗关系", "粗细不同的石砌、砖、木屋架、瓦、金属和雕刻接点", "题铭、宗教文字和建筑名称必须准确；不混用原生罗马式与19世纪复兴信息"], en: ["towers, arcades, entries, and masses organized by church, campus, or civic program without a fixed symmetrical fortress silhouette", "round arches, thick walls, robust columns, and carving used according to the specific region and branch", "stone, brick, tile, timber, and interior color derived from material and project without fixed warm brown and brick red", "real daylight revealing opening depth and masonry weight, with interiors retaining contrast caused by window openings", "masonry of varied finish, brick, timber roofs, tile, metal, and carved junctions", "inscriptions, religious text, and building names must be exact; never mix original Romanesque and nineteenth-century revival information"] },
  "neo-vernacular-architecture": { period: "20世纪后期至今，地区定义差异显著", year: 1990, summary: "新乡土建筑泛指当代建筑对地方空间、材料、气候和工艺的再解释，术语边界并不稳定，也不等同于新古典主义。可识别屋顶或院落只是部分路线；关键是说明谁的乡土传统、如何转译，以及现代结构和社区需求如何介入。", influencedBy: "地方民居与工艺、气候知识、后现代地方主义、社区建筑、现代工程与遗产讨论", influenced: "当代住宅、乡村公共建筑、文化旅游、低碳材料实践及对地方身份的争论", related: ["critical-regionalism", "tropical-modernism", "organic-architecture", "arts-crafts"], sources: BATCH_15_SOURCES.neoVernacular, zh: ["从具体地区的院落、屋顶、街巷、家庭或公共活动生成空间，不拼贴泛乡村符号", "坡顶、厚墙、木架、砖拱或地方构件须对应真实传统与现代功能", "土砖木瓦、石、混凝土和现代材料本色依地区变化，不统一米色", "自然光、通风、雨雪和檐下阴影符合当地气候，不用怀旧暖光滤镜", "夯土、地方砖瓦、石木、灰泥、再生材料和可辨现代加固节点", "地区、社群、工艺与建筑名称必须准确；不发明民俗图案和地方文字"], en: ["space generated from the courts, roofs, lanes, household, or public activities of a specific region without generic rural symbols", "pitched roofs, thick walls, timber frames, brick vaults, or local elements corresponding to real tradition and modern program", "earth, brick, timber, tile, stone, concrete, and modern materials varying by region without uniform beige", "daylight, ventilation, rain or snow, and eave shade matching local climate without nostalgic warm filters", "rammed earth, local brick and tile, stone, timber, plaster, reused material, and legible modern reinforcement", "regions, communities, crafts, and building names must be exact; never invent folk patterns or local writing"] },
  "corporate-memphis": { period: "约2010年代中后期–2020年代，非正式设计标签", year: 2018, summary: "Corporate Memphis是对科技公司和平台在2010年代后期广泛采用的一类模块化矢量人物插画的批评性昵称，与1980年代Memphis设计集团没有直接组织连续性。夸张比例、无面孔和柔和综合色便于品牌复用，也因同质化、去个性与掩饰平台权力而受批评。", influencedBy: "扁平设计、矢量图库、产品插画系统、现代主义几何和对Memphis综合色形状的松散借用", influenced: "SaaS品牌、 onboarding与空状态插画，也推动品牌转向更具地域、质感和人物差异的反应", related: ["flat-design", "memphis", "minimalism", "postmodernism"], sources: BATCH_15_SOURCES.corporateMemphis, zh: ["围绕产品任务组织人物、界面和几何模块，保留清楚信息焦点而非装饰散点", "夸张肢体、简化脸部和圆润形状是常见惯例，但人物身份与无障碍信息不能被抹除", "综合色来自品牌系统，可柔和或高对比，不固定蓝珊瑚芥末黄", "平面综合色和有限遮叠为主；轻阴影仅服务层级与可读性", "矢量面、统一描边或无描边、可复用组件和数字输出边缘", "界面文字和品牌名必须准确可读；不生成伪按钮、乱码或误导性控件"], en: ["people, interface elements, and geometric modules organized around a product task with a clear information focus rather than decorative scatter", "exaggerated limbs, simplified faces, and rounded shapes as common conventions without erasing identity or accessibility information", "color derived from the brand system, whether soft or high contrast, without a fixed blue-coral-mustard set", "flat color and limited overlap, with slight shadow only for hierarchy and legibility", "vector planes, consistent or absent outlines, reusable components, and crisp digital-output edges", "interface text and brand names must be exact and legible; never generate fake buttons, gibberish, or misleading controls"] },
  "cyberpunk": { period: "术语兴起于1980年代，相关文学与视觉先例更早并延续至今", year: 1984, summary: "赛博朋克首先是20世纪80年代形成的科幻文学类型，围绕网络、企业权力、身体改造、监控和社会边缘展开；电影、动画、漫画和游戏随后形成多样视觉传统。“高科技、低生活”是有效概括，但霓虹雨夜亚洲招牌只是部分影视惯例，不能替代社会主题。", influencedBy: "新浪潮科幻、黑色电影、朋克、控制论、城市化、冷战企业文化，以及对东京和香港等城市图像的选择性挪用", influenced: "科幻电影、动画、漫画、游戏、电子音乐与关于数字资本和身体政治的视觉讨论", related: ["film-noir", "glitch-art", "synthwave", "biopunk"], sources: BATCH_15_SOURCES.cyberpunk, zh: ["从人物、权力系统、基础设施和界面关系组织空间，可拥挤也可冷清，不强制巨型霓虹都市", "机械改造、线缆、终端和建筑层叠须服务叙事，不堆砌科技零件", "综合色可低调、荧光、工业灰或日光化；青洋红不是必要配色", "黑色电影式低调光、屏幕光、工业日光或过曝均可按作品设定使用", "金属、玻璃、湿地面、塑料、屏幕、旧基础设施和数字噪声依场景选择", "多语种标识和代码必须准确或明确虚构；不以随机亚洲文字制造异域未来"], en: ["space organized through relations among people, power systems, infrastructure, and interfaces, whether crowded or sparse, without mandatory neon megacity", "augmentation, cables, terminals, and layered buildings serving narrative rather than piled technology parts", "color may be low-key, fluorescent, industrial gray, or daylight-based; cyan-magenta is not required", "film-noir low key, screen light, industrial daylight, or clipping selected by the specific work", "metal, glass, wet paving, plastic, screens, aging infrastructure, and digital noise chosen by scene", "multilingual signs and code must be accurate or explicitly fictional; never use random Asian writing to manufacture exotic futurity"] },
  "steampunk": { period: "术语出现于1987年；常回想19世纪蒸汽时代的另类历史", year: 1987, summary: "蒸汽朋克是20世纪末形成的科幻类型与亚文化，以19世纪工业、帝国和维多利亚想象重构另类技术史。蒸汽机械和手工材料重要，但齿轮、护目镜、黄铜与褐色并非充分定义；殖民、阶级和技术幻想的历史语境也不可省略。", influencedBy: "凡尔纳、威尔斯等早期科幻、维多利亚工业和设计、冒险文学、蒸汽技术及20世纪另类历史小说", influenced: "文学、时尚、工艺、游戏、影视和主题娱乐中的复古技术世界", related: ["retrofuturism", "dieselpunk", "gothic-subculture", "arts-crafts"], sources: BATCH_15_SOURCES.steampunk, zh: ["按交通、工坊、城市或角色叙事组织机械系统，不在任何主体表面粘贴齿轮", "锅炉、阀门、连杆、仪表和铆接须具可读功能或明确幻想规则", "黄铜、铜、铁、木、皮革与综合色织物随世界设定变化，不固定褐金黑", "煤气、日光、炉火或电弧光按技术设定使用，保留真实金属反射和烟尘", "钢铁、铜合金、木、皮革、玻璃、织物、油污、铆接和手工加工", "仪表、专名和时代文字必须准确或一致虚构；不伪造历史品牌和殖民符号"], en: ["mechanical systems organized through transport, workshop, city, or character narrative without pasting gears onto every subject", "boilers, valves, linkages, gauges, and riveting carrying legible function or explicit fictional rules", "brass, copper, iron, timber, leather, and colored textiles varying by world rather than fixed brown-gold-black", "gaslight, daylight, fire, or arc light selected by the technology while retaining real metal reflection and soot", "iron and steel, copper alloys, timber, leather, glass, textile, oil, rivets, and hand machining", "instruments, proper names, and period text must be accurate or consistently fictional; never fabricate historic brands or colonial insignia"] },
  "solarpunk": { period: "约2000年代末至今，2010年代形成更明确社群", year: 2015, summary: "太阳朋克是围绕气候正义、可再生能源、生态修复和互助社会的推想类型与创作社群，不是单纯“绿色版赛博朋克”。它既可呈现可实现的低技术与社区维护，也可讨论冲突和转型；植物覆盖白色未来城市只是其中一种图像。", influencedBy: "生态科幻、气候行动、可持续设计、Arts and Crafts、去中心化技术、环境正义和原住民未来思想", influenced: "小说、插画、游戏、社区实践、气候传播和对希望型未来叙事的讨论", related: ["solarpunk", "neo-futurism", "organic-architecture", "critical-regionalism"].filter((id, index, list) => id !== "solarpunk" && list.indexOf(id) === index), sources: BATCH_15_SOURCES.solarpunk, zh: ["从能源、食物、水、交通、修复和公共生活的关系组织社区，不只让高楼长满植物", "生物系统、可维修设施、地方建筑和适度高技术保持功能可读", "综合色来自生态区、材料和文化，可明亮也可克制，不固定鲜绿陶土天蓝", "真实日光、遮阳和能源条件塑造环境，不用普遍暖光乌托邦滤镜", "木土石、再生材料、太阳能与风能设施、织物、维修痕迹和生长变化", "能源说明、社群语言和公共标识必须准确；不挪用受限原住民符号作为生态装饰"], en: ["communities organized through energy, food, water, mobility, repair, and public life rather than towers merely covered in plants", "biological systems, maintainable infrastructure, local building, and appropriate high technology remaining functionally legible", "color derived from ecology, material, and culture, whether bright or restrained, without fixed green-terracotta-sky blue", "real daylight, shade, and energy conditions shaping the environment without a universal warm utopian filter", "timber, earth, stone, reused materials, solar and wind equipment, textile, repair traces, and growth", "energy information, community languages, and public signs must be accurate; never appropriate restricted Indigenous signs as ecological decoration"] },
  "y2k": { period: "约1997–2005年；2010年代末后出现复兴", year: 2000, summary: "Y2K视觉指千禧年前后由互联网、消费电子、锐舞、时尚和早期CG共同形成的多种未来想象，也包含对2000年计算机问题的焦虑。铬、凝胶、液态字体和冰蓝界面是部分路线；泡泡糖粉色、网络像素和极简科技同样存在，不能合成一种统一复古滤镜。", influencedBy: "1990年代后期互联网、电子消费品、锐舞与流行音乐、科幻、杂志设计和早期三维软件", influenced: "2010年代末以来的时尚和音乐复兴、网络设计、生成式三维和品牌怀旧", related: ["vaporwave", "new-aesthetic", "frutiger-metro", "atompunk"], sources: BATCH_15_SOURCES.y2k, zh: ["界面、杂志、广告、时尚或三维对象按具体媒介组织悬浮、轨道、网格或拼贴", "液态圆形、锐利科技线、像素和早期CG体块按来源年代选择，不全部叠加", "冰蓝银绿、粉彩、黑白或高饱和流行综合色均可，依具体子路线", "影棚高光、屏幕光、闪光灯或早期CG照明按媒介使用，不统一边缘辉光", "铬、透明塑料、凝胶、网布、像素、低多边形、印刷光泽和压缩痕迹", "品牌、网址、微型标签和界面文字必须准确可读；不制造伪系统按钮和乱码"], en: ["interfaces, magazines, ads, fashion, or 3D objects using floating, orbital, gridded, or collaged organization according to medium", "liquid rounds, sharp technical lines, pixels, and early-CGI solids selected by source date rather than all combined", "icy blue-silver-green, pastel, black-white, or saturated pop color depending on the specific branch", "studio highlights, screen light, flash, or early-CGI lighting selected by medium without universal edge glow", "chrome, transparent plastic, gel, mesh, pixels, low polygon forms, print gloss, and compression artifacts", "brands, URLs, micro-labels, and interface text must be accurate and legible; never fabricate system buttons or gibberish"] },
  "atompunk": { period: "20世纪末至今的复古未来类型；主要引用约1945–1965年", year: 2005, summary: "原子朋克是后来的复古未来类型标签，借用二战后至1960年代中期的核能、太空竞赛、民防和消费设计想象。它既包含技术乐观，也应容纳核焦虑和冷战政治；原子轨道、回旋镖、铬和粉彩只是历史图像资源，不是统一世界设定。", influencedBy: "原子时代设计、冷战科幻、Googie、Streamline Moderne、航天宣传、民防与核武器文化", influenced: "游戏、动画、插画和影视中的中世纪复古未来世界观", related: ["atomic-age", "googie-architecture", "retrofuturism", "dieselpunk"], sources: BATCH_15_SOURCES.atompunk, zh: ["按家庭、实验室、民防、交通或太空叙事组织场景，不拼贴所有原子时代图标", "圆顶、胶囊、回旋镖、轨道和机械装置依据具体年代参照与功能使用", "综合色可来自1950年代商品、军用设施、宣传印刷或黑白档案，不固定樱桃红青绿奶黄", "影棚日光、荧光灯、电视光或警报光按叙事使用，不一律乐观明亮", "珐琅金属、铬、玻璃、早期塑料、印刷纸、混凝土和使用磨损", "警告、仪表、品牌和政治文字必须准确或一致虚构；不美化真实核灾难"], en: ["scenes organized through domestic, laboratory, civil-defense, transport, or space narratives without collaging every atomic-age icon", "domes, capsules, boomerangs, orbits, and machinery used through a specific dated reference and function", "color derived from 1950s goods, military facilities, printed propaganda, or monochrome archives without fixed cherry-teal-cream", "studio daylight, fluorescent light, television glow, or warning light selected by narrative rather than universal optimism", "enamel metal, chrome, glass, early plastic, printed paper, concrete, and use wear", "warnings, instruments, brands, and political text must be accurate or consistently fictional; never glamorize real nuclear disasters"] },
  "dieselpunk": { period: "20世纪末至今的复古未来类型；主要引用约1920–1950年代", year: 2001, summary: "柴油朋克是以两次世界大战之间及二战年代的柴油工业、Art Deco、航空、宣传和大众文化构造另类历史的后设类型。重型机械、铆接钢板和烟尘常见，但军绿色和战争崇拜不是必要条件；法西斯主义、殖民与战争图像需被准确而非装饰性地处理。", influencedBy: "Art Deco、Streamline Moderne、柴油交通、航空与城市工业、纸浆科幻、黑色电影和战争宣传", influenced: "游戏、漫画、影视和模型中的重工业复古未来及另类历史", related: ["art-deco", "streamline-moderne", "steampunk", "atompunk"], sources: BATCH_15_SOURCES.dieselpunk, zh: ["按城市、交通、工厂、角色或冲突叙事组织重型系统，不默认战争宣传构图", "发动机、装甲、散热格、铆接外壳和流线体须具功能或一致幻想逻辑", "钢灰、煤黑、军用色、Art Deco综合色和民用广告综合色均依设定，不固定军绿暗红", "工业日光、探照灯、黑色电影低调光或广告棚光按场景使用", "钢、铝、橡胶、玻璃、油污、烟尘、磨损漆面、纸张和铆接", "徽章、军服、语言和政治标志必须历史准确且有批判语境；不使用虚构仇恨符号作装饰"], en: ["heavy systems organized by city, transport, factory, character, or conflict narrative without default propaganda composition", "engines, armor, cooling grilles, riveted shells, and streamlining carrying function or consistent fictional logic", "steel gray, coal black, military colors, Art Deco color, and civilian advertising color varying by setting without fixed green-red", "industrial daylight, searchlights, film-noir low key, or advertising studio light selected by scene", "steel, aluminum, rubber, glass, oil, soot, worn paint, paper, and riveting", "insignia, uniforms, languages, and political signs must be historically accurate and critically contextualized; never use invented hate symbols decoratively"] }
};

