const batch16Genes = (id) => {
  const style = STYLE_DATA.find((candidate) => candidate.id === id);
  if (!style || style.visualGenes.length !== 6) throw new Error(`${id}: batch 16 requires six existing genes`);
  return { zh: style.visualGenes.map((gene) => gene.zh), en: style.visualGenes.map((gene) => gene.en) };
};

const BATCH_16_REVIEWS = {
  "barbizon-school": { ...batch16Genes("barbizon-school"), period: "约1830年代–1870年代", year: 1850, summary: "巴比松画派是19世纪中叶在枫丹白露森林周边工作的一批法国风景画家的宽泛称呼，成员和风格边界并不固定。直接写生、乡村劳动和低调土色重要，但许多作品仍在画室完成；它既非统一宣言团体，也不等同后来印象派的户外即时综合色。", influencedBy: "17世纪荷兰风景、英国风景画、浪漫主义自然观、学院风景传统及法国乡村社会变化", influenced: "法国现实主义风景、印象主义的户外实践、欧洲与美国的自然主义画家群体", related: ["realism", "romanticism", "impressionism", "naturalism"], sources: BATCH_16_SOURCES.barbizon },
  "hudson-river-school": { ...batch16Genes("hudson-river-school"), period: "约1825–1870年代，美国", year: 1855, summary: "哈德逊河画派是后世对19世纪美国风景画家网络的称呼，题材从哈德逊河谷扩展到新英格兰、美国西部与南美。精细全景和崇高光线常与国家扩张、旅游和保护意识并存，也必须说明原住民族土地被写成‘荒野’的殖民视角。", influencedBy: "欧洲浪漫主义风景、如画与崇高理论、美国地理考察、旅游和定居扩张", influenced: "美国风景画、Luminism、国家公园视觉与环境保护图像，同时受到去殖民批评", related: ["romanticism", "barbizon-school", "luminism", "realism"].filter((id) => STYLE_DATA.some((style) => style.id === id)), sources: BATCH_16_SOURCES.hudsonRiver },
  "orientalist-painting": { ...batch16Genes("orientalist-painting"), period: "约18世纪末–20世纪初，19世纪最盛", year: 1870, summary: "东方主义绘画是欧洲艺术家对北非、西亚及所谓‘东方’的再现类别，而非当地艺术风格。旅行观察、学院想象、殖民权力和性别凝视交织其中；精密织物、戏剧光和异域场景必须被标为欧洲建构，不能当作中立地域记录。", influencedBy: "欧洲殖民扩张、旅行与考古、学院历史画、浪漫主义、摄影及对伊斯兰世界的想象", influenced: "欧洲大众对北非西亚的刻板图像、殖民展览与旅游传播，并成为后殖民视觉批评的重要对象", related: ["romanticism", "academic-art", "realism", "postcolonial-art"].filter((id) => STYLE_DATA.some((style) => style.id === id)), sources: BATCH_16_SOURCES.orientalism, zh: ["按具体作品区分旅行观察、历史想象、室内或风景构图，不把殖民凝视当地域模板", "学院写实、装饰细节和人物姿态须说明作者与再现关系，避免类型化匿名人物", "综合色来自具体作品和欧洲画家选择，不设宝石色与土金色的‘东方’公式", "日光、室内光和戏剧光按作品处理，不把综合色反差声称为地区自然属性", "油画、纸本、摄影参照、织物与建筑细节作为欧洲再现媒介而非民族真实性证明", "地名、人物、阿拉伯文及其他语言必须准确；不得生成伪文字或殖民标签"], en: ["distinguish travel observation, historical fantasy, interiors, and landscapes by the specific work without turning the colonial gaze into a regional template", "academic realism, ornament, and posing contextualized through artist and representation without anonymous human types", "color derived from the work and European painter's choices rather than a jewel-and-earth Oriental formula", "sunlight, interior light, and theatrical light treated by work without claiming chromatic contrast as a regional natural property", "oil, works on paper, photographic reference, textiles, and architecture as European representational media rather than proof of ethnic authenticity", "place names, people, Arabic, and other languages must be exact; never generate pseudo-script or colonial labels"] },
  "pointillism": { ...batch16Genes("pointillism"), period: "约1886–1900年代，技术影响延续", year: 1890, summary: "点彩主义是以细小综合色点并置实现观看距离上光学混合的绘画技法，常与修拉、希涅克及新印象主义相关。它是Divisionism的一种较规则点触实践，而非二者完全同义；点的大小、密度和底色随艺术家变化。", influencedBy: "综合色科学与光学理论、印象主义、新印象主义及修拉的系统实验", influenced: "新印象主义、意大利分色主义、现代印刷与数字综合色采样的类比接受", related: ["impressionism", "post-impressionism", "divisionism", "fauvism"], sources: BATCH_16_SOURCES.pointillism },
  "divisionism": { ...batch16Genes("divisionism"), period: "约1880年代中期–1910年代，法国与意大利路径不同", year: 1900, summary: "分色主义指将综合色分离为点、短线或方向性笔触，使其在观看中混合的理论与方法；法国新印象主义和意大利Divisionismo并不相同。意大利艺术家常把分色笔触用于象征、社会和政治题材，因此不能仅写成更自由的点彩。", influencedBy: "19世纪综合色与光学理论、法国新印象主义、意大利社会象征主题及印象主义实验", influenced: "意大利未来主义的综合色与运动研究、象征主义及欧洲现代综合色绘画", related: ["pointillism", "post-impressionism", "symbolism", "futurism"], sources: BATCH_16_SOURCES.divisionism },
  "les-nabis": { ...batch16Genes("les-nabis"), period: "约1888–1900年，成员后续实践延长", year: 1895, summary: "纳比派是1888年前后在巴黎形成的松散艺术家团体，成员在绘画、版画、海报、屏风、壁画和舞台设计中强调画面平面、主观综合色与装饰整体。浅空间和硬边色面重要，但博纳尔、维亚尔、德尼等人的题材与笔触差异明显。", influencedBy: "高更与Pont-Aven综合主义、日本版画、象征主义、装饰艺术和戏剧出版网络", influenced: "20世纪装饰绘画、平面设计、现代室内综合色和野兽派前史", related: ["post-impressionism", "symbolism", "art-nouveau", "fauvism"], sources: BATCH_16_SOURCES.nabis },
  "secessionism": { ...batch16Genes("secessionism"), period: "约1890年代–1910年代，城市分支不同", year: 1900, summary: "‘分离派’是慕尼黑、维也纳、柏林等地艺术家脱离官方展览和学院体制的组织现象总称，不是一套统一装饰风格。各分支既展出自然主义、印象主义和象征主义，也发展建筑、设计与出版；几何边框和金色只适用于部分作品。", influencedBy: "官方沙龙与学院体制争议、国际展览、自然主义、印象主义、象征主义和艺术门类改革", influenced: "欧洲现代展览制度、维也纳现代主义、新艺术与多种先锋团体的组织模式", related: ["vienna-secession", "art-nouveau", "symbolism", "naturalism"], sources: BATCH_16_SOURCES.secession },
  "vienna-secession": { ...batch16Genes("vienna-secession"), period: "1897年成立；核心活动约至1910年代", year: 1902, summary: "维也纳分离派于1897年成立，是追求展览自主和国际现代艺术交流的组织，不能等同克里姆特金色时期或几何装饰风格。绘画、建筑、海报与展览设计差异广泛，1905年克里姆特集团退出后组织仍继续存在。", influencedBy: "维也纳学院体制争议、英国工艺美术、象征主义、国际新艺术与现代展览设计", influenced: "维也纳工坊、奥地利现代建筑与平面设计、欧洲总体艺术观念", related: ["secessionism", "art-nouveau", "wiener-werkstatte-graphics", "symbolism"], sources: BATCH_16_SOURCES.vienna },
  "orphism": { ...batch16Genes("orphism"), period: "约1912–1914年，影响延续至一战后", year: 1913, summary: "奥费主义是阿波利奈尔1912年前后用于德劳内夫妇、库普卡等综合色导向作品的术语，而非成员稳定的正式团体。综合色同时对比、光感和节奏推动立体主义走向抽象，但同心圆盘只是高识别个案，不能覆盖所有相关艺术家。", influencedBy: "立体主义、分色与同时对比综合色理论、现代城市和电光经验", influenced: "综合色抽象、同步主义、包豪斯综合色教学与欧洲几何抽象", related: ["cubism", "divisionism", "rayonism", "geometric-abstraction"], sources: BATCH_16_SOURCES.orphism },
  "purism": { ...batch16Genes("purism"), period: "约1918–1925年，后续影响延伸", year: 1922, summary: "纯粹主义由奥赞方和勒·柯布西耶在一战后法国提出，以标准化日用品、稳定比例和清楚综合色关系批评他们所理解的晚期立体主义装饰化。它包含绘画、杂志和建筑理论，不等于所有机械对象都被画成无痕白灰几何。", influencedBy: "立体主义、战后秩序诉求、工业标准化、古典比例和现代机械文化", influenced: "勒·柯布西耶建筑与出版、法国现代主义、精确主义及现代静物设计", related: ["cubism", "precisionism", "international-style-architecture", "art-deco"], sources: BATCH_16_SOURCES.purism },
  "rayonism": { ...batch16Genes("rayonism"), period: "约1911–1914年，俄罗斯先锋", year: 1913, summary: "辐射主义由拉里奥诺夫和冈察洛娃在1910年代初发展，以物体之间反射和交叉的‘光线’分解形体，并在宣言中走向非再现。它的射线并非物理光学记录，也不能把所有俄罗斯先锋斜线抽象都归为辐射主义。", influencedBy: "立体主义、未来主义、综合色分割、俄罗斯新原始主义和现代光学想象", influenced: "俄罗斯非客观绘画、未来主义舞台与更广泛的先锋抽象", related: ["cubism", "futurism", "orphism", "suprematism"], sources: BATCH_16_SOURCES.rayonism },
  "precisionism": { ...batch16Genes("precisionism"), period: "约1915年代后期–1940年代，美国", year: 1930, summary: "精确主义是后世对两次世界大战之间美国一批以清晰几何、锐利裁切和压低笔触描绘工业、城市与乡村建筑的艺术家所用名称。它没有正式组织或宣言，查尔斯·希勒、德穆斯、奥基夫等人的主题和抽象程度也不同。", influencedBy: "摄影、立体主义、纯粹主义、美国工业化、摩天楼和广告视觉", influenced: "美国现代绘画与摄影、工业图像、硬边和波普对商品建筑的再认识", related: ["purism", "cubism", "straight-photography", "art-deco"], sources: BATCH_16_SOURCES.precisionism },
  "der-blaue-reiter": { ...batch16Genes("der-blaue-reiter"), period: "1911–1914年，慕尼黑", year: 1912, summary: "蓝骑士是康定斯基、弗兰茨·马克等人围绕展览和1912年《蓝骑士年鉴》形成的短期网络，并非样式统一的画派。精神性、音乐类比和综合色自主性重要，但成员从具象综合色到抽象的路径差异很大。", influencedBy: "表现主义、野兽派、民间与儿童艺术、音乐、神智学，以及当时对非欧洲艺术的选择性接受", influenced: "抽象艺术、包豪斯、欧洲表现主义和现代综合色理论", related: ["expressionism", "die-bruecke", "fauvism", "abstract-expressionism"], sources: BATCH_16_SOURCES.blaueReiter },
  "die-bruecke": { ...batch16Genes("die-bruecke"), period: "1905–1913年，德累斯顿与柏林", year: 1910, summary: "桥社于1905年在德累斯顿成立，1911年前后转向柏林，1913年解散。成员通过绘画、木刻和共同工作追求直接表现，但城市、人体、风景和版画差异显著；酸性综合色、尖角人体和木刻粗线不能成为每件作品的固定配方。", influencedBy: "凡高、高更、蒙克、德国版画、Jugendstil，以及对非洲和大洋洲艺术的现代主义挪用", influenced: "德国表现主义、现代版画、新表现主义及20世纪反学院人物画", related: ["expressionism", "der-blaue-reiter", "fauvism", "neo-expressionism"], sources: BATCH_16_SOURCES.bruecke },
  "new-objectivity": { ...batch16Genes("new-objectivity"), period: "约1920年代–1933年，魏玛德国", year: 1925, summary: "新客观主义名称来自古斯塔夫·哈特劳布1925年展览，用于魏玛德国对表现主义作出反应的多种具象实践。尖锐社会讽刺与冷静古典化是两条常被区分的路线，因此疏离肖像、硬光和无痕表面不能概括全部艺术家。", influencedBy: "第一次世界大战、达达、表现主义反拨、摄影、社会政治危机和旧大师绘画", influenced: "20世纪具象绘画、社会批判图像、魔幻现实主义术语及现代摄影", related: ["expressionism", "dada", "magic-realism-painting", "social-realism"], sources: BATCH_16_SOURCES.newObjectivity },
  "metaphysical-painting": { ...batch16Genes("metaphysical-painting"), period: "约1910–1920年代初，意大利", year: 1915, summary: "形而上绘画由德·基里科、卡拉等人在一战前后发展，以空旷广场、雕像、人体模型和不合逻辑并置制造谜样静止。长阴影和拱廊很有辨识度，但室内静物与不同画家阶段同样重要，不能只生成一种黄昏城市。", influencedBy: "古典建筑与雕塑、象征主义、尼采思想、意大利城市空间和现代商品物件", influenced: "超现实主义、新客观主义部分路线和20世纪谜样具象绘画", related: ["symbolism", "surrealism", "new-objectivity", "magic-realism-painting"], sources: BATCH_16_SOURCES.metaphysical },
  "vorticism": { ...batch16Genes("vorticism"), period: "约1914–1919年，英国核心活动短暂", year: 1915, summary: "漩涡主义是温德姆·刘易斯等人围绕《BLAST》杂志形成的英国先锋团体，以机器时代的角状结构综合立体主义与未来主义。战争中断了活动，绘画、雕塑、文字和排版并不共享一种漩涡中心构图。", influencedBy: "立体主义、未来主义、英国工业都市、现代雕塑和先锋杂志文化", influenced: "英国现代主义、战争艺术、实验排版和后续几何机械图像", related: ["cubism", "futurism", "constructivism", "expressionism"], sources: BATCH_16_SOURCES.vorticism },
  "magic-realism-painting": { ...batch16Genes("magic-realism-painting"), period: "术语提出于1925年；视觉艺术用法主要关联1920–1940年代", year: 1925, summary: "视觉艺术中的‘魔幻现实主义’由弗朗茨·罗1925年提出，用于描述表现主义之后重新关注物体世界而又显得陌生的绘画，历史含义不同于后来拉丁美洲文学魔幻现实主义。它与新客观主义部分重叠，不能泛指任何写实画中的超自然事件。", influencedBy: "表现主义反拨、形而上绘画、旧大师技法、摄影般清晰度和魏玛时期具象转向", influenced: "新客观主义接受、20世纪谜样具象绘画，以及后来同名文学术语造成的跨媒介混用", related: ["new-objectivity", "metaphysical-painting", "surrealism", "realism"], sources: BATCH_16_SOURCES.magicRealism }
};

