const batch17Genes = (id) => {
  const style = STYLE_DATA.find((candidate) => candidate.id === id);
  if (!style || style.visualGenes.length !== 6) throw new Error(`${id}: batch 17 requires six existing genes`);
  return { zh: style.visualGenes.map((gene) => gene.zh), en: style.visualGenes.map((gene) => gene.en) };
};

const BATCH_17_REVIEWS = {
  "art-informel": { ...batch17Genes("art-informel"), period: "约1940年代中期–1960年代，欧洲", year: 1955, summary: "不定形艺术是评论家米歇尔·塔皮耶等人在战后用于欧洲多种非几何抽象的宽泛术语，强调手势、材料、偶发和非预设形体。它不是正式团体，也不等于塔希主义、物质绘画或所有欧洲抽象表现。", influencedBy: "超现实主义自动技法、战前抽象、战争创伤、存在主义及对学院和几何秩序的反拨", influenced: "塔希主义、物质绘画、欧洲抒情抽象和战后跨大西洋抽象讨论", related: ["tachisme", "matter-painting", "lyrical-abstraction", "abstract-expressionism"], sources: BATCH_17_SOURCES.informel },
  "lyrical-abstraction": { ...batch17Genes("lyrical-abstraction"), period: "1940年代后出现欧洲用法；1960年代末美国用法另有语境", year: 1960, summary: "抒情抽象是跨时期且语境不一的术语：战后法国用法常指与几何抽象相对的自由抽象，1960年代末美国同名展览则回应极简和形式主义。流动线条、透明色层和留白只是部分路线，不能写成一个连续国际运动。", influencedBy: "超现实主义自动技法、康定斯基、战后抽象、Art Informel，以及美国对极简和后绘画性抽象的反应", influenced: "欧洲和美国的自由抽象、综合色场与后续当代抽象绘画", related: ["art-informel", "tachisme", "abstract-expressionism", "post-painterly-abstraction"], sources: BATCH_17_SOURCES.lyrical },
  "tachisme": { ...batch17Genes("tachisme"), period: "约1940年代后期–1950年代，法国及欧洲", year: 1953, summary: "塔希主义名称来自法语tache（斑点），用于战后法国及欧洲以色斑、滴洒和自发笔触形成的抽象倾向。它通常被置于Art Informel之内，而非与不定形艺术并列的完整同义词；不同艺术家的材料厚度和空间感并不一致。", influencedBy: "超现实主义自动技法、战前抽象、书写性线条和战后对预设构图的反拨", influenced: "欧洲自由抽象、抒情抽象和战后手势绘画", related: ["art-informel", "lyrical-abstraction", "matter-painting", "abstract-expressionism"], sources: BATCH_17_SOURCES.tachisme },
  "matter-painting": { ...batch17Genes("matter-painting"), period: "约1940年代–1960年代，欧洲战后语境", year: 1955, summary: "物质绘画是战后欧洲将砂、灰泥、焦油、布和厚颜料纳入画面的材料性实践，常与Art Informel相交。核心是支持体、裂缝、孔洞和堆积的真实物质作用，而非任何厚涂绘画；塔皮埃斯、布里等人的方法也不可统一。", influencedBy: "拼贴与综合材料、达达、战争废墟经验、Art Informel和对传统画面平整性的反拨", influenced: "欧洲材料艺术、Arte Povera、装置和当代绘画对支持体与损耗的研究", related: ["art-informel", "tachisme", "arte-povera", "supports-surfaces"], sources: BATCH_17_SOURCES.matter },
  "spatialism": { ...batch17Genes("spatialism"), period: "1947年宣言后–1960年代，意大利", year: 1958, summary: "空间主义由卢齐奥·丰塔纳等人在1947年后的一系列宣言中推动，主张将真实空间、时间、运动和新技术带入艺术。切割和穿孔画布是丰塔纳的重要实践，但霓虹、环境和陶瓷实验说明运动不等于单色画布上的一道切口。", influencedBy: "意大利未来主义、现代科学与航空航天、战后材料实验、雕塑和环境艺术", influenced: "极简、观念艺术、环境与装置艺术，以及对绘画支持体的后续研究", related: ["futurism", "zero-group", "minimalism", "light-and-space"], sources: BATCH_17_SOURCES.spatialism },
  "zero-group": { ...batch17Genes("zero-group"), period: "1957–1966年；国际ZERO网络范围更广", year: 1962, summary: "ZERO由海因茨·马克、奥托·皮内和君特·于克尔1957年在杜塞尔多夫发起，并迅速连接欧洲多地艺术家。单色、光、反射、运动、火和重复是不同实践，不应把银白点阵当作统一样式；‘归零’也与战后重启语境相关。", influencedBy: "战后重建、技术材料、单色绘画、动力艺术、空间主义和对主观手势的反拨", influenced: "光与空间、动力艺术、极简、环境和媒介装置", related: ["spatialism", "kinetic-art", "light-and-space", "minimalism"], sources: BATCH_17_SOURCES.zero },
  "nouveau-realisme": { ...batch17Genes("nouveau-realisme"), period: "1960–1970年，法国及欧洲网络", year: 1962, summary: "新现实主义由评论家皮埃尔·雷斯塔尼和艺术家于1960年共同命名，主张‘重新感知现实’，通过现成消费物、压缩、积聚、撕裂海报和行动处理城市生活。它既不是19世纪现实主义，也不能被任何废料拼贴泛化。", influencedBy: "达达现成品、城市消费与广告、工业废物、行为和对抽象绘画的反应", influenced: "欧洲物件艺术、行为与装置、消费文化批评，并与波普艺术形成跨大西洋对话", related: ["dada", "pop-art", "arte-povera", "post-minimalism"], sources: BATCH_17_SOURCES.nouveau },
  "arte-povera": { ...batch17Genes("arte-povera"), period: "术语形成于1967年；核心活动约1960年代末–1970年代", year: 1970, summary: "贫穷艺术由热尔马诺·切兰特1967年命名，涵盖意大利艺术家以日常、工业、有机和能量过程质疑商品、制度与技术现代化的不同实践。‘贫穷’指策略而非只用天然廉价材料，作品也可使用钢、霓虹和复杂装置。", influencedBy: "意大利战后工业化、政治抗议、达达、Fontana、物质与行为艺术及剧场理论", influenced: "装置、过程、生态和观念艺术，以及意大利当代艺术国际化", related: ["nouveau-realisme", "matter-painting", "post-minimalism", "italian-radical-design"], sources: BATCH_17_SOURCES.povera },
  "supports-surfaces": { ...batch17Genes("supports-surfaces"), period: "约1966–1974年，法国南部网络", year: 1970, summary: "Supports/Surfaces是1960年代末法国艺术家围绕画布、木框、染色和展示方式展开的松散网络，名称强调‘支持体/表面’的拆解。成员政治立场与形式不同，未绷画布和重复印染只是部分实践，不应写成统一反绘画风格。", influencedBy: "马蒂斯与综合色传统、美国综合色场、结构主义、1968年前后政治和对画架绘画制度的批评", influenced: "法国当代绘画、解构支持体的装置与后续过程性抽象", related: ["matter-painting", "post-painterly-abstraction", "post-minimalism", "concrete-art"], sources: BATCH_17_SOURCES.supports },
  "post-painterly-abstraction": { ...batch17Genes("post-painterly-abstraction"), period: "术语由1964年展览推广；主要关联1950年代末–1960年代", year: 1964, summary: "‘后绘画性抽象’是克莱门特·格林伯格为1964年巡展提出的集合名称，涵盖综合色场、硬边和压低手势的多种美国及加拿大绘画。它不是成员自称的统一运动，也不能只以薄染画布定义。", influencedBy: "抽象表现主义、综合色场绘画、现代主义形式批评、丙烯材料和对厚涂手势的反应", influenced: "硬边绘画、综合色场、极简视觉和后续抽象绘画", related: ["abstract-expressionism", "color-field", "hard-edge-painting", "washington-color-school"], sources: BATCH_17_SOURCES.postPainterly },
  "post-minimalism": { ...batch17Genes("post-minimalism"), period: "约1966年后–1970年代，影响延续", year: 1970, summary: "后极简主义是评论与展览使用的宽泛术语，涵盖过程艺术、柔性材料、身体、偶发和场地实践对极简主义的扩展与反应。毡的垂坠、乳胶卷曲只是个案；部分作品仍保留模块和工业材料。", influencedBy: "极简主义、过程艺术、女性主义、身体与舞蹈、工业和柔性材料实验", influenced: "过程、装置、身体与生态艺术，以及雕塑对重力和时间的研究", related: ["minimalism", "arte-povera", "supports-surfaces", "nouveau-realisme"], sources: BATCH_17_SOURCES.postMinimal },
  "washington-color-school": { ...batch17Genes("washington-color-school"), period: "约1950年代末–1970年代，华盛顿特区", year: 1965, summary: "华盛顿综合色画派是对莫里斯·路易斯、肯尼斯·诺兰、吉恩·戴维斯等华盛顿特区艺术家的地区性称呼，成员并非样式一致的正式团体。浸染、条带、靶形和综合色帷幕各有不同制作机制，不能统一为透明软边综合色场。", influencedBy: "抽象表现主义、综合色场、海伦·弗兰肯瑟勒的浸染、丙烯颜料和华盛顿艺术网络", influenced: "后绘画性抽象、硬边、综合色场及美国地区现代主义研究", related: ["color-field", "post-painterly-abstraction", "hard-edge-painting", "abstract-expressionism"], sources: BATCH_17_SOURCES.washington },
  "geometric-abstraction": { ...batch17Genes("geometric-abstraction"), period: "20世纪初至今，跨地区与媒介", year: 1930, summary: "几何抽象是以线、平面、网格、曲线和比例关系组织非具象作品的上位类别，涵盖不同理论、综合色、空间和制作方式。它比具体艺术范围更广，也不必完全排除象征、直觉、手工边缘或三维空间。", influencedBy: "立体主义、俄国先锋、De Stijl、包豪斯、数学与非再现艺术理论", influenced: "具体艺术、硬边、Op Art、极简、建筑设计和数字生成艺术", related: ["suprematism", "de-stijl", "concrete-art", "hard-edge-painting"], sources: BATCH_17_SOURCES.geometric },
  "concrete-art": { ...batch17Genes("concrete-art"), period: "1930年宣言后至今，国际传播", year: 1940, summary: "具体艺术由Theo van Doesburg等人在1930年宣言中主张作品应由综合色、线和表面自身构成，而非抽象自然对象。其理性、非再现和预先构成原则影响广泛，但不同国家并不都坚持数学秩序或无手工痕迹。", influencedBy: "De Stijl、构成主义、几何抽象、现代设计和非再现理论", influenced: "瑞士、阿根廷和巴西具体艺术、系统与几何抽象、现代视觉设计", related: ["geometric-abstraction", "de-stijl", "brazilian-concretism", "neo-concretism"], sources: BATCH_17_SOURCES.concrete },
  "brazilian-concretism": { ...batch17Genes("brazilian-concretism"), period: "约1950年代–1960年代初，圣保罗与里约路径不同", year: 1956, summary: "巴西具体主义在1950年代围绕圣保罗Grupo Ruptura、里约Grupo Frente和1956年全国具体艺术展发展，将国际具体艺术与巴西工业化、设计和诗歌相连。两地艺术家并非完全一致，理性网格和工业表面不能覆盖全部实践。", influencedBy: "国际具体艺术、Max Bill、De Stijl、构成主义、巴西工业化、现代设计与具体诗", influenced: "巴西新具体主义、视觉诗、现代设计和拉丁美洲几何抽象", related: ["concrete-art", "neo-concretism", "geometric-abstraction", "tropicalia"], sources: BATCH_17_SOURCES.brazilConcrete },
  "neo-concretism": { ...batch17Genes("neo-concretism"), period: "1959年宣言后–1960年代初，后续影响深远", year: 1960, summary: "巴西新具体主义由1959年宣言确立，反对把艺术化约为机械和知觉公式，强调身体、时间、主观经验与作品作为‘准身体’。可折叠Bichos、参与物和环境各异，不能统一为柔化的红黄蓝几何。", influencedBy: "巴西具体主义、现象学、梅洛-庞蒂、Grupo Frente及对过度理性几何的反应", influenced: "巴西参与式、身体与装置艺术，并深刻影响全球对拉丁美洲战后艺术的理解", related: ["brazilian-concretism", "concrete-art", "post-minimalism", "tropicalia"], sources: BATCH_17_SOURCES.neoConcrete },
  "hard-edge-painting": { ...batch17Genes("hard-edge-painting"), period: "名称约1959年提出；核心实践约1950年代末–1970年代", year: 1965, summary: "硬边绘画名称由评论家Jules Langsner于1959年提出，指综合色区域边界清晰、整体均等且压低笔触的抽象绘画。它与后绘画性抽象、几何抽象和综合色场相交，但并非所有几何画或胶带边缘作品都属于同一地区运动。", influencedBy: "几何抽象、综合色场、抽象表现主义反拨、丙烯颜料和美国西海岸艺术网络", influenced: "后绘画性抽象、极简视觉、平面设计及后续精确抽象", related: ["geometric-abstraction", "post-painterly-abstraction", "color-field", "minimalism"], sources: BATCH_17_SOURCES.hardEdge },
  "pattern-and-decoration": { ...batch17Genes("pattern-and-decoration"), period: "约1970年代中期–1980年代，美国为核心", year: 1980, summary: "Pattern and Decoration是1970年代美国艺术家重新肯定装饰、工艺和综合色愉悦的运动，常回应现代主义、极简和艺术/工艺等级中的性别偏见。它借鉴伊斯兰、亚洲及民间传统时也涉及挪用问题，不能将‘多文化纹样’当作可自由拼贴的无主资源。", influencedBy: "女性主义艺术、纺织与陶瓷、装饰史、Matisse、民间艺术及对极简主义和现代主义反装饰立场的批评", influenced: "当代绘画、纤维、装置、女性主义工艺复兴和装饰研究", related: ["maximalism", "feminist-art", "geometric-abstraction", "pop-art"].filter((id) => STYLE_DATA.some((style) => style.id === id)), sources: BATCH_17_SOURCES.pattern, zh: ["满幅重复、边带和层级纹样可并置，但具体文化来源必须分辨，不能做无主拼贴", "花卉、几何、贴片和手工单元按艺术家与媒介组织，不设统一装饰词汇", "高纯度多色、金属、土色或纤维本色依作品变化", "均匀展览光显示综合色与材质，局部反射来自真实陶瓷、珠饰或金属", "织物、丙烯、拼贴、陶瓷、珠饰、手工接缝及工业材料", "引用文字和文化符号必须准确且说明来源；不得伪造或混用受限传统"], en: ["all-over repetition, borders, and layered patterns may coexist, but specific cultural sources remain distinct rather than ownerless collage", "floral, geometric, appliqued, and handmade units organized by artist and medium without one ornamental vocabulary", "saturated multicolor, metallic, earth, or fiber colors varying by work", "even exhibition light revealing color and material, with local reflection coming from actual ceramic, beads, or metal", "textile, acrylic, collage, ceramic, beads, handmade seams, and industrial materials", "quoted text and cultural signs must be accurate and sourced; never fabricate or merge restricted traditions"] }
};

