const batch18Genes = (id) => {
  const style = STYLE_DATA.find((candidate) => candidate.id === id);
  if (!style || style.visualGenes.length !== 6) throw new Error(`${id}: batch 18 requires six existing genes`);
  return { zh: style.visualGenes.map((gene) => gene.zh), en: style.visualGenes.map((gene) => gene.en) };
};

const BATCH_18_REVIEWS = {
  "neo-expressionism": { period: "约1970年代末–1990年代初，地区名称不同", year: 1983, summary: "新表现主义是1970年代末至1980年代在德国、意大利、美国等地重新强调具象、历史引用和强烈绘画性的宽泛标签，各地另有Neue Wilde、Transavanguardia等名称。厚涂、粗野人物和涂写并非共同公式，市场复兴与性别偏见也是接受史的一部分。", influencedBy: "历史表现主义、战后具象绘画、朋克与都市文化、观念和极简之后的绘画回归", influenced: "1980年代绘画市场、当代具象与街头艺术，并引发对男性英雄主义和市场机制的批评", related: ["expressionism", "die-bruecke", "abstract-expressionism", "neo-pop"], sources: BATCH_18_SOURCES.neoExpressionism, zh: ["画面可满幅、分区、正面或叙事，依据艺术家建立强焦点而非统一失衡", "具象、符号和抽象形体可粗犷变形，也可使用克制或历史化轮廓", "综合色从浑浊土色到高纯度冲突不等，不固定暗底红黄蓝", "画面光服从颜料与综合色结构，写实光仅在具体作品需要时出现", "厚涂、刮擦、稀薄综合色、拼贴、油彩或丙烯的可见制作差异", "文字与符号须来自作品或准确用户内容；不伪造艺术家笔迹和签名"], en: ["all-over, zoned, frontal, or narrative structures forming strong focal relations by artist rather than one imbalance", "figures, signs, and abstract forms may be coarsely distorted, restrained, or historically inflected", "color ranging from muddy earth tones to saturated clashes without fixed dark-ground primaries", "pictorial light subordinated to paint and color structure, with observed light only where the specific work uses it", "impasto, scraping, thin color, collage, oil, or acrylic retaining visible differences of making", "words and signs must come from the work or exact user content; never fabricate an artist's handwriting or signature"] },
  "lowbrow": { period: "约1970年代末至今；‘Pop Surrealism’为相交称呼", year: 1990, summary: "Lowbrow是从南加州地下漫画、热棒、滑板、朋克、纹身和定制文化发展出的自我意识艺术网络，后来与‘Pop Surrealism’部分重叠。精细卡通、怪诞角色和珐琅表面常见，但艺术家从绘画到雕塑和玩具差异很大，不能统一为糖果色大头人物。", influencedBy: "地下漫画、Kustom Kulture、朋克、滑板、纹身、商业插画、超现实主义和大众玩具", influenced: "当代插画、艺术玩具、街头与画廊文化，以及高低艺术边界讨论", related: ["pop-art", "surrealism", "punk-visual", "neo-pop"], sources: BATCH_18_SOURCES.lowbrow, zh: ["海报、漫画、绘画、雕塑或玩具按媒介建立焦点，不固定中心头像和浅空间", "卡通、写实、怪诞和定制机械形体依艺术家变化，不强制圆润比例", "综合色可糖果鲜艳、热棒综合色、单色或暗色，不设红黑粉统一配方", "平涂、喷绘、影棚高光或绘画光按媒介选择，不一律珐琅发亮", "油彩、丙烯、喷绘、丝网、树脂、乙烯基、金属和手工线纹", "标识、漫画对白和品牌必须准确或明确虚构；不得仿造在世艺术家签名"], en: ["posters, comics, paintings, sculpture, and toys creating focal structure by medium without mandatory centered heads or shallow space", "cartoon, realist, grotesque, and custom-machine forms varying by artist without required rounded proportion", "candy, hot-rod, monochrome, or dark palettes without one red-black-pink formula", "flat fill, airbrush, studio highlight, or painterly light selected by medium without universal enamel shine", "oil, acrylic, airbrush, screenprint, resin, vinyl, metal, and handmade linework", "signs, speech text, and brands must be exact or explicitly fictional; never imitate a living artist's signature"] },
  "afrofuturism": { period: "相关实践可追溯至20世纪中期；术语由Mark Dery于1993年提出", year: 1993, summary: "Afrofuturism是从黑人历史、非洲离散经验、科技、音乐和推想叙事重新思考未来的跨媒介框架，相关实践早于1993年术语。它不等于‘非洲纹样加科幻金属’，也必须区分非洲大陆、加勒比、美国及其他离散社群的不同历史和作者位置。", influencedBy: "非洲与离散历史、黑人音乐和科幻、民权与黑人解放运动、科技政治、Sun Ra、Octavia Butler等创作者", influenced: "音乐、文学、电影、时尚、视觉艺术和关于种族、技术及未来的全球讨论", related: ["cyberpunk", "hurufiyya-movement", "tropicalia", "solarpunk"], sources: BATCH_18_SOURCES.afrofuturism, zh: ["从具体人物、社群、时间观和技术关系组织场景，可纪念、日常、抽象或叙事", "未来装置、服饰、身体与历史物件必须来自具体创作者和文化语境，不拼贴泛非符号", "综合色依音乐、电影、地区和艺术家变化，不固定黑紫金宝石色", "舞台光、日光、档案光、科幻光或平面综合色按具体媒介处理", "织物、珠饰、金属、塑料、影像、声音、档案和数字材料按作品真实组合", "语言、姓名、社群和符号必须准确；不发明非洲文字、部族身份或神圣图案"], en: ["scenes organized through specific people, communities, temporalities, and technologies, whether monumental, everyday, abstract, or narrative", "future devices, dress, bodies, and historical objects grounded in a creator and cultural context rather than pan-African symbols", "color varying by music, film, region, and artist without fixed black-purple-gold jewel tones", "stage light, daylight, archival light, speculative light, or flat color treated according to medium", "textile, beads, metal, plastic, moving image, sound, archives, and digital material combined through the actual work", "languages, names, communities, and signs must be exact; never invent African scripts, tribal identities, or sacred patterns"] },
  "biomorphic": { ...batch18Genes("biomorphic"), period: "20世纪初至今，跨艺术与设计的形态倾向", year: 1935, summary: "生物形态抽象是从细胞、器官、植物和生长过程中提炼非几何形体的宽泛倾向，常联系超现实主义和20世纪现代设计，但不是统一运动。软曲线可平面、雕塑、家具或数字化，也不必呈现半透明树脂和粉绿珊瑚综合色。", influencedBy: "自然形态研究、超现实主义自动性、现代雕塑、显微图像和有机设计", influenced: "现代雕塑与家具、有机建筑、抽象动画和数字生成形态", related: ["surrealism", "organic-architecture", "blobitecture", "geometric-abstraction"], sources: BATCH_18_SOURCES.biomorphic },
  "neo-pop": { ...batch18Genes("neo-pop"), period: "约1980年代起，宽泛评论标签", year: 1988, summary: "Neo-Pop是对1980年代以来重新使用商品、名人、玩具、漫画和品牌图像的宽泛评论标签，并非正式团体。作品可采用挪用、雕塑、摄影、装置或数字媒介；粗黑轮廓、电光原色和乙烯基光泽只代表部分艺术家。", influencedBy: "Pop Art、Pictures Generation、商品与名人文化、漫画、广告和后现代挪用", influenced: "当代商品图像、艺术玩具、品牌合作和关于消费与作者性的批评", related: ["pop-art", "pictures-generation", "lowbrow", "neo-expressionism"], sources: BATCH_18_SOURCES.neoPop },
  "naive-art": { ...batch18Genes("naive-art"), period: "19世纪末以来的分类；相关非学院实践更早并延续", year: 1900, summary: "‘稚拙艺术’是艺术史和市场对未受学院训练或有意采用直接、非学院表现的作品所用外部分类，容易把不同创作者幼儿化。平面空间和非标准比例常见但不是能力缺失；具体艺术家、地区、自我定位和专业实践必须优先说明。", influencedBy: "民间和自学艺术实践、现代主义对非学院表达的接受、收藏与画廊分类", influenced: "现代绘画、Outsider Art讨论、插画和对学院训练标准的反思", related: ["realism", "lowbrow", "tingatinga-painting", "naturalism"], sources: BATCH_18_SOURCES.naive, zh: ["叙事、肖像、风景或图案按具体艺术家组织，不预设简单前后排列", "比例、透视和轮廓应尊重艺术家选择，不将差异描述为儿童能力", "综合色随作者、材料与地区变化，不固定清澈原色", "平面光、观察光或象征性综合色按作品处理，不统一两级阴影", "油彩、水粉、铅笔、木板、纸、纤维或其他具体材料及手工痕迹", "作品文字和艺术家姓名必须准确；不模仿儿童字或以错别字制造‘天真感’"], en: ["narrative, portrait, landscape, or pattern organized by the specific artist without a preset simple front-back order", "proportion, perspective, and contour respecting artistic choice rather than framing difference as childlike incapacity", "color varying by maker, material, and place without mandatory clear primaries", "flat, observed, or symbolic chromatic light treated by work without uniform two-step shadows", "oil, gouache, pencil, panel, paper, fiber, or other specific materials and handmade traces", "work text and artist names must be exact; never imitate children's writing or use errors to manufacture naivety"] },
  "gutai-art-association": { ...batch18Genes("gutai-art-association"), period: "1954–1972年，日本关西", year: 1960, summary: "具体美术协会由吉原治良等1954年在关西创立，鼓励艺术家‘做前所未有之事’，以材料、身体、户外、舞台和技术实验重新定义绘画。撕纸、脚绘和泼洒是重要个案，但Gutai并不等同日本版行动绘画。", influencedBy: "战后日本社会、吉原治良的抽象实践、儿童美术、国际抽象和新材料", influenced: "日本及全球行为、装置、材料与跨媒介艺术的重新评价", related: ["abstract-expressionism", "zero-group", "mono-ha", "art-informel"], sources: BATCH_18_SOURCES.gutai },
  "mono-ha": { ...batch18Genes("mono-ha"), period: "约1968–1970年代初，日本", year: 1970, summary: "物派是对1968年前后日本艺术家以石、木、纸、玻璃、钢和空间关系展开实践的后设名称，成员没有统一宣言。材料常少加工，但选择、切割、支撑和场地配置仍是艺术行为，不能称作未经介入的自然物陈列。", influencedBy: "日本战后雕塑、极简与观念艺术、禅和现象学的当代解释，以及1968年前后社会语境", influenced: "日本装置与材料艺术、亚太战后艺术史及场地关系实践", related: ["minimalism", "post-minimalism", "gutai-art-association", "arte-povera"], sources: BATCH_18_SOURCES.monoHa },
  "tingatinga-painting": { ...batch18Genes("tingatinga-painting"), period: "约1968年至今，坦桑尼亚及东非传播", year: 1980, summary: "廷加廷加绘画得名于坦桑尼亚艺术家Edward Saidi Tingatinga，约1968年后在达累斯萨拉姆发展为作坊和市场网络。硬板瓷漆、动物和重复点饰常见，但后续艺术家扩展了城市、社会与幻想题材，不能当作无作者的泛非民俗画。", influencedBy: "Edward Tingatinga的实践、达累斯萨拉姆城市与旅游市场、招牌画和东非大众图像", influenced: "坦桑尼亚与东非当代大众绘画、旅游艺术和个体艺术家工作室", related: ["naive-art", "afrofuturism", "pop-art", "ndebele-house-painting"], sources: BATCH_18_SOURCES.tingatinga },
  "venetian-school": { ...batch18Genes("venetian-school"), period: "约15世纪后期–16世纪，影响延续至17世纪", year: 1550, summary: "威尼斯画派是对文艺复兴时期威尼斯及其领地画家传统的宽泛称呼，综合色、油画层染、光与空气感重要，但贝利尼、乔尔乔内、提香、丁托列托和委罗内塞的构图与笔触差异显著。它也涵盖祭坛画、肖像、神话和公共装饰。", influencedBy: "拜占庭和威尼斯综合色传统、尼德兰油画技术、文艺复兴人文主义、海上贸易与共和国委托", influenced: "欧洲巴洛克综合色与油画、鲁本斯、委拉斯开兹及后续综合色主义绘画", related: ["renaissance", "mannerism", "baroque", "flemish-baroque"], sources: BATCH_18_SOURCES.venetian },
  "sienese-school": { ...batch18Genes("sienese-school"), period: "约13世纪后期–15世纪，锡耶纳", year: 1350, summary: "锡耶纳画派在13世纪后期至15世纪发展，杜乔、洛伦采蒂兄弟、马尔蒂尼等人将拜占庭传统、哥特线性、金地和城市叙事结合。修长曲线和金箔重要，但空间、情感和世俗题材逐渐变化，不能统一为无透视圣像。", influencedBy: "拜占庭绘画、托斯卡纳板画、哥特艺术、方济各会文化和锡耶纳城市委托", influenced: "国际哥特、意大利早期文艺复兴和欧洲金地板画传统", related: ["byzantine", "italian-proto-renaissance", "international-gothic", "renaissance"], sources: BATCH_18_SOURCES.sienese },
  "flemish-baroque": { ...batch18Genes("flemish-baroque"), period: "约1600–1700年，南尼德兰", year: 1640, summary: "佛兰德巴洛克涵盖17世纪南尼德兰的宗教、宫廷、肖像、风景、静物和风俗画。鲁本斯的旋转群组和丰厚体积极具代表性，却不能覆盖凡·戴克、约尔丹斯、斯奈德斯等人的专门类型与工作室协作。", influencedBy: "意大利文艺复兴与巴洛克、天主教改革、哈布斯堡宫廷、安特卫普市场和尼德兰油画技术", influenced: "欧洲宫廷肖像、巴洛克宗教与历史画、英国和法国绘画", related: ["baroque", "venetian-school", "dutch-golden-age-painting", "spanish-golden-age-painting"], sources: BATCH_18_SOURCES.flemishBaroque },
  "dutch-golden-age-painting": { ...batch18Genes("dutch-golden-age-painting"), period: "约1600–1700年，荷兰共和国", year: 1650, summary: "17世纪荷兰共和国绘画在城市市场中形成肖像、风景、海景、风俗、静物和历史画的高度分化。窗侧光、综合色克制和精细材质是部分路线，伦勃朗、维米尔、哈尔斯及众多专门画家的笔触和光线并不统一；‘黄金时代’名称也需面对殖民贸易背景。", influencedBy: "尼德兰绘画传统、宗教与市场结构变化、城市财富、科学观察、全球贸易和殖民体系", influenced: "欧洲风俗、风景、肖像和静物画，现代现实主义与摄影式观看", related: ["baroque", "flemish-baroque", "realism", "naturalism"], sources: BATCH_18_SOURCES.dutchGolden },
  "academic-art": { ...batch18Genes("academic-art"), period: "约17–19世纪为制度高峰，学院传统延续", year: 1850, summary: "学院艺术指欧洲及其殖民和国际学院体系通过素描、历史题材等级、古典范本、竞赛与沙龙建立的教学和评价规范，而非一种无痕写实画风。不同学院、国家和世纪对综合色、题材和技法要求并不一致。", influencedBy: "文艺复兴艺术理论、法国与其他国家学院、古典艺术、宫廷和国家文化制度", influenced: "19世纪沙龙、历史画与美术教育，也成为现实主义、印象主义和现代主义反拨对象", related: ["classical-revival-architecture", "neoclassicism", "realism", "orientalist-painting"], sources: BATCH_18_SOURCES.academic },
  "naturalism": { ...batch18Genes("naturalism"), period: "约19世纪后半叶，跨文学与视觉艺术", year: 1885, summary: "视觉艺术中的自然主义强调可观察环境、身体和社会条件的可信再现，19世纪后半叶常与现实主义相交，并受文学自然主义和科学观影响。它不是一个成员固定的国际画派，也不比现实主义天然更‘照片化’。", influencedBy: "现实主义、户外写生、摄影、科学与社会观察、左拉等文学自然主义", influenced: "欧洲和美国乡村与社会题材绘画、学院改革和20世纪观察性写实", related: ["realism", "barbizon-school", "academic-art", "social-realism"], sources: BATCH_18_SOURCES.naturalism },
  "socialist-realism": { ...batch18Genes("socialist-realism"), period: "苏联1932年后确立；其他国家采用时期和形式不同", year: 1950, summary: "社会主义现实主义在苏联1932年艺术团体重组后逐步成为官方方法，并于1934年作家大会获得规范表述，随后在不同社会主义国家产生各异实践。积极英雄、劳动建设和清楚叙事常见，但媒介、国家、时期和政治压力不能被统一成仰视红金宣传画。", influencedBy: "19世纪现实主义、革命艺术、苏联文化政策、国家委托和大众传播", influenced: "苏联及相关国家的绘画、雕塑、建筑、电影和海报，同时成为非官方艺术反应与历史批评对象", related: ["realism", "social-realism", "constructivism", "mexican-muralism"], sources: BATCH_18_SOURCES.socialistRealism, zh: ["公共壁画、绘画、雕塑、电影或海报按国家、机构和任务组织叙事，不固定上升对角线", "人物可理想化、类型化或观察性表现，服饰、劳动和身份必须具体准确", "红金蓝、自然综合色、黑白或地方综合色随国家、时期和媒介变化", "纪念光、自然光、舞台光或印刷明度按作品处理，不统一轮廓辉光", "油画、壁画、青铜、石、摄影电影和印刷材料及真实制作痕迹", "口号、旗帜、语言、领袖和机构必须历史准确；不伪造政治文字或混用国家符号"], en: ["murals, paintings, sculpture, film, and posters organizing narrative through the specific country, institution, and commission without fixed rising diagonals", "figures idealized, typified, or observed, with dress, labor, and identity kept specific and accurate", "red-gold-blue, natural color, monochrome, or local palettes varying by country, period, and medium", "monumental, natural, stage, or printed light selected by work without universal rim glow", "oil, mural, bronze, stone, photography, film, and print materials retaining actual production traces", "slogans, flags, languages, leaders, and institutions must be historically exact; never fabricate political text or mix national symbols"] },
  "tropicalia": { ...batch18Genes("tropicalia"), period: "约1967–1968年为运动高峰，影响延续至1970年代及以后", year: 1968, summary: "Tropicalia/Tropicalismo是1960年代末巴西跨音乐、视觉艺术、诗歌、戏剧和电视的文化运动，以‘文化食人’策略并置本土和国际大众文化，并处于军事独裁与审查语境。综合色热带符号和媒体拼贴是手段，不是无政治内容的欢乐综合色风格。", influencedBy: "巴西现代主义食人主义、Bossa Nova、具体诗、Pop Art、电视大众文化、Oiticica和军事独裁政治", influenced: "巴西流行音乐、当代艺术、时尚和全球混杂文化理论", related: ["brazilian-concretism", "neo-concretism", "pop-art", "afrofuturism"], sources: BATCH_18_SOURCES.tropicalia },
  "hurufiyya-movement": { ...batch18Genes("hurufiyya-movement"), period: "约1950年代起，西亚、北非及离散地区多中心发展", year: 1970, summary: "Hurufiyya是对20世纪中后期西亚、北非及离散艺术家将阿拉伯字母、书写和现代抽象结合的多中心称呼，并非成员统一的正式运动。字母可保持语言、转为形体或承担身份政治；不能用随机阿拉伯线条替代准确书写。", influencedBy: "阿拉伯书法与不同地区文字传统、现代抽象、反殖民国家建构、身份与语言政治", influenced: "阿拉伯现代与当代艺术、书写抽象、离散身份和全球文字艺术", related: ["islamic-manuscript-illumination", "kufic-calligraphy-aesthetic", "abstract-expressionism", "afrofuturism"], sources: BATCH_18_SOURCES.hurufiyya, zh: ["字母、词语、书写痕迹或抽象场按具体艺术家与语言关系组织，不固定非线性碎片", "字形可清晰、断裂、重复或绘画化，但应保持来源书体与动作可辨", "综合色从黑白土色到高纯度现代综合色不等，依作品与地区变化", "平面综合色、颜料厚度、书写墨色或装置光按媒介处理", "油彩、墨、纸、拼贴、织物、雕塑和真实书写表面", "阿拉伯文及其他文字必须准确；若字母纯形式化须说明，不得生成伪经文或无义宗教书写"], en: ["letters, words, writing traces, or abstract fields organized through the specific artist and language relation without fixed nonlinear fragments", "letterforms may be clear, broken, repeated, or painterly while retaining a discernible script source and gesture", "color ranging from black-white and earth tones to saturated modern palettes by work and region", "flat color, paint relief, written ink, or installation light treated according to medium", "oil, ink, paper, collage, textile, sculpture, and actual inscribed surfaces", "Arabic and other scripts must be exact; when letters are purely formal say so, and never generate false scripture or meaningless sacred writing"] }
};

