  "cybergoth": { ...batch21Genes("cybergoth"), period: "1990年代末–2010年代初为高可见期，后续延续", year: 2005, summary: "Cybergoth在1990年代末至2000年代工业、EBM、rave与goth夜店网络中形成，以黑色基底、荧光合成材料、发束、厚底鞋与呼吸面罩式配件建立身体造型。它是特定夜店与时尚分支，不等于所有goth或赛博朋克服装，防毒面具也不应伪造安全功能。", influencedBy: "goth、industrial与EBM音乐、rave、网络科幻图像、PVC与荧光俱乐部材料", influenced: "俱乐部时尚、节日造型、网络亚文化摄影和当代复古未来服饰", related: ["gothic-subculture", "rave-aesthetic", "techno-aesthetic", "cyberpunk"], sources: BATCH_21_SOURCES.youth },
  "gyaru-aesthetic": { ...batch21Genes("gyaru-aesthetic"), period: "1990年代–2010年代为主，子类与复兴延续", year: 2000, summary: "Gyaru是1990年代后日本青年女性时尚的多分支网络，通过杂志、涩谷商业空间、手机摄影与同伴社群发展高识别妆发和服饰。Ganguro、kogyaru、hime等在肤色、廓形和阶级想象上不同，不能以深色肤色、厚底鞋与染发概括。", influencedBy: "日本青年杂志、涩谷零售、偶像与海外流行时尚、校服改造、手机和大头贴社交", influenced: "日本美妆与时尚产业、东亚网络造型、青年自我摄影与当代Y2K复兴", related: ["harajuku-street-style", "decora-kei", "japanese-i-photography", "y2k"], sources: BATCH_21_SOURCES.japaneseFashion },
  "mori-kei": { ...batch21Genes("mori-kei"), period: "2000年代后期起，网络与街头社群延续", year: 2010, summary: "Mori kei在2000年代后期日本社交网络、杂志与街头时尚中形成，以‘像生活在森林中’的想象组织宽松多层、旧化天然材料和手作配件。它是现代都市网络时尚，不是一种古老乡村传统；也不必固定米色、蕾丝和篮子。", influencedBy: "日本自然系品牌、古着、绘本与森林想象、mixi等网络社群和手作文化", influenced: "日本与国际自然系时尚、慢生活图像、手作零售与网络微美学分类", related: ["harajuku-street-style", "gothic-lolita", "wabi-sabi", "normcore"], sources: BATCH_21_SOURCES.japaneseFashion },
  "visual-kei": { ...batch21Genes("visual-kei"), period: "1980年代起，多次转型延续至今", year: 1995, summary: "Visual kei是1980年代后日本摇滚乐队以视觉表演、杂志、唱片与粉丝文化建立的宽泛场景标签，不是音乐类型或固定时尚款式。Glam、goth、punk、传统服饰与性别表演的引用随乐队和时期差异很大，不能套用一种夸张黑红造型。", influencedBy: "日本rock与metal、glam rock、punk、goth、歌舞伎和时代杂志与唱片工业", influenced: "日本音乐时尚、Gothic Lolita、东亚乐队视觉、粉丝角色扮演与当代偶像造型", related: ["glam-rock-aesthetic", "gothic-subculture", "gothic-lolita", "heavy-metal-aesthetic"], sources: BATCH_21_SOURCES.japaneseFashion },
  "dandyism": { ...batch21Genes("dandyism"), period: "18世纪末起，19世纪形成关键话语并延续", year: 1850, summary: "Dandyism是从18世纪末至19世纪欧美发展的自我塑造与社会姿态，以剪裁、保养、言行和对细节的受控选择表达现代个人性。它不等于奢侈服装或纰绔不羁，且需纳入黑人大西洋、女性与酷儿对dandy形象的重释。", influencedBy: "Beau Brummell时代英国男装、城市现代性、阶级礼仪、唯美主义、殖民与离散的服饰重释", influenced: "现代男装、流行文化、酷儿与黑人时尚、摄影肖像和关于自我表演的理论", related: ["aesthetic-movement", "flapper-style", "new-romantic-aesthetic", "glam-rock-aesthetic"], sources: BATCH_21_SOURCES.youth },
  "hippie-aesthetic": { ...batch21Genes("hippie-aesthetic"), period: "1960年代中期–1970年代，后续影响延续", year: 1969, summary: "Hippie视觉在1960年代美国反文化、反战、公社、音乐节和新左翼运动中形成，宽松服装、旧衣改造和手工刺绣常见。所谓‘民族风’常涉及对南亚、北非、美洲原住民等传统的去语境挲用，不应将无主图案作为反文化装饰。", influencedBy: "反战与民权运动、folk与rock音乐、公社生活、二手服饰、手工文化及对多地传统的选择性挲用", influenced: "自然系时尚、音乐节服饰、环保生活方式图像、新时代运动和当代boho商业风格", related: ["psychedelic", "arts-crafts", "rave-aesthetic", "mori-kei"], sources: BATCH_21_SOURCES.youth },
