function applyStrictEditorialReview(style, review) {
  if (!Array.isArray(review.en) || review.en.length !== 6) throw new Error(`${style.id}: editorial review requires six English genes`);
  const genesZh = review.zh || style.visualGenes.map((gene) => gene.zh);
  if (genesZh.length !== 6) throw new Error(`${style.id}: editorial review requires six Chinese genes`);
  style.summary = review.summary;
  if (review.period) style.period = review.period;
  if (Number.isFinite(review.year)) style.year = review.year;
  if (review.region) style.region = review.region;
  if (review.influencedBy) style.influencedBy = review.influencedBy;
  if (review.influenced) style.influenced = review.influenced;
  if (review.related) style.related = [...review.related];
  if (review.sources) style.sources = review.sources.map((source) => ({ ...source }));
  style.visualGenes = genesZh.map((zh, index) => ({ zh, en: review.en[index] }));
  style.recognition = style.visualGenes.slice(0, 5).map((gene) => gene.zh).join("；") + "。";
  style.genes.composition = [genesZh[0]];
  style.genes.form = [genesZh[1]];
  style.genes.color = [genesZh[2]];
  style.genes.type = [genesZh[5]];
  style.genes.texture = [genesZh[4]];
  style.editorialReviewed = true;
}

for (const style of STYLE_DATA) {
  const review = STRICT_STYLE_EDITORIAL_REVIEWS[style.id];
  if (review) applyStrictEditorialReview(style, review);
}

